export const SHOULDER_AUDIT_ENTRIES={"disloc":{"id":"disloc","segment":"A","edits":{"en":"Shoulder Pass-Through","eq":["light_dowel","long_light_band"],"pos":["Stůj pohodlně a drž lehkou tyč nebo dlouhou lehkou gumu širokým úchopem před stehny. Lokty nech pohodlně natažené; kolem paží i za tělem musí být volno.","Stand comfortably and hold a light dowel or long light band with a wide grip in front of the thighs. Keep the elbows comfortably straight, with space around the arms and behind the body."],"exe":["Pomalu veď obě ruce nad hlavu a podle dostupného rozsahu za tělo, potom stejnou cestou zpět před stehna. Pohyb tam a zpět je jedno opakování. Pokud celá dráha není pohodlná, vrať se dřív.","Slowly move both hands overhead and, within your available range, behind the body, then return along the same path to the thighs. Out and back is one repetition. Return earlier if the full path is not comfortable."],"wat":["Netahej přes ostrý tlak a nezískávej dráhu velkým záklonem. Úchop musí dovolit klidný pohyb obou paží; lokty nenarovnávej násilím a ramena netlač dolů za každou cenu.","Do not pull through sharp pressure or gain the path by leaning far backward. Use a grip that allows both arms to move steadily; do not force the elbows straight or hold the shoulders down at all costs."],"pro":["Lehčí: širší úchop nebo kratší oblouk. Dlouhá lehká guma může mírně povolit. Větší dráha či užší úchop jsou možnosti, pokud zůstanou pohodlné; silnější odpor není povinný další krok.","Easier: a wider grip or shorter arc. A long light band can give slightly. A longer path or narrower grip are options if comfortable; stronger resistance is not a required next step."],"foc":["Plynulý společný pohyb obou paží v pohodlném rozsahu.","Move both arms smoothly through a comfortable range."],"equipmentDetail":["Lehká dostatečně dlouhá tyč NEBO dlouhá lehká odporová guma. Krátká smyčka, těžká osa ani nucené natahování gumy nejsou stejná pomůcka.","A light dowel of adequate length OR a long light resistance band. A short loop, heavy barbell or forcibly stretching the band is not the same setup."],"source":{"author":"Mike Gettier / GettFit","document":"PVC or Band Pass Through","url":"https://www.gettfit.com/pass-through/","scope":"Public first-party technique text for a wide-grip pass-through and an earlier return if the full path is uncomfortable. Independent wording; no source dose adopted and embedded videos not viewed."}},"taxonomy":{"movements":["joint"],"focus":["mobility"],"positions":["standing"],"supports":[],"priority":1,"equipmentRequirements":[["light_dowel","long_light_band"]],"aliases":["shoulder pass through","průvlek s tyčí nebo gumou"]},"policy":{"id":"disloc","measurementType":"REPS_ONLY","loadMode":"none","sideMode":"none","requirements":[["light_dowel","long_light_band"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false},"art":{"appId":"disloc","atlasId":"disloc","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"8d7e645a1243665d93b5bdc4b5207153e43cefc050593abc39f302b6df577f2c","thumb":"/unified-atlas/disloc-c5edf2e362736365-thumb.webp","detail":"/unified-atlas/disloc-7d183b3eaba3d24f-detail.webp","inkThumb":"/unified-atlas/disloc-a5e3652d1b8f3542-inkThumb.webp","inkDetail":"/unified-atlas/disloc-24b25765aaa55f5f-inkDetail.webp","fillThumb":"/unified-atlas/disloc-cec2e213f7daa31e-fillThumb.webp","fillDetail":"/unified-atlas/disloc-44902e4ce8b9d9e8-fillDetail.webp"},"sourceSha256":"8d7e645a1243665d93b5bdc4b5207153e43cefc050593abc39f302b6df577f2c","contourOnly":true,"darkOutline":true},"libraryOrder":1000,"deliveryProfiles":{"5ca94a833b871cef":{"fields":{"id":"disloc","cz":"Průvleky ramen","en":"Shoulder Pass-Through","pat":"mobilita","eq":["light_dowel","long_light_band"],"measurementType":"REPS_ONLY","defaultRestSec":15,"unilateral":false,"sideMode":"none","focus":["Plynulý společný pohyb obou paží v pohodlném rozsahu.","Move both arms smoothly through a comfortable range."],"startPosition":["Stůj pohodlně a drž lehkou tyč nebo dlouhou lehkou gumu širokým úchopem před stehny. Lokty nech pohodlně natažené; kolem paží i za tělem musí být volno.","Stand comfortably and hold a light dowel or long light band with a wide grip in front of the thighs. Keep the elbows comfortably straight, with space around the arms and behind the body."],"execution":["Pomalu veď obě ruce nad hlavu a podle dostupného rozsahu za tělo, potom stejnou cestou zpět před stehna. Pohyb tam a zpět je jedno opakování. Pokud celá dráha není pohodlná, vrať se dřív.","Slowly move both hands overhead and, within your available range, behind the body, then return along the same path to the thighs. Out and back is one repetition. Return earlier if the full path is not comfortable."],"watchFor":["Netahej přes ostrý tlak a nezískávej dráhu velkým záklonem. Úchop musí dovolit klidný pohyb obou paží; lokty nenarovnávej násilím a ramena netlač dolů za každou cenu.","Do not pull through sharp pressure or gain the path by leaning far backward. Use a grip that allows both arms to move steadily; do not force the elbows straight or hold the shoulders down at all costs."]},"progression":["Lehčí: širší úchop nebo kratší oblouk. Dlouhá lehká guma může mírně povolit. Větší dráha či užší úchop jsou možnosti, pokud zůstanou pohodlné; silnější odpor není povinný další krok.","Easier: a wider grip or shorter arc. A long light band can give slightly. A longer path or narrower grip are options if comfortable; stronger resistance is not a required next step."]}}},"shouldercars":{"id":"shouldercars","segment":"A","edits":{"cz":"Kontrolované kroužení ramenem (CARs)","pos":["Stůj pohodlně s jednou paží podél těla. Trup drž klidný, dlaň směřuje k tělu. Loket nech pohodlně natažený a dýchej.","Stand comfortably with one arm by your side. Keep the trunk steady and the palm facing the body. Keep the elbow comfortably straight and breathe."],"exe":["Veď paži pomalu před tělem vzhůru. Postupně otáčej celou paží v rameni, aby se dlaň obracela ven, a pokračuj dozadu a dolů jen v pohodlném rozsahu. Vrať se opačnou cestou. Jeden průchod a návrat počítej pro nový plán jako jedno opakování; pak podle plánu vystřídej paži.","Slowly move the arm upward in front of the body. Gradually rotate the whole arm at the shoulder so the palm turns outward, then continue backward and down only through a comfortable range. Reverse the path to return. For a new plan, count one pass and return as one repetition; change arms as planned."],"wat":["Neotáčej celý trup za paží a rozsah nezískávej záklonem. Lopatka se při vzpažení smí přirozeně pohybovat; nesvírej ji stále dolů a dozadu. Ostrý tlak je důvod zmenšit oblouk, ne přidat sílu.","Do not turn the whole torso after the arm or gain range by leaning backward. Let the shoulder blade move naturally as the arm rises rather than pinning it down and back. Reduce the arc if there is sharp pressure instead of applying more force."],"pro":["Lehčí: menší oblouk, případně lehká opora druhé ruky pro rovnováhu. Náročnější: pomalejší kontrolovaný průchod při stejném dýchání. Přidaná zátěž není součástí této základní varianty.","Easier: a smaller arc, with light support from the other hand if balance needs it. More demanding: a slower controlled pass while breathing normally. Added weight is not part of this base version."],"foc":["Kontroluj dráhu paže i její otáčení; trup zůstává klidný.","Control both the arm path and its rotation while keeping the trunk steady."],"source":{"author":"[P]rehab","document":"Shoulder CARs","url":"https://theprehabguys.com/vimeo-video/shoulder-cars/","scope":"Public exercise notes for arm elevation, humeral rotation, reversal and a steady forward-facing trunk. Independent comfortable-range and counting instruction; embedded video not viewed. No daily dose, added load or clinical claim adopted."}},"taxonomy":{"movements":["joint"],"focus":["mobility"],"positions":["standing"],"supports":[],"priority":0,"equipmentRequirements":[["telo"]],"aliases":["kontrolovaná rotace ramene","shoulder controlled articular rotation"]},"policy":{"id":"shouldercars","measurementType":"REPS_ONLY","loadMode":"none","sideMode":"none","requirements":[["telo"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false},"art":{"appId":"shouldercars","atlasId":"shouldercars","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"66bd87557a04e1d857afa99695fb8444c78fd403b4bda463baef8306d3c68c34","thumb":"/unified-atlas/shouldercars-96ddd53eb5d26f8a-thumb.webp","detail":"/unified-atlas/shouldercars-7d0b589c042064dd-detail.webp","inkThumb":"/unified-atlas/shouldercars-59c6ba6fcd4e1f2d-inkThumb.webp","inkDetail":"/unified-atlas/shouldercars-5698aa059ae4c028-inkDetail.webp","fillThumb":"/unified-atlas/shouldercars-7211dddaf214581c-fillThumb.webp","fillDetail":"/unified-atlas/shouldercars-42af5c557812ee15-fillDetail.webp"},"sourceSha256":"66bd87557a04e1d857afa99695fb8444c78fd403b4bda463baef8306d3c68c34","contourOnly":true,"darkOutline":true},"libraryOrder":1001,"deliveryProfiles":{"ededf8d8bae61ab1":{"fields":{"id":"shouldercars","cz":"Kontrolované kroužení ramenem (CARs)","en":"Shoulder CARs","pat":"mobilita","eq":["telo"],"measurementType":"REPS_ONLY","defaultRestSec":15,"unilateral":false,"sideMode":"none","focus":["Kontroluj dráhu paže i její otáčení; trup zůstává klidný.","Control both the arm path and its rotation while keeping the trunk steady."],"startPosition":["Stůj pohodlně s jednou paží podél těla. Trup drž klidný, dlaň směřuje k tělu. Loket nech pohodlně natažený a dýchej.","Stand comfortably with one arm by your side. Keep the trunk steady and the palm facing the body. Keep the elbow comfortably straight and breathe."],"execution":["Veď paži pomalu před tělem vzhůru. Postupně otáčej celou paží v rameni, aby se dlaň obracela ven, a pokračuj dozadu a dolů jen v pohodlném rozsahu. Vrať se opačnou cestou. Jeden průchod a návrat počítej pro nový plán jako jedno opakování; pak podle plánu vystřídej paži.","Slowly move the arm upward in front of the body. Gradually rotate the whole arm at the shoulder so the palm turns outward, then continue backward and down only through a comfortable range. Reverse the path to return. For a new plan, count one pass and return as one repetition; change arms as planned."],"watchFor":["Neotáčej celý trup za paží a rozsah nezískávej záklonem. Lopatka se při vzpažení smí přirozeně pohybovat; nesvírej ji stále dolů a dozadu. Ostrý tlak je důvod zmenšit oblouk, ne přidat sílu.","Do not turn the whole torso after the arm or gain range by leaning backward. Let the shoulder blade move naturally as the arm rises rather than pinning it down and back. Reduce the arc if there is sharp pressure instead of applying more force."]},"progression":["Lehčí: menší oblouk, případně lehká opora druhé ruky pro rovnováhu. Náročnější: pomalejší kontrolovaný průchod při stejném dýchání. Přidaná zátěž není součástí této základní varianty.","Easier: a smaller arc, with light support from the other hand if balance needs it. More demanding: a slower controlled pass while breathing normally. Added weight is not part of this base version."]}}},"wallext":{"id":"wallext","segment":"A","edits":{"cz":"Posun paží po zdi zády ke stěně","pos":["Postav se zády ke zdi, chodidla mírně před ní. Opři se pohodlně a zvedni pokrčené paže do tvaru W. Lokty a hřbety rukou přibliž ke zdi podle možností, bez násilného přitlačení.","Stand with your back to a wall and feet slightly forward. Rest comfortably against it and bring the bent arms into a W. Bring the elbows and backs of the hands toward the wall as available without forcing contact."],"exe":["Pomalu posouvej paže vzhůru k tvaru Y a vrať se do W. Zdvih a návrat jsou jedno opakování. Skonči dřív, pokud by další výška vyžadovala výrazné prohnutí nebo tlak v rameni.","Slowly slide the arms upward toward a Y and return to the W. One raise and return is one repetition. Stop earlier if more height requires marked back arching or shoulder pressure."],"wat":["Celá záda, lokty ani zápěstí nemusí být zároveň přitisknuté. Nevtlačuj bedra silou do zdi. Dýchej a nech lopatky pohybovat s pažemi; výška rukou není měřítko úspěchu.","The whole back, elbows and wrists do not have to press against the wall at once. Do not force the lower back flat. Breathe and let the shoulder blades move with the arms; hand height is not a success score."],"pro":["Lehčí: menší dráha nebo nižší výchozí W. Dále můžeš rozsah pozvolna zvětšit, pokud zůstává pohodlný. Natažené lokty a úplný kontakt se zdí nejsou povinný cíl.","Easier: a shorter path or lower starting W. You may gradually expand the range if it stays comfortable. Straight elbows and full wall contact are not required goals."],"foc":["Pohodlný posun paží vzhůru a zpět bez vynuceného kontaktu se zdí.","Slide the arms up and back comfortably without forcing wall contact."],"source":{"author":"Hospital for Special Surgery / Hannah Solomon","document":"Wall angels — comfortable-range modifications","url":"https://news.hss.edu/want-to-stop-slouching-this-is-the-move-your-exercise-routine-is-missing/","scope":"First-party clinical contributor summary supports a smaller comfortable wall-angel range. The exact W-to-Y setup is independent coaching consistent with the existing card and illustration; posture-correction claims and the linked third-party full article are not adopted."}},"taxonomy":{"movements":["joint"],"focus":["mobility"],"positions":["standing"],"supports":["wall"],"priority":1,"equipmentRequirements":[["zed"]],"aliases":["wall angel","wall W to Y","anděl zády ke zdi"]},"policy":{"id":"wallext","measurementType":"REPS_ONLY","loadMode":"none","sideMode":"none","requirements":[["zed"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false,"blockedMotionSources":["/exercise-motion/wallext-ef4aa12481a1b8ec.mp4"]},"art":{"appId":"wallext","atlasId":"wallext","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"a1407b248e4651dee46c0818e5f37c349ffbc0c7ab7366b8c65b50021d22c363","thumb":"/unified-atlas/wallext-ccb9eb9ce8dcae2a-thumb.webp","detail":"/unified-atlas/wallext-262e286a4799f412-detail.webp","inkThumb":"/unified-atlas/wallext-83059f38873b1840-inkThumb.webp","inkDetail":"/unified-atlas/wallext-293a0060d366c590-inkDetail.webp","fillThumb":"/unified-atlas/wallext-0c2e99b70977bbb4-fillThumb.webp","fillDetail":"/unified-atlas/wallext-e87ebf603e88b311-fillDetail.webp"},"sourceSha256":"a1407b248e4651dee46c0818e5f37c349ffbc0c7ab7366b8c65b50021d22c363","contourOnly":true,"darkOutline":true},"libraryOrder":1002,"deliveryProfiles":{"808d34864507771c":{"fields":{"id":"wallext","cz":"Posun paží po zdi zády ke stěně","en":"Wall Extensions","pat":"mobilita","eq":["zed"],"measurementType":"REPS_ONLY","defaultRestSec":15,"unilateral":false,"sideMode":"none","focus":["Pohodlný posun paží vzhůru a zpět bez vynuceného kontaktu se zdí.","Slide the arms up and back comfortably without forcing wall contact."],"startPosition":["Postav se zády ke zdi, chodidla mírně před ní. Opři se pohodlně a zvedni pokrčené paže do tvaru W. Lokty a hřbety rukou přibliž ke zdi podle možností, bez násilného přitlačení.","Stand with your back to a wall and feet slightly forward. Rest comfortably against it and bring the bent arms into a W. Bring the elbows and backs of the hands toward the wall as available without forcing contact."],"execution":["Pomalu posouvej paže vzhůru k tvaru Y a vrať se do W. Zdvih a návrat jsou jedno opakování. Skonči dřív, pokud by další výška vyžadovala výrazné prohnutí nebo tlak v rameni.","Slowly slide the arms upward toward a Y and return to the W. One raise and return is one repetition. Stop earlier if more height requires marked back arching or shoulder pressure."],"watchFor":["Celá záda, lokty ani zápěstí nemusí být zároveň přitisknuté. Nevtlačuj bedra silou do zdi. Dýchej a nech lopatky pohybovat s pažemi; výška rukou není měřítko úspěchu.","The whole back, elbows and wrists do not have to press against the wall at once. Do not force the lower back flat. Breathe and let the shoulder blades move with the arms; hand height is not a success score."]},"progression":["Lehčí: menší dráha nebo nižší výchozí W. Dále můžeš rozsah pozvolna zvětšit, pokud zůstává pohodlný. Natažené lokty a úplný kontakt se zdí nejsou povinný cíl.","Easier: a shorter path or lower starting W. You may gradually expand the range if it stays comfortable. Straight elbows and full wall contact are not required goals."]}}},"ex26_supine_armraise":{"id":"ex26_supine_armraise","segment":"A","edits":{"exe":["Pomalu přenes natažené paže z polohy podél těla nad hlavu a vrať je. Zdvih a návrat obou paží jsou jedno opakování. Zastav tam, kde ještě udržíš žebra a pánev klidné.","Slowly raise the straight arms from beside the body toward overhead, then return. Raising and returning both arms is one repetition. Stop while the ribs and pelvis remain steady."],"equipmentDetail":["Vlastní váha a pohodlná pevná podlaha; podložka je volitelná. Hlava a trup zůstávají opřené. Každá paže se pohybuje sama, druhá jí nepomáhá.","Bodyweight on a comfortable firm floor; a mat is optional. Keep the head and trunk supported. Each arm moves actively without assistance from the other."]},"taxonomy":{"movements":["joint"],"focus":["mobility","coordination"],"positions":["supine"],"supports":[],"priority":1,"equipmentRequirements":[["telo"]]},"policy":{"id":"ex26_supine_armraise","measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"none","requirements":[["telo"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false,"blockedMotionSources":["/exercise-motion/ex26_supine_armraise-0eeb5999cc35cf8d.mp4"]},"art":{"appId":"ex26_supine_armraise","atlasId":"ex26_supine_armraise","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"710ec4126508bd42738e9e917c57477e2b92191ed31f08ffde4b8b12c6bb78bf","thumb":"/expansion-atlas/ex26_supine_armraise-original-256.webp","detail":"/expansion-atlas/ex26_supine_armraise-original-960.webp","inkThumb":"/expansion-atlas/ex26_supine_armraise-ink-256.webp","inkDetail":"/expansion-atlas/ex26_supine_armraise-ink-960.webp","fillThumb":"/expansion-atlas/ex26_supine_armraise-fill-256.webp","fillDetail":"/expansion-atlas/ex26_supine_armraise-fill-960.webp"},"sourceSha256":"710ec4126508bd42738e9e917c57477e2b92191ed31f08ffde4b8b12c6bb78bf","contourOnly":true,"darkOutline":true},"libraryOrder":1003,"deliveryProfiles":{"6297cf2582630a35":{"fields":{"id":"ex26_supine_armraise","cz":"Vzpažení vleže s kontrolou žeber","en":"Supine Shoulder Flexion","pat":"mobilita","eq":["telo"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":90,"unilateral":false,"sideMode":"none","focus":["Pomalu přenes natažené paže nad hlavu a zpět.","Slowly raise straight arms overhead and back."],"startPosition":["Lehni na záda, pokrč kolena, paže polož vedle těla s dlaněmi dovnitř.","Lie supine with knees bent and arms beside the body, palms inward."],"execution":["Pomalu přenes natažené paže z polohy podél těla nad hlavu a vrať je. Zdvih a návrat obou paží jsou jedno opakování. Zastav tam, kde ještě udržíš žebra a pánev klidné.","Slowly raise the straight arms from beside the body toward overhead, then return. Raising and returning both arms is one repetition. Stop while the ribs and pelvis remain steady."],"watchFor":["Kontakt rukou se zemí není podmínkou. Nezískávej rozsah prohnutím beder.","Touching the floor overhead is optional. Do not gain range by arching the lower back."]},"progression":["Lehčí: jedna paže nebo pokrčené lokty. Těžší: postupně větší aktivní rozsah bez pohybu žeber.","Easier: move one arm or bend the elbows. Harder: gradually increase active range without rib movement."]}}},"ex26_snow_angel":{"id":"ex26_snow_angel","segment":"A","edits":{"exe":["Posouvej paže obloukem podél podložky směrem nad hlavu a zpět, jako při kreslení anděla. Celý oblouk tam a zpět je jedno opakování; ruce se nad hlavou nemusí spojit.","Sweep the arms along an arc near the floor toward overhead and back, as if making a snow angel. The outward arc and return together are one repetition; the hands need not meet overhead."],"equipmentDetail":["Vlastní váha na pevné podlaze, podložka volitelná. Hlava a trup zůstávají opřené; kontakt rukou, loktů a zápěstí se zemí nevynucuj.","Bodyweight on a firm floor, with an optional mat. Keep the head and trunk supported without forcing the hands, elbows or wrists onto the floor."]},"taxonomy":{"movements":["joint"],"focus":["mobility","coordination"],"positions":["supine"],"supports":[],"priority":1,"equipmentRequirements":[["telo"]]},"policy":{"id":"ex26_snow_angel","measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"none","requirements":[["telo"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false,"blockedMotionSources":["/exercise-motion/ex26_snow_angel-e4b2c791ba904336.mp4"]},"art":{"appId":"ex26_snow_angel","atlasId":"ex26_snow_angel","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"e24898d985474c90869b01a1545be69d2e63993ef8044d91ef814fcc8bd682a3","thumb":"/expansion-atlas/ex26_snow_angel-original-256.webp","detail":"/expansion-atlas/ex26_snow_angel-original-960.webp","inkThumb":"/expansion-atlas/ex26_snow_angel-ink-256.webp","inkDetail":"/expansion-atlas/ex26_snow_angel-ink-960.webp","fillThumb":"/expansion-atlas/ex26_snow_angel-fill-256.webp","fillDetail":"/expansion-atlas/ex26_snow_angel-fill-960.webp"},"sourceSha256":"e24898d985474c90869b01a1545be69d2e63993ef8044d91ef814fcc8bd682a3","contourOnly":true,"darkOutline":true},"libraryOrder":1004,"deliveryProfiles":{"237045e0d935103a":{"fields":{"id":"ex26_snow_angel","cz":"Anděl s pažemi vleže na zádech","en":"Supine Snow Angel","pat":"mobilita","eq":["telo"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":90,"unilateral":false,"sideMode":"none","focus":["Posouvej paže obloukem podél podložky nad hlavu a zpět, jako při kreslení anděla.","Sweep the arms along an arc toward overhead and back, as if making a snow angel."],"startPosition":["Lehni na záda s pokrčenými koleny. Paže dej mírně od těla a lokty pohodlně pokrč.","Lie supine with knees bent, arms slightly away from the body and elbows comfortably bent."],"execution":["Posouvej paže obloukem podél podložky směrem nad hlavu a zpět, jako při kreslení anděla. Celý oblouk tam a zpět je jedno opakování; ruce se nad hlavou nemusí spojit.","Sweep the arms along an arc near the floor toward overhead and back, as if making a snow angel. The outward arc and return together are one repetition; the hands need not meet overhead."],"watchFor":["Netlač zápěstí ani lokty silou k zemi. Žebra se nezvedají.","Do not force wrists or elbows to the floor. Keep the ribs settled."]},"progression":["Lehčí: kratší oblouk. Těžší: plynule delší oblouk a menší pokrčení loktů.","Easier: shorten the arc. Harder: gradually lengthen it and reduce elbow bend."]}}},"ex26_mob_pendulum":{"id":"ex26_mob_pendulum","segment":"A","edits":{"eq":["fixed_support"],"exe":["Malým přenášením váhy rozkývej uvolněnou paži vpřed a vzad, případně do malých kruhů. Pro jednu sérii zvol jeden vzor: celý pohyb vpřed a zpět NEBO jeden kruh je jedno opakování. Kruhy proveď podle plánu oběma směry a potom vystřídej volnou paži.","Use small body-weight shifts to move the relaxed arm forward and back, or in small circles. Choose one pattern per set: a full forward-and-back swing OR one circle is one repetition. Perform circles in both directions as planned, then change the hanging arm."],"equipmentDetail":["Pevný stůl, pult nebo jiná stabilní opora ruky ve výšce umožňující pohodlný předklon. Volná paže musí mít prostor pro malý pohyb; nedrží závaží.","A firm table, counter or another stable hand support at a height that permits a comfortable hinge. Leave room for the hanging arm to move through a small arc without holding a weight."]},"taxonomy":{"movements":["joint"],"focus":["mobility"],"positions":["standing"],"supports":["hand_support"],"priority":1,"equipmentRequirements":[["fixed_support","stable_table"]],"aliases":["shoulder pendulum","kyvadlo uvolněnou paží"]},"policy":{"id":"ex26_mob_pendulum","measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"perSide","requirements":[["fixed_support","stable_table"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false,"blockedMotionSources":["/exercise-motion/ex26_mob_pendulum-f54c2761c088736b.mp4"],"sideMeaning":["Volná paže","Hanging arm"]},"art":{"appId":"ex26_mob_pendulum","atlasId":"ex26_mob_pendulum","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"5faad2c31b06f62265da832967658117b111daef8074165f30a62af7fef51eb1","thumb":"/expansion-atlas/ex26_mob_pendulum-original-256.webp","detail":"/expansion-atlas/ex26_mob_pendulum-original-960.webp","inkThumb":"/expansion-atlas/ex26_mob_pendulum-ink-256.webp","inkDetail":"/expansion-atlas/ex26_mob_pendulum-ink-960.webp","fillThumb":"/expansion-atlas/ex26_mob_pendulum-fill-256.webp","fillDetail":"/expansion-atlas/ex26_mob_pendulum-fill-960.webp"},"sourceSha256":"5faad2c31b06f62265da832967658117b111daef8074165f30a62af7fef51eb1","contourOnly":true,"darkOutline":true},"libraryOrder":1005,"deliveryProfiles":{"414595812c10a7bc":{"fields":{"id":"ex26_mob_pendulum","cz":"Uvolněné kyvadlo paže s oporou","en":"Supported Shoulder Pendulum","pat":"mobilita","eq":["fixed_support"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":15,"unilateral":true,"sideMode":"perSide","focus":["Malým přenášením váhy rozkývej uvolněnou paži vpřed, vzad a do malých kruhů.","Use small body-weight shifts to swing the relaxed arm forward, backward and in small circles."],"startPosition":["Jednou rukou se opři o pevný stůl, mírně pokrč kolena a předkloň se z kyčlí. Druhou paži nech volně viset.","Support one hand on a firm table, soften the knees and hinge forward, letting the other arm hang loosely."],"execution":["Malým přenášením váhy rozkývej uvolněnou paži vpřed a vzad, případně do malých kruhů. Pro jednu sérii zvol jeden vzor: celý pohyb vpřed a zpět NEBO jeden kruh je jedno opakování. Kruhy proveď podle plánu oběma směry a potom vystřídej volnou paži.","Use small body-weight shifts to move the relaxed arm forward and back, or in small circles. Choose one pattern per set: a full forward-and-back swing OR one circle is one repetition. Perform circles in both directions as planned, then change the hanging arm."],"watchFor":["Paží aktivně nemáchej a kruh nezvětšuj přes bolest.","Do not actively fling the arm or enlarge the circle into pain."]},"progression":["Lehčí: nepatrný pohyb s oporou. Dále: postupně zvětši pohodlný oblouk při stále uvolněné paži, bez přidané zátěže.","Easier: use tiny movements with support. Progress by gradually increasing the comfortable arc while the arm stays relaxed, without adding weight."]}}},"ex26_mob_table_slide":{"id":"ex26_mob_table_slide","segment":"A","edits":{"eq":["stable_table","chair","towel"],"exe":["Posouvej obě ruce po ručníku vpřed a současně předkloň trup z kyčlí. Vrať se bez prudkého přitažení ramen. Posun obou rukou a návrat je jedno opakování.","Slide both hands forward on the towel while hinging the trunk from the hips. Return without jerking the shoulders. One slide of both hands and return is one repetition."],"wat":["Chodidla nech opřená a ramena netlač silou dolů ani k uším. Skonči před ostrým tlakem v rameni; většího dosahu nedosahuj propadem hrudníku nebo páčením paží.","Keep the feet supported and do not force the shoulders down or up toward the ears. Stop before sharp shoulder pressure; do not gain reach by collapsing the chest or levering the arms."],"pro":["Lehčí: kratší posun a větší opora předloktí o stůl. Dále můžeš postupně prodloužit pohodlnou dráhu. Aktivní vzpažení bez stolu je jiný způsob úkolu, ne povinný další stupeň.","Easier: a shorter slide with more forearm support on the table. You may gradually lengthen the comfortable path. Active elevation without the table is a different task setup, not a required next level."],"equipmentDetail":["Pevná židle A stabilní stůl s hladkou plochou A ručník, který po ní klouže. Výška musí umožnit opřít ruce a chodidla. Samotná lavice nebo bedna neprokazuje celé vybavení.","A stable chair AND a firm table with a smooth surface AND a towel that slides on it. The height must allow supported hands and feet. A bench or box alone does not establish the full setup."]},"taxonomy":{"movements":["joint"],"focus":["mobility"],"positions":["seated"],"supports":["hand_support","chair_bench"],"priority":1,"equipmentRequirements":[["stable_table"],["chair"],["towel"]]},"policy":{"id":"ex26_mob_table_slide","measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"none","requirements":[["stable_table"],["chair"],["towel"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false,"blockedMotionSources":["/exercise-motion/ex26_mob_table_slide-eb8e5947fd63e5ca.mp4"]},"art":{"appId":"ex26_mob_table_slide","atlasId":"ex26_mob_table_slide","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"07769b089f5703d97c9b37501ddb74021b210ab8e3f786a5be638bfadfd6673c","thumb":"/expansion-atlas/ex26_mob_table_slide-original-256.webp","detail":"/expansion-atlas/ex26_mob_table_slide-original-960.webp","inkThumb":"/expansion-atlas/ex26_mob_table_slide-ink-256.webp","inkDetail":"/expansion-atlas/ex26_mob_table_slide-ink-960.webp","fillThumb":"/expansion-atlas/ex26_mob_table_slide-fill-256.webp","fillDetail":"/expansion-atlas/ex26_mob_table_slide-fill-960.webp"},"sourceSha256":"07769b089f5703d97c9b37501ddb74021b210ab8e3f786a5be638bfadfd6673c","contourOnly":true,"darkOutline":true},"libraryOrder":1006,"deliveryProfiles":{"ca1c7befc49291f8":{"fields":{"id":"ex26_mob_table_slide","cz":"Posun paží po stole do vzpažení","en":"Seated Shoulder Table Slide","pat":"mobilita","eq":["stable_table","chair","towel"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":15,"unilateral":false,"sideMode":"none","focus":["Posouvej ruce vpřed a současně předkloň trup z kyčlí.","Slide hands forward while hinging the trunk from the hips, then return without jerking the shoulders."],"startPosition":["Sedni si ke stolu a polož dlaně na ručník. Lokty jsou pohodlně natažené.","Sit at a table with palms on a towel and elbows comfortably extended."],"execution":["Posouvej obě ruce po ručníku vpřed a současně předkloň trup z kyčlí. Vrať se bez prudkého přitažení ramen. Posun obou rukou a návrat je jedno opakování.","Slide both hands forward on the towel while hinging the trunk from the hips. Return without jerking the shoulders. One slide of both hands and return is one repetition."],"watchFor":["Chodidla nech opřená a ramena netlač silou dolů ani k uším. Skonči před ostrým tlakem v rameni; většího dosahu nedosahuj propadem hrudníku nebo páčením paží.","Keep the feet supported and do not force the shoulders down or up toward the ears. Stop before sharp shoulder pressure; do not gain reach by collapsing the chest or levering the arms."]},"progression":["Lehčí: kratší posun a větší opora předloktí o stůl. Dále můžeš postupně prodloužit pohodlnou dráhu. Aktivní vzpažení bez stolu je jiný způsob úkolu, ne povinný další stupeň.","Easier: a shorter slide with more forearm support on the table. You may gradually lengthen the comfortable path. Active elevation without the table is a different task setup, not a required next level."]}}},"ex26_mob_supine_assisted_raise":{"id":"ex26_mob_supine_assisted_raise","segment":"A","edits":{"exe":["Pomalu veď spojené ruce od polohy nad hrudníkem směrem za hlavu do pohodlného rozsahu a vrať. Druhá paže může jemně pomáhat té, kterou chceš procvičit. Společný zdvih a návrat je jedno opakování.","Slowly move the clasped hands from above the chest toward overhead through a comfortable range, then return. The other arm can gently assist the one you want to practise. One combined raise and return is one repetition."],"equipmentDetail":["Bez povinné pomůcky; podložka je volitelná. Hlava a trup zůstávají opřené. Dopomoc druhé paže nemá přetlačovat pohodlný rozsah.","No required equipment; a mat is optional. Keep the head and trunk supported. Assistance from the other arm should not force the available comfortable range."]},"taxonomy":{"movements":["joint"],"focus":["mobility"],"positions":["supine"],"supports":["assisted"],"priority":1,"equipmentRequirements":[["telo"]]},"policy":{"id":"ex26_mob_supine_assisted_raise","measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"none","requirements":[["telo"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false,"blockedMotionSources":["/exercise-motion/ex26_mob_supine_assisted_raise-fcd63601be33a385.mp4"]},"art":{"appId":"ex26_mob_supine_assisted_raise","atlasId":"ex26_mob_supine_assisted_raise","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"1d58338ba5f16d10bc9d5623ab0e7036c09de6f39e2f5968288c63efdbc93196","thumb":"/expansion-atlas/ex26_mob_supine_assisted_raise-original-256.webp","detail":"/expansion-atlas/ex26_mob_supine_assisted_raise-original-960.webp","inkThumb":"/expansion-atlas/ex26_mob_supine_assisted_raise-ink-256.webp","inkDetail":"/expansion-atlas/ex26_mob_supine_assisted_raise-ink-960.webp","fillThumb":"/expansion-atlas/ex26_mob_supine_assisted_raise-fill-256.webp","fillDetail":"/expansion-atlas/ex26_mob_supine_assisted_raise-fill-960.webp"},"sourceSha256":"1d58338ba5f16d10bc9d5623ab0e7036c09de6f39e2f5968288c63efdbc93196","contourOnly":true,"darkOutline":true},"libraryOrder":1007,"deliveryProfiles":{"e4998f8af443ccc6":{"fields":{"id":"ex26_mob_supine_assisted_raise","cz":"Asistované vzpažení vleže se spojenými dlaněmi","en":"Supine Clasped-Hand Shoulder Elevation","pat":"mobilita","eq":["telo"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":15,"unilateral":false,"sideMode":"none","focus":["Pomalu veď spojené ruce za hlavu do pohodlného rozsahu a vrať.","Slowly move the joined hands overhead through a comfortable range and return."],"startPosition":["Lehni na záda s pokrčenými koleny. Spoj dlaně před hrudníkem.","Lie supine with knees bent and clasp hands above the chest."],"execution":["Pomalu veď spojené ruce od polohy nad hrudníkem směrem za hlavu do pohodlného rozsahu a vrať. Druhá paže může jemně pomáhat té, kterou chceš procvičit. Společný zdvih a návrat je jedno opakování.","Slowly move the clasped hands from above the chest toward overhead through a comfortable range, then return. The other arm can gently assist the one you want to practise. One combined raise and return is one repetition."],"watchFor":["Neprohýbej záda, abys dosáhl rukama na podlahu. Dotyk země není nutný.","Do not arch the back to reach the floor. Floor contact is unnecessary."]},"progression":["Lehčí: více pokrč lokty. Těžší: méně pomoci a pomalejší návrat.","Easier: bend elbows more. Harder: use less assistance and a slower return."]}}},"ex26_mob_finger_wallclimb":{"id":"ex26_mob_finger_wallclimb","segment":"A","edits":{"exe":["Postupně posouvej prsty jedné ruky vzhůru do pohodlné výšky. Přibliž tělo ke zdi podle potřeby a potom stejným způsobem sestup. Celý výstup a sestup je jedno opakování na pracovní paži; nepočítej jednotlivé kroky prstů. Po sérii vystřídej ruku.","Walk the fingers of one hand upward to a comfortable height. Move the body nearer the wall as needed, then walk them back down. The full climb and descent is one repetition for the working arm; do not count individual finger steps. Change hands after the set."],"pro":["Lehčí: kratší dráha a nižší výchozí poloha ruky. Dále můžeš rozsah prodloužit při stejném klidném trupu. Odlepení ruky od zdi je jiný aktivní úkol, není povinnou součástí tohoto vyšlapávání.","Easier: a shorter path and lower starting hand position. You may extend the range while keeping the trunk steady. Lifting the hand away is a different active task, not a required part of this wall climb."],"foc":["Vyšlapej prsty pohodlně vzhůru a kontrolovaně se vrať.","Walk the fingers upward comfortably, then return with control."]},"taxonomy":{"movements":["joint"],"focus":["mobility"],"positions":["standing"],"supports":["wall","assisted"],"priority":1,"equipmentRequirements":[["zed"]]},"policy":{"id":"ex26_mob_finger_wallclimb","measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"perSide","requirements":[["zed"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false,"sideMeaning":["Pohybující se paže","Moving arm"]},"art":{"appId":"ex26_mob_finger_wallclimb","atlasId":"ex26_mob_finger_wallclimb","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"3995288a3bf48d3532df7e4c6da0cc00dccede87d04c7aec9ffa87b2f513bb7f","thumb":"/expansion-atlas/ex26_mob_finger_wallclimb-original-256.webp","detail":"/expansion-atlas/ex26_mob_finger_wallclimb-original-960.webp","inkThumb":"/expansion-atlas/ex26_mob_finger_wallclimb-ink-256.webp","inkDetail":"/expansion-atlas/ex26_mob_finger_wallclimb-ink-960.webp","fillThumb":"/expansion-atlas/ex26_mob_finger_wallclimb-fill-256.webp","fillDetail":"/expansion-atlas/ex26_mob_finger_wallclimb-fill-960.webp"},"sourceSha256":"3995288a3bf48d3532df7e4c6da0cc00dccede87d04c7aec9ffa87b2f513bb7f","contourOnly":true,"darkOutline":true},"libraryOrder":1008,"deliveryProfiles":{"a1b7e41ed11eab01":{"fields":{"id":"ex26_mob_finger_wallclimb","cz":"Postupné vyšlapávání prsty po zdi","en":"Finger Wall Climb","pat":"mobilita","eq":["zed"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":15,"unilateral":true,"sideMode":"perSide","focus":["Vyšlapej prsty pohodlně vzhůru a kontrolovaně se vrať.","Walk the fingers upward comfortably, then return with control."],"startPosition":["Stůj čelem ke zdi, prsty jedné ruky o ni lehce opři před ramenem.","Face a wall with fingertips of one hand lightly touching it in front of the shoulder."],"execution":["Postupně posouvej prsty jedné ruky vzhůru do pohodlné výšky. Přibliž tělo ke zdi podle potřeby a potom stejným způsobem sestup. Celý výstup a sestup je jedno opakování na pracovní paži; nepočítej jednotlivé kroky prstů. Po sérii vystřídej ruku.","Walk the fingers of one hand upward to a comfortable height. Move the body nearer the wall as needed, then walk them back down. The full climb and descent is one repetition for the working arm; do not count individual finger steps. Change hands after the set."],"watchFor":["Nezadržuj dech a nesnaž se dosáhnout výš záklonem.","Keep breathing and avoid gaining height by leaning backward."]},"progression":["Lehčí: kratší dráha a nižší výchozí poloha ruky. Dále můžeš rozsah prodloužit při stejném klidném trupu. Odlepení ruky od zdi je jiný aktivní úkol, není povinnou součástí tohoto vyšlapávání.","Easier: a shorter path and lower starting hand position. You may extend the range while keeping the trunk steady. Lifting the hand away is a different active task, not a required part of this wall climb."]}}},"extrot":{"id":"extrot","segment":"B","edits":{"cz":"Zevní rotace ramene s ukotvenou gumou","en":"Standing Shoulder External Rotation with Anchored Band","hd":null,"pos":["Upevni lehkou odporovou gumu k pevné kotvě přibližně ve výšce lokte. Postav se bokem, procvičovanou paží dál od kotvy. Loket nech u boku, pokrčený přibližně do pravého úhlu; mezi nadloktí a trup můžeš vložit složený ručník.","Secure a light resistance band to a fixed anchor roughly at elbow height. Stand sideways with the working arm farther from the anchor. Keep the elbow beside the trunk, bent roughly to a right angle; a folded towel between the upper arm and trunk is optional."],"exe":["Otáčej pažní kost zevně v rameni: ruka a předloktí se pohybují od břicha ven, loket zůstává přibližně na místě. Pomalu se vrať. Otočení ven a návrat tvoří jedno opakování; po plánované sérii vystřídej paži.","Rotate the upper arm outward at the shoulder: the hand and forearm move away from the abdomen while the elbow stays roughly in place. Return slowly. One outward rotation and return is one repetition; change arms after the planned set."],"wat":["Neotáčej trup místo paže a neohýbej zápěstí, abys došel dál. Rameno nemusíš silou tlačit dolů ani lopatku svírat k páteři. Zvol odpor a rozsah, ve kterých pohyb ovládáš bez nepříjemného tlaku.","Do not turn the trunk instead of the arm or bend the wrist to reach farther. You do not need to force the shoulder downward or squeeze the shoulder blade against the spine. Choose resistance and range you can control without uncomfortable pressure."],"pro":["Lehčí: menší napětí gumy nebo rozsah. Podle potřeby změň odpor či zpomal návrat při stejné poloze. Silnější guma není povinný další krok a přítah k obličeji není stejný úkol.","Easier: less band tension or a smaller range. Adjust resistance or slow the return as needed while keeping the same setup. A stronger band is not a required next step, and a face pull is a different task."],"foc":["Rotace vzniká v rameni; předloktí ukazuje směr pohybu.","Rotation occurs at the shoulder; the forearm shows its direction."],"equipmentDetail":["Odporová guma a pevná kotva přibližně ve výšce lokte; ručník u boku je volitelný. Zapisuj opakování, typ gumy a napnutí do poznámky. Původní záznamy bez strany nepřeváděj na pravou či levou a neměň jejich způsob počítání.","Resistance band and a fixed anchor roughly at elbow height; the towel at the side is optional. Record repetitions and note the band and tension. Do not convert old unspecified-side records into right or left, or change their counting convention."],"source":{"author":"American Academy of Orthopaedic Surgeons","document":"Rotator Cuff and Shoulder Conditioning Program — External Rotation","url":"https://www.orthoinfo.org/recovery/rotator-cuff-and-shoulder-conditioning-program/","scope":"Public method text supports an anchored band, elbow beside the trunk and rotation at the shoulder. Independent coaching language and repetition definition; no rehabilitation prescription, fixed tempo or automatic progression is imported."}},"taxonomy":{"regions":["shoulders"],"secondaryRegions":["back"],"movements":["joint"],"focus":["strength"],"positions":["standing"],"supports":[],"priority":0,"equipmentRequirements":[["guma"],["fixed_anchor"]],"aliases":["zevní rotace s gumou","vnější rotace s gumou","band shoulder external rotation"]},"policy":{"id":"extrot","measurementType":"REPS_ONLY","loadMode":"none","sideMode":"none","requirements":[["guma"],["fixed_anchor"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false,"familyOverride":"shoulder_external_rotation","blockedMotionSources":[]},"art":{"appId":"extrot","atlasId":"extrot","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"1ba1cba65c04065d0a5f93ebe2e9499ca5fe8e5204dca2558eaca1cc477fa6a6","thumb":"/unified-atlas/extrot-ce5d3e3212dfa4ed-thumb.webp","detail":"/unified-atlas/extrot-7eb160844e672a40-detail.webp","inkThumb":"/unified-atlas/extrot-e934897c00236220-inkThumb.webp","inkDetail":"/unified-atlas/extrot-61b2002a94cf1f23-inkDetail.webp","fillThumb":"/unified-atlas/extrot-4c3e568d5c0a3e89-fillThumb.webp","fillDetail":"/unified-atlas/extrot-5dc31f0f0e1a2545-fillDetail.webp"},"sourceSha256":"1ba1cba65c04065d0a5f93ebe2e9499ca5fe8e5204dca2558eaca1cc477fa6a6","contourOnly":true,"darkOutline":true},"libraryOrder":3000,"deliveryProfiles":{"25ec2c4aa4294ddc":{"fields":{"id":"extrot","cz":"Zevní rotace ramene s ukotvenou gumou","en":"Standing Shoulder External Rotation with Anchored Band","pat":"tah","eq":["guma"],"measurementType":"REPS_ONLY","defaultRestSec":60,"unilateral":false,"sideMode":"none","focus":["Rotace vzniká v rameni; předloktí ukazuje směr pohybu.","Rotation occurs at the shoulder; the forearm shows its direction."],"startPosition":["Upevni lehkou odporovou gumu k pevné kotvě přibližně ve výšce lokte. Postav se bokem, procvičovanou paží dál od kotvy. Loket nech u boku, pokrčený přibližně do pravého úhlu; mezi nadloktí a trup můžeš vložit složený ručník.","Secure a light resistance band to a fixed anchor roughly at elbow height. Stand sideways with the working arm farther from the anchor. Keep the elbow beside the trunk, bent roughly to a right angle; a folded towel between the upper arm and trunk is optional."],"execution":["Otáčej pažní kost zevně v rameni: ruka a předloktí se pohybují od břicha ven, loket zůstává přibližně na místě. Pomalu se vrať. Otočení ven a návrat tvoří jedno opakování; po plánované sérii vystřídej paži.","Rotate the upper arm outward at the shoulder: the hand and forearm move away from the abdomen while the elbow stays roughly in place. Return slowly. One outward rotation and return is one repetition; change arms after the planned set."],"watchFor":["Neotáčej trup místo paže a neohýbej zápěstí, abys došel dál. Rameno nemusíš silou tlačit dolů ani lopatku svírat k páteři. Zvol odpor a rozsah, ve kterých pohyb ovládáš bez nepříjemného tlaku.","Do not turn the trunk instead of the arm or bend the wrist to reach farther. You do not need to force the shoulder downward or squeeze the shoulder blade against the spine. Choose resistance and range you can control without uncomfortable pressure."]},"progression":["Lehčí: menší napětí gumy nebo rozsah. Podle potřeby změň odpor či zpomal návrat při stejné poloze. Silnější guma není povinný další krok a přítah k obličeji není stejný úkol.","Easier: less band tension or a smaller range. Adjust resistance or slow the return as needed while keeping the same setup. A stronger band is not a required next step, and a face pull is a different task."]}}},"ex26_mob_dowel_er":{"id":"ex26_mob_dowel_er","segment":"B","edits":{"pos":["Ve stoji drž lehkou tyč vodorovně před pasem. Loket procvičované paže nech pohodlně u boku a ohni přibližně do pravého úhlu. Ruka této paže drží nebo podpírá konec tyče, druhá ruka ji vede.","Stand holding a light dowel horizontally in front of the waist. Keep the working elbow comfortably beside the trunk, bent roughly to a right angle. That hand holds or cups one end of the dowel while the other hand guides it."],"exe":["Druhou rukou jemně posuň tyč tak, aby se procvičovaná paže otáčela zevně v rameni a předloktí šlo ven. Potom se klidně vrať. Otočení a návrat jsou jedno opakování na procvičované paži; po sérii vystřídej stranu.","Gently guide the dowel with the other hand so the working upper arm rotates outward at the shoulder and the forearm moves out. Return smoothly. One rotation and return is one repetition for the working arm; change sides after the set."],"wat":["Trup a pánev nech směřovat vpřed, loket nemusíš k boku tisknout silou. Tyč poskytuje jemnou dopomoc, ne páku pro vynucení rozsahu. Skonči před nepříjemným tlakem nebo bolestí.","Keep the trunk and pelvis facing forward without squeezing the elbow forcefully into the side. The dowel provides gentle assistance, not leverage to force range. Stop before uncomfortable pressure or pain."],"pro":["Lehčí: menší úhel a pomalejší pohyb. Méně dopomoci je jiná aktivnější varianta, kterou si poznamenej; nemusíš ji zvládnout jako další povinný krok. Rozsah lze ponechat stejný.","Easier: a smaller angle and slower movement. Less assistance is a different, more active variation to note; it is not a compulsory next step. The range may stay the same."],"foc":["Jemná dopomoc druhé ruky, pohyb v rameni bez otáčení trupu.","Gentle assistance from the other hand; shoulder movement without turning the trunk."],"equipmentDetail":["Lehká tyč dostatečné délky pro pohodlný úchop. Jde o opakovaný dopomáhaný pohyb bez přidané hmotnosti; krátké zastavení nemění zápis na sekundy.","A light dowel long enough for a comfortable grip. This is repeated assisted movement without added load; a brief pause does not change the recording to seconds."],"source":{"author":"American Academy of Orthopaedic Surgeons","document":"Rotator Cuff and Shoulder Conditioning Program","url":"https://www.orthoinfo.org/recovery/rotator-cuff-and-shoulder-conditioning-program/","scope":"Public Passive External Rotation method supports the light stick, assisted shoulder rotation and stable forward-facing trunk. The source uses a timed hold; this existing app card is an independent repeated movement adaptation. No source dose or treatment claim is imported."},"eq":["light_dowel"]},"taxonomy":{"regions":["shoulders"],"secondaryRegions":["back"],"movements":["joint"],"focus":["mobility"],"positions":["standing"],"supports":["assisted"],"priority":1,"equipmentRequirements":[["light_dowel"]],"aliases":["pasivní zevní rotace tyčí","dowel assisted external rotation"]},"policy":{"id":"ex26_mob_dowel_er","measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"perSide","requirements":[["light_dowel"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false,"blockedMotionSources":[],"sideMeaning":["Procvičovaná paže","Working arm"]},"art":{"appId":"ex26_mob_dowel_er","atlasId":"ex26_mob_dowel_er","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"fe5b64cb7fd11e202a3f6862e35fb2c2576ed4779832cf717321c7c46eab301f","thumb":"/expansion-atlas/ex26_mob_dowel_er-original-256.webp","detail":"/expansion-atlas/ex26_mob_dowel_er-original-960.webp","inkThumb":"/expansion-atlas/ex26_mob_dowel_er-ink-256.webp","inkDetail":"/expansion-atlas/ex26_mob_dowel_er-ink-960.webp","fillThumb":"/expansion-atlas/ex26_mob_dowel_er-fill-256.webp","fillDetail":"/expansion-atlas/ex26_mob_dowel_er-fill-960.webp"},"sourceSha256":"fe5b64cb7fd11e202a3f6862e35fb2c2576ed4779832cf717321c7c46eab301f","contourOnly":true,"darkOutline":true},"libraryOrder":3001,"deliveryProfiles":{"8c85446ecc98c1b9":{"fields":{"id":"ex26_mob_dowel_er","cz":"Zevní rotace ramene s dopomocí tyče","en":"Dowel-Assisted Shoulder External Rotation","pat":"mobilita","eq":["light_dowel"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":15,"unilateral":true,"sideMode":"perSide","focus":["Jemná dopomoc druhé ruky, pohyb v rameni bez otáčení trupu.","Gentle assistance from the other hand; shoulder movement without turning the trunk."],"startPosition":["Ve stoji drž lehkou tyč vodorovně před pasem. Loket procvičované paže nech pohodlně u boku a ohni přibližně do pravého úhlu. Ruka této paže drží nebo podpírá konec tyče, druhá ruka ji vede.","Stand holding a light dowel horizontally in front of the waist. Keep the working elbow comfortably beside the trunk, bent roughly to a right angle. That hand holds or cups one end of the dowel while the other hand guides it."],"execution":["Druhou rukou jemně posuň tyč tak, aby se procvičovaná paže otáčela zevně v rameni a předloktí šlo ven. Potom se klidně vrať. Otočení a návrat jsou jedno opakování na procvičované paži; po sérii vystřídej stranu.","Gently guide the dowel with the other hand so the working upper arm rotates outward at the shoulder and the forearm moves out. Return smoothly. One rotation and return is one repetition for the working arm; change sides after the set."],"watchFor":["Trup a pánev nech směřovat vpřed, loket nemusíš k boku tisknout silou. Tyč poskytuje jemnou dopomoc, ne páku pro vynucení rozsahu. Skonči před nepříjemným tlakem nebo bolestí.","Keep the trunk and pelvis facing forward without squeezing the elbow forcefully into the side. The dowel provides gentle assistance, not leverage to force range. Stop before uncomfortable pressure or pain."]},"progression":["Lehčí: menší úhel a pomalejší pohyb. Méně dopomoci je jiná aktivnější varianta, kterou si poznamenej; nemusíš ji zvládnout jako další povinný krok. Rozsah lze ponechat stejný.","Easier: a smaller angle and slower movement. Less assistance is a different, more active variation to note; it is not a compulsory next step. The range may stay the same."]}}},"ig27_kneeling_cuban_rotation":{"id":"ig27_kneeling_cuban_rotation","segment":"B","edits":{"pos":["Ve vysokém kleku drž dvě stejně lehké jednoručky. Boky nech přibližně nad koleny. Nadloktí zvedni do stran do pohodlné výšky, obvykle poblíž ramen, a lokty ohni přibližně do pravého úhlu. Začni s předloktími před tělem.","Tall kneel holding two equally light dumbbells. Keep the hips roughly above the knees. Raise the upper arms to a comfortable height, usually near shoulder level, and bend the elbows roughly to a right angle. Start with the forearms in front of the body."],"exe":["Pomalu otoč obě paže zevně v ramenou, aby předloktí směřovala vzhůru, a stejnou cestou je vrať. Výšku nadloktí a pokrčení loktů udržuj přibližně stejné. Společné otočení a návrat obou paží jsou jedno opakování, bez tlaku činek nad hlavu.","Slowly rotate both upper arms outward at the shoulders so the forearms move upward, then reverse the path. Keep upper-arm height and elbow bend roughly unchanged. The simultaneous rotation and return of both arms is one repetition, without pressing the dumbbells overhead."],"wat":["Výšku rukou nezískávej záklonem trupu ani dopnutím loktů. Nesnaž se silou stáhnout lopatky dolů; udržuj klidný krk a kontrolovanou polohu paží. Sniž zátěž či rozsah před nepříjemným tlakem v rameni.","Do not gain hand height by leaning backward or straightening the elbows. Do not force the shoulder blades downward; keep the neck comfortable and arm position controlled. Reduce load or range before uncomfortable shoulder pressure."],"pro":["Lehčí: nižší hmotnost, menší rozsah nebo nácvik bez činek. Nižší poloha loktů mění provedení a patří do poznámky. Pomalý návrat či malá změna hmotnosti jsou možnosti, ne povinné pořadí postupu.","Easier: less weight, a smaller range or unloaded practice. A lower elbow position changes the setup and belongs in the notes. A slow return or small weight change are options, not a mandatory progression sequence."],"foc":["Obě ramena rotují současně; lokty zůstávají pokrčené a činky nejdou do tlaku.","Both shoulders rotate together; the elbows stay bent and the weights are not pressed overhead."],"equipmentDetail":["Pár stejně lehkých jednoruček, podložka pod kolena podle pohodlí. Zapisuj hmotnost a opakování; do poznámky uveď hmotnost každého kusu a zda číselné pole znamená jeden kus, nebo součet. Dosavadní konvenci ani staré záznamy nepřepočítávej.","A pair of equally light dumbbells, with knee padding as needed. Record weight and repetitions; note each implement’s weight and whether the numeric field means one implement or their combined weight. Keep your existing convention and do not convert old records."]},"taxonomy":{"regions":["shoulders"],"secondaryRegions":["back"],"movements":["joint"],"focus":["strength","mobility"],"positions":["kneeling"],"supports":[],"priority":1,"equipmentRequirements":[["dumbbell_pair"]],"aliases":["zevní rotace ve vysokém kleku","tall kneeling Cuban rotation"]},"policy":{"id":"ig27_kneeling_cuban_rotation","measurementType":"WEIGHT_REPS","loadMode":"ext","sideMode":"none","requirements":[["dumbbell_pair"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":false,"allowEstimatedMax":false,"allowComparableRecords":false,"blockedMotionSources":[]},"art":{"appId":"ig27_kneeling_cuban_rotation","atlasId":"ig27_kneeling_cuban_rotation","unified":true,"contourOnly":true,"darkOutline":true,"sourceSha256":"2a22837ea4b337561098b349b1cc2ff430fa8ee029161d9f4914d87b7b615d71","primary":{"width":960,"height":960,"thumb":"/movement-audit/ig27_kneeling_cuban_rotation-2a22837ea4b3-256.webp","inkThumb":"/movement-audit/ig27_kneeling_cuban_rotation-2a22837ea4b3-256.webp","detail":"/movement-audit/ig27_kneeling_cuban_rotation-2a22837ea4b3-960.webp","inkDetail":"/movement-audit/ig27_kneeling_cuban_rotation-2a22837ea4b3-960.webp","sourceSha256":"2a22837ea4b337561098b349b1cc2ff430fa8ee029161d9f4914d87b7b615d71"}},"libraryOrder":3004,"deliveryProfiles":{"fd8613635d2ed074":{"fields":{"id":"ig27_kneeling_cuban_rotation","cz":"Zevní rotace ramen s jednoručkami ve vysokém kleku","en":"Tall-Kneeling Dumbbell Cuban Rotation","pat":"mobilita","eq":["zavazi"],"measurementType":"WEIGHT_REPS","defaultRestSec":30,"unilateral":false,"sideMode":"none","focus":["Obě ramena rotují současně; lokty zůstávají pokrčené a činky nejdou do tlaku.","Both shoulders rotate together; the elbows stay bent and the weights are not pressed overhead."],"startPosition":["Ve vysokém kleku drž dvě stejně lehké jednoručky. Boky nech přibližně nad koleny. Nadloktí zvedni do stran do pohodlné výšky, obvykle poblíž ramen, a lokty ohni přibližně do pravého úhlu. Začni s předloktími před tělem.","Tall kneel holding two equally light dumbbells. Keep the hips roughly above the knees. Raise the upper arms to a comfortable height, usually near shoulder level, and bend the elbows roughly to a right angle. Start with the forearms in front of the body."],"execution":["Pomalu otoč obě paže zevně v ramenou, aby předloktí směřovala vzhůru, a stejnou cestou je vrať. Výšku nadloktí a pokrčení loktů udržuj přibližně stejné. Společné otočení a návrat obou paží jsou jedno opakování, bez tlaku činek nad hlavu.","Slowly rotate both upper arms outward at the shoulders so the forearms move upward, then reverse the path. Keep upper-arm height and elbow bend roughly unchanged. The simultaneous rotation and return of both arms is one repetition, without pressing the dumbbells overhead."],"watchFor":["Výšku rukou nezískávej záklonem trupu ani dopnutím loktů. Nesnaž se silou stáhnout lopatky dolů; udržuj klidný krk a kontrolovanou polohu paží. Sniž zátěž či rozsah před nepříjemným tlakem v rameni.","Do not gain hand height by leaning backward or straightening the elbows. Do not force the shoulder blades downward; keep the neck comfortable and arm position controlled. Reduce load or range before uncomfortable shoulder pressure."]},"progression":["Lehčí: nižší hmotnost, menší rozsah nebo nácvik bez činek. Nižší poloha loktů mění provedení a patří do poznámky. Pomalý návrat či malá změna hmotnosti jsou možnosti, ne povinné pořadí postupu.","Easier: less weight, a smaller range or unloaded practice. A lower elbow position changes the setup and belongs in the notes. A slow return or small weight change are options, not a mandatory progression sequence."]}}},"ex26_mob_prone_swimmer":{"id":"ex26_mob_prone_swimmer","segment":"B","edits":{"pos":["Lehni na břicho a čelo pohodlně podepři nízkým složeným ručníkem nebo vhodným polštářkem. Hrudník a nohy nech spočívat na podložce. Paže natáhni před sebe do pohodlné polohy.","Lie prone and support the forehead comfortably on a low folded towel or suitable cushion. Rest the chest and legs on the floor or mat. Extend both arms forward to a comfortable position."],"exe":["Paže lehce odlehči a pomalu je veď do stran a k bokům. Průběžně otáčej paže v ramenou, potom pokrč lokty pro pohodlný dosah za záda. Vrať se opačnou cestou před sebe. Jeden celý oblouk tam a zpět oběma pažemi je jedno opakování.","Float the arms slightly and sweep them slowly out to the sides and toward the hips. Rotate through the shoulders as you go, then bend the elbows for a comfortable reach behind the back. Reverse the path to the front. One complete outward-and-return arc with both arms is one repetition."],"wat":["Nezvedej hrudník ani hlavu kvůli vyššímu dosahu. Lopatky mohou přirozeně měnit polohu; nesvírej je po celý oblouk pevně k páteři. Ruce nemusí dosáhnout vysoko za záda.","Do not lift the chest or head to gain reach. Let the shoulder blades change position naturally rather than pinning them against the spine throughout the arc. The hands do not need to reach high behind the back."],"pro":["Lehčí: kratší oblouk nebo lehké klouzání rukou po podložce. Náročnější může být delší úsek bez dotyku země, pokud zůstává trup klidný. Poznamenej změnu provedení; maximální výška ani zátěž nejsou cíl.","Easier: a shorter arc or lightly sliding the hands on the floor. A longer section without floor contact may increase the demand if the trunk stays settled. Note setup changes; maximum height and added load are not the goal."],"foc":["Plynulý oblouk obou paží, podepřené čelo a klidný trup.","A smooth arc of both arms with the forehead supported and trunk settled."],"equipmentDetail":["Vlastní váha a nízký složený ručník nebo vhodný polštářek pod čelo. Podložka pod tělo je volitelná. Počítá se společný pohyb obou paží; nejde o střídavé zvedání ruky a protilehlé nohy.","Bodyweight and a low folded towel or suitable cushion beneath the forehead. A mat under the body is optional. Count the arms moving together; this is not an alternating opposite-arm-and-leg lift."],"source":{"author":"Evolution Physical Therapy","document":"Upper Body Mobility Exercises for Swimmers","url":"https://www.evolutionphysicaltherapy.com/post/upper-body-mobility-exercises-swimming/","scope":"Publisher text for Prone Swimmers supports a controlled shoulder arc between overhead and behind-back positions with the chest grounded. The source describes single-arm repetitions from the hand-behind-head position; this existing app card uses both arms together from forward reach, forehead support and one out-and-return cycle. Independent adaptation, not the source dose or an injury-prevention claim."}},"taxonomy":{"regions":["shoulders"],"secondaryRegions":["back"],"movements":["joint"],"focus":["mobility","coordination"],"positions":["prone"],"supports":["head_support"],"priority":1,"equipmentRequirements":[["telo"],["towel","support_cushion"]],"aliases":["plavecké oblouky ramen","prone shoulder swimmers","swimmer hover"]},"policy":{"id":"ex26_mob_prone_swimmer","measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"none","requirements":[["telo"],["towel","support_cushion"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false,"blockedMotionSources":[]},"art":{"appId":"ex26_mob_prone_swimmer","atlasId":"ex26_mob_prone_swimmer","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"a21e508fd36f528dfba9d7ce53dfc2b8ac2e55dbda1abdc233d7eb3f53d8c723","thumb":"/expansion-atlas/ex26_mob_prone_swimmer-original-256.webp","detail":"/expansion-atlas/ex26_mob_prone_swimmer-original-960.webp","inkThumb":"/expansion-atlas/ex26_mob_prone_swimmer-ink-256.webp","inkDetail":"/expansion-atlas/ex26_mob_prone_swimmer-ink-960.webp","fillThumb":"/expansion-atlas/ex26_mob_prone_swimmer-fill-256.webp","fillDetail":"/expansion-atlas/ex26_mob_prone_swimmer-fill-960.webp"},"sourceSha256":"a21e508fd36f528dfba9d7ce53dfc2b8ac2e55dbda1abdc233d7eb3f53d8c723","contourOnly":true,"darkOutline":true},"libraryOrder":3005,"deliveryProfiles":{"e5598c22d389749a":{"fields":{"id":"ex26_mob_prone_swimmer","cz":"Pomalé plavecké oblouky pažemi na břiše","en":"Prone Shoulder Swimmer","pat":"mobilita","eq":["telo"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":15,"unilateral":false,"sideMode":"none","focus":["Plynulý oblouk obou paží, podepřené čelo a klidný trup.","A smooth arc of both arms with the forehead supported and trunk settled."],"startPosition":["Lehni na břicho a čelo pohodlně podepři nízkým složeným ručníkem nebo vhodným polštářkem. Hrudník a nohy nech spočívat na podložce. Paže natáhni před sebe do pohodlné polohy.","Lie prone and support the forehead comfortably on a low folded towel or suitable cushion. Rest the chest and legs on the floor or mat. Extend both arms forward to a comfortable position."],"execution":["Paže lehce odlehči a pomalu je veď do stran a k bokům. Průběžně otáčej paže v ramenou, potom pokrč lokty pro pohodlný dosah za záda. Vrať se opačnou cestou před sebe. Jeden celý oblouk tam a zpět oběma pažemi je jedno opakování.","Float the arms slightly and sweep them slowly out to the sides and toward the hips. Rotate through the shoulders as you go, then bend the elbows for a comfortable reach behind the back. Reverse the path to the front. One complete outward-and-return arc with both arms is one repetition."],"watchFor":["Nezvedej hrudník ani hlavu kvůli vyššímu dosahu. Lopatky mohou přirozeně měnit polohu; nesvírej je po celý oblouk pevně k páteři. Ruce nemusí dosáhnout vysoko za záda.","Do not lift the chest or head to gain reach. Let the shoulder blades change position naturally rather than pinning them against the spine throughout the arc. The hands do not need to reach high behind the back."]},"progression":["Lehčí: kratší oblouk nebo lehké klouzání rukou po podložce. Náročnější může být delší úsek bez dotyku země, pokud zůstává trup klidný. Poznamenej změnu provedení; maximální výška ani zátěž nejsou cíl.","Easier: a shorter arc or lightly sliding the hands on the floor. A longer section without floor contact may increase the demand if the trunk stays settled. Note setup changes; maximum height and added load are not the goal."]}}},"ex26_mob_prone_overhead_lift":{"id":"ex26_mob_prone_overhead_lift","segment":"C","edits":{"pos":["Lehni na břicho a čelo pohodlně podepři nízkým složeným ručníkem nebo vhodným polštářkem. Hrudník a nohy nech na podložce. Lehká tyč leží před hlavou, obě ruce ji drží pohodlným širším úchopem a lokty zůstávají dlouhé.","Lie prone with the forehead comfortably supported by a low folded towel or suitable cushion. Rest the chest and legs on the floor or mat. A light dowel rests beyond the head; hold it with both hands at a comfortable wider grip and keep the elbows long."],"exe":["Oběma pažemi tyč lehce zvedni nad podložku a kontrolovaně ji polož. Stačí malý pohyb, při kterém čelo i hrudník zůstávají podepřené. Jedno zvednutí a položení tyče je jedno opakování.","Use both arms to lift the dowel slightly from the floor and lower it with control. A small lift is enough while the forehead and chest stay supported. One lift and return of the dowel is one repetition."],"wat":["Výšku nezískávej zvedáním hlavy, hrudníku nebo prohýbáním beder. Lopatky mohou s pažemi přirozeně měnit polohu; nestahuj je silou dolů. Pokud tyč v pohodlném rozsahu neodlehčíš, zmenši nárok na vzpažení nebo zvol jinou polohu.","Do not gain height by lifting the head or chest or arching the lower back. Let the shoulder blades move naturally with the arms instead of forcing them downward. If the dowel cannot clear the floor comfortably, reduce the overhead demand or choose another position."],"pro":["Lehčí může být pohodlně širší úchop nebo samostatný nácvik vzpažení vleže na zádech. Šířku úchopu vol podle pohodlí, její zužování není povinná progrese. Krátká pauza nad zemí je možnost; tyč zůstává lehká a změnu provedení si poznamenej.","A comfortably wider grip or separate practice of an arm raise while lying on the back may be easier. Choose grip width for comfort; narrowing it is not a required progression. A brief pause above the floor is an option; keep the dowel light and note setup changes."],"foc":["Malé aktivní odlehčení tyče s podepřeným čelem a klidným trupem.","A small active dowel lift with the forehead supported and the trunk settled."],"equipmentDetail":["Lehká tyč a nízký složený ručník nebo vhodný polštářek pod čelo. Podložka pod tělo je volitelná. Počítá se společný pohyb obou paží; hmotnost tyče se zde nezapisuje jako zátěž.","A light dowel and a low folded towel or suitable cushion beneath the forehead. A mat under the body is optional. Count both arms moving together; this card does not record the dowel as added weight."],"source":{"author":"The Prehab Guys","document":"Prone Overhead Lift Off - PVC","url":"https://library.theprehabguys.com/vimeo-video/prone-overhead-lift-off-pvc/","scope":"Specific publisher technique text for a bilateral prone overhead dowel lift with head and chest down. Forehead padding, comfortable rather than maximal height and the app counting convention are independent coaching refinements. Source video not visually reviewed; no clinical indication or fixed prescription is imported."},"eq":["light_dowel"]},"taxonomy":{"regions":["shoulders"],"secondaryRegions":["back"],"movements":["joint"],"focus":["mobility","coordination"],"priority":1,"positions":["prone"],"supports":["head_support"],"equipmentRequirements":[["light_dowel"],["towel","support_cushion"]],"aliases":["prone overhead dowel lift off","aktivní vzpažení na břiše"]},"policy":{"id":"ex26_mob_prone_overhead_lift","measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"none","requirements":[["light_dowel"],["towel","support_cushion"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false,"blockedMotionSources":[]},"art":{"appId":"ex26_mob_prone_overhead_lift","atlasId":"ex26_mob_prone_overhead_lift","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"fcecb69f822ce65ac950d2bc87d4fd5c6c9918c034c005ecb66dc5b7829431c7","thumb":"/expansion-atlas/ex26_mob_prone_overhead_lift-original-256.webp","detail":"/expansion-atlas/ex26_mob_prone_overhead_lift-original-960.webp","inkThumb":"/expansion-atlas/ex26_mob_prone_overhead_lift-ink-256.webp","inkDetail":"/expansion-atlas/ex26_mob_prone_overhead_lift-ink-960.webp","fillThumb":"/expansion-atlas/ex26_mob_prone_overhead_lift-fill-256.webp","fillDetail":"/expansion-atlas/ex26_mob_prone_overhead_lift-fill-960.webp"},"sourceSha256":"fcecb69f822ce65ac950d2bc87d4fd5c6c9918c034c005ecb66dc5b7829431c7","contourOnly":true,"darkOutline":true},"libraryOrder":4003,"deliveryProfiles":{"7bb85763c9763f6b":{"fields":{"id":"ex26_mob_prone_overhead_lift","cz":"Aktivní odlehčení tyče ve vzpažení na břiše","en":"Prone Overhead Dowel Lift-Off","pat":"mobilita","eq":["light_dowel"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":15,"unilateral":false,"sideMode":"none","focus":["Malé aktivní odlehčení tyče s podepřeným čelem a klidným trupem.","A small active dowel lift with the forehead supported and the trunk settled."],"startPosition":["Lehni na břicho a čelo pohodlně podepři nízkým složeným ručníkem nebo vhodným polštářkem. Hrudník a nohy nech na podložce. Lehká tyč leží před hlavou, obě ruce ji drží pohodlným širším úchopem a lokty zůstávají dlouhé.","Lie prone with the forehead comfortably supported by a low folded towel or suitable cushion. Rest the chest and legs on the floor or mat. A light dowel rests beyond the head; hold it with both hands at a comfortable wider grip and keep the elbows long."],"execution":["Oběma pažemi tyč lehce zvedni nad podložku a kontrolovaně ji polož. Stačí malý pohyb, při kterém čelo i hrudník zůstávají podepřené. Jedno zvednutí a položení tyče je jedno opakování.","Use both arms to lift the dowel slightly from the floor and lower it with control. A small lift is enough while the forehead and chest stay supported. One lift and return of the dowel is one repetition."],"watchFor":["Výšku nezískávej zvedáním hlavy, hrudníku nebo prohýbáním beder. Lopatky mohou s pažemi přirozeně měnit polohu; nestahuj je silou dolů. Pokud tyč v pohodlném rozsahu neodlehčíš, zmenši nárok na vzpažení nebo zvol jinou polohu.","Do not gain height by lifting the head or chest or arching the lower back. Let the shoulder blades move naturally with the arms instead of forcing them downward. If the dowel cannot clear the floor comfortably, reduce the overhead demand or choose another position."]},"progression":["Lehčí může být pohodlně širší úchop nebo samostatný nácvik vzpažení vleže na zádech. Šířku úchopu vol podle pohodlí, její zužování není povinná progrese. Krátká pauza nad zemí je možnost; tyč zůstává lehká a změnu provedení si poznamenej.","A comfortably wider grip or separate practice of an arm raise while lying on the back may be easier. Choose grip width for comfort; narrowing it is not a required progression. A brief pause above the floor is an option; keep the dowel light and note setup changes."]}}},"ex26_mob_behindback_lift":{"id":"ex26_mob_behindback_lift","segment":"C","edits":{"cz":"Odtažení spojených rukou za tělem","en":"Standing Clasped-Hand Shoulder Extension","pos":["Stůj pohodlně vzpřímeně a volně propleť prsty za pánví. Lokty nech téměř natažené, bez nuceného dopnutí. Pokud ruce pohodlně nespojíš, zvol níže popsanou úpravu.","Stand comfortably upright and loosely interlace the fingers behind the pelvis. Keep the elbows nearly straight without forcing them to lock. If joining the hands is uncomfortable, choose the modification described below."],"exe":["Aktivně odtáhni spojené ruce malý kousek za tělo a klidně je vrať. Trup přitom zůstává přibližně vzpřímený. Jedno odtažení a návrat obou rukou je jedno opakování.","Actively move the joined hands a short distance behind the body, then return gently. Keep the trunk approximately upright. One outward-and-return movement of both hands is one repetition."],"wat":["Nezískávej větší dosah předklonem, vystrčením hlavy ani prohnutím zad. Spojené ruce nepoužívej k přetahování jednoho ramene druhým. Při nepříjemném tlaku v přední části ramene pohyb zmenši nebo ruce odděl.","Do not gain reach by leaning forward, jutting the head or arching the back. Do not use the joined hands to pull one shoulder farther with the other. Reduce the movement or separate the hands if there is uncomfortable pressure at the front of a shoulder."],"pro":["Lehčí: kratší odtažení, ruce odděleně nebo volný širší úchop ručníku či lehké tyče. Pomůcka neslouží k přitahování paží silou. Úpravu si poznamenej. Krátká pauza je možnost, ne důvod nutit ruce výš.","Easier: a shorter reach, separate hands, or a relaxed wider grip on a towel or light dowel. Do not use the prop to force the arms upward. Note the modification. A brief pause is optional and is not a reason to force greater height."],"foc":["Kontrolovaný dosah obou paží za tělo bez předklonu.","A controlled reach of both arms behind the body without leaning forward."],"equipmentDetail":["Základní varianta je bez pomůcek. Ručník nebo tyč jsou volitelné úpravy úchopu, nikoli povinné vybavení. Nejde o odlepování hřbetu jedné ruky od beder při pokrčeném lokti.","The default version uses no equipment. A towel or dowel is an optional grip modification, not required equipment. This is not a single-hand lift from the lower back with the elbow bent."],"source":{"author":"Jarlo Ilano / GMB Fitness","document":"Shoulder Mobility Exercises: Find Your Restriction, Then Fix It","url":"https://gmb.io/shoulder-mobility/","scope":"The public Clasped Hands Extension section supports standing upright, joined hands behind the body, active lifting and an optional towel grip. This card uses controlled lift-and-return repetitions; the source pulse/hold dose and broader health claims are not imported. Embedded source video not visually reviewed."}},"taxonomy":{"regions":["shoulders"],"secondaryRegions":["back"],"movements":["joint"],"focus":["mobility","coordination"],"priority":1,"positions":["standing"],"supports":[],"equipmentRequirements":[["telo"]],"aliases":["clasped hands extension","shoulder extension lift off","aktivní odlehčení rukou za zády"]},"policy":{"id":"ex26_mob_behindback_lift","measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"none","requirements":[["telo"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false,"blockedMotionSources":["/exercise-motion/ex26_mob_behindback_lift-e4b23fb47b3184be.mp4"]},"art":{"appId":"ex26_mob_behindback_lift","atlasId":"ex26_mob_behindback_lift","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"52dd8c9e823effcb041465626fdfc5013728eba4a737becc7fa43b00f7a865a7","thumb":"/expansion-atlas/ex26_mob_behindback_lift-original-256.webp","detail":"/expansion-atlas/ex26_mob_behindback_lift-original-960.webp","inkThumb":"/expansion-atlas/ex26_mob_behindback_lift-ink-256.webp","inkDetail":"/expansion-atlas/ex26_mob_behindback_lift-ink-960.webp","fillThumb":"/expansion-atlas/ex26_mob_behindback_lift-fill-256.webp","fillDetail":"/expansion-atlas/ex26_mob_behindback_lift-fill-960.webp"},"sourceSha256":"52dd8c9e823effcb041465626fdfc5013728eba4a737becc7fa43b00f7a865a7","contourOnly":true,"darkOutline":true},"libraryOrder":4001,"deliveryProfiles":{"09f78653ec6602f6":{"fields":{"id":"ex26_mob_behindback_lift","cz":"Odtažení spojených rukou za tělem","en":"Standing Clasped-Hand Shoulder Extension","pat":"mobilita","eq":["telo"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":15,"unilateral":false,"sideMode":"none","focus":["Kontrolovaný dosah obou paží za tělo bez předklonu.","A controlled reach of both arms behind the body without leaning forward."],"startPosition":["Stůj pohodlně vzpřímeně a volně propleť prsty za pánví. Lokty nech téměř natažené, bez nuceného dopnutí. Pokud ruce pohodlně nespojíš, zvol níže popsanou úpravu.","Stand comfortably upright and loosely interlace the fingers behind the pelvis. Keep the elbows nearly straight without forcing them to lock. If joining the hands is uncomfortable, choose the modification described below."],"execution":["Aktivně odtáhni spojené ruce malý kousek za tělo a klidně je vrať. Trup přitom zůstává přibližně vzpřímený. Jedno odtažení a návrat obou rukou je jedno opakování.","Actively move the joined hands a short distance behind the body, then return gently. Keep the trunk approximately upright. One outward-and-return movement of both hands is one repetition."],"watchFor":["Nezískávej větší dosah předklonem, vystrčením hlavy ani prohnutím zad. Spojené ruce nepoužívej k přetahování jednoho ramene druhým. Při nepříjemném tlaku v přední části ramene pohyb zmenši nebo ruce odděl.","Do not gain reach by leaning forward, jutting the head or arching the back. Do not use the joined hands to pull one shoulder farther with the other. Reduce the movement or separate the hands if there is uncomfortable pressure at the front of a shoulder."]},"progression":["Lehčí: kratší odtažení, ruce odděleně nebo volný širší úchop ručníku či lehké tyče. Pomůcka neslouží k přitahování paží silou. Úpravu si poznamenej. Krátká pauza je možnost, ne důvod nutit ruce výš.","Easier: a shorter reach, separate hands, or a relaxed wider grip on a towel or light dowel. Do not use the prop to force the arms upward. Note the modification. A brief pause is optional and is not a reason to force greater height."]}}},"ex26_mob_wall_liftoff":{"id":"ex26_mob_wall_liftoff","segment":"C","edits":{"ez":null,"pos":["Stůj čelem k hladké pevné zdi s chodidly stabilně na zemi. Předloktí opři přibližně na šířku ramen, lokty pokrč a ruce nech směřovat vzhůru. Zvol odstup, ve kterém se nemusíš kácet ke zdi.","Face a smooth, stable wall with both feet settled on the floor. Rest the forearms about shoulder-width apart with the elbows bent and the hands pointing up. Choose a distance that does not require leaning your body into the wall."],"exe":["Posuň předloktí a ruce vzhůru do pohodlného vzpažení. Bez pohybu trupu je lehce oddal od zdi, vrať do kontaktu a pomalu sjeď dolů. Celý posun nahoru, odlehčení, přiložení a návrat dolů je jedno opakování obou paží.","Slide the forearms and hands upward into a comfortable overhead reach. Gently lift them away from the wall without moving the trunk, replace them and slide down slowly. The complete upward slide, lift-off, replacement and downward return is one repetition with both arms."],"wat":["Odlehčení vzniká pohybem ramen, nikoli odkloněním celého těla od zdi nebo záklonem beder. Lopatky se mohou při vzpažení otáčet vzhůru; nedrž je silou dole. Není nutná maximální výška ani dotyk hlavy se zdí.","The lift-off comes from the shoulders, not from leaning the whole body away from the wall or arching the lower back. Let the shoulder blades rotate upward with the reach rather than forcing them down. Maximum height and head contact with the wall are not required."],"pro":["Lehčí: nižší pohodlné vzpažení nebo samostatný posun po zdi bez odlehčení. Krátká pauza mimo zeď může nárok zvýšit, pokud trup zůstává klidný. Guma ani širší rozsah nejsou povinným dalším krokem.","Easier: a lower comfortable reach or a separate wall slide without the lift-off. A brief pause away from the wall can increase the demand if the trunk stays steady. A band and a greater range are not mandatory next steps."],"foc":["Posun a malé odlehčení obou paží čelem ke zdi, s klidným trupem.","Slide and briefly lift both arms while facing the wall with a steady trunk."],"equipmentDetail":["Hladká pevná zeď a stabilní podlaha. Tato varianta nevyžaduje odporovou gumu ani válec. Počítá se celý společný cyklus, ne každá jeho fáze zvlášť.","A smooth, stable wall and a secure floor. This version does not require a resistance band or roller. Count the full shared cycle, not each phase separately."],"source":{"author":"Physitrack","document":"Wall slides - schouder flexie - lift-off","url":"https://nl.physitrack.com/home-exercise-video/wall-slides---schouder-flexie---lift-off","scope":"Original Dutch publisher text describes facing a wall, forearm contact, upward sliding, lifting the wrists away and returning down without a band. Comfortable range and free upward scapular motion are coaching refinements; no fixed dose or treatment claim. Source video not visually reviewed."}},"taxonomy":{"regions":["shoulders"],"secondaryRegions":["back"],"movements":["joint"],"focus":["mobility","coordination"],"priority":1,"positions":["standing"],"supports":["wall","forearm_support"],"equipmentRequirements":[["zed"]],"aliases":["wall slide lift off","odlehčení paží od zdi"]},"policy":{"id":"ex26_mob_wall_liftoff","measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"none","requirements":[["zed"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false,"blockedMotionSources":[]},"art":{"appId":"ex26_mob_wall_liftoff","atlasId":"ex26_mob_wall_liftoff","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"b82f801f712dbab0e4fd49fd3a27c0b4635b3c9d0e2d4b7546d6d6e8a8c7f873","thumb":"/expansion-atlas/ex26_mob_wall_liftoff-original-256.webp","detail":"/expansion-atlas/ex26_mob_wall_liftoff-original-960.webp","inkThumb":"/expansion-atlas/ex26_mob_wall_liftoff-ink-256.webp","inkDetail":"/expansion-atlas/ex26_mob_wall_liftoff-ink-960.webp","fillThumb":"/expansion-atlas/ex26_mob_wall_liftoff-fill-256.webp","fillDetail":"/expansion-atlas/ex26_mob_wall_liftoff-fill-960.webp"},"sourceSha256":"b82f801f712dbab0e4fd49fd3a27c0b4635b3c9d0e2d4b7546d6d6e8a8c7f873","contourOnly":true,"darkOutline":true},"libraryOrder":4000,"deliveryProfiles":{"bdc6f58a5d904e07":{"fields":{"id":"ex26_mob_wall_liftoff","cz":"Vzpažení u zdi s aktivním odlehčením rukou","en":"Wall Slide with Lift-Off","pat":"mobilita","eq":["zed"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":15,"unilateral":false,"sideMode":"none","focus":["Posun a malé odlehčení obou paží čelem ke zdi, s klidným trupem.","Slide and briefly lift both arms while facing the wall with a steady trunk."],"startPosition":["Stůj čelem k hladké pevné zdi s chodidly stabilně na zemi. Předloktí opři přibližně na šířku ramen, lokty pokrč a ruce nech směřovat vzhůru. Zvol odstup, ve kterém se nemusíš kácet ke zdi.","Face a smooth, stable wall with both feet settled on the floor. Rest the forearms about shoulder-width apart with the elbows bent and the hands pointing up. Choose a distance that does not require leaning your body into the wall."],"execution":["Posuň předloktí a ruce vzhůru do pohodlného vzpažení. Bez pohybu trupu je lehce oddal od zdi, vrať do kontaktu a pomalu sjeď dolů. Celý posun nahoru, odlehčení, přiložení a návrat dolů je jedno opakování obou paží.","Slide the forearms and hands upward into a comfortable overhead reach. Gently lift them away from the wall without moving the trunk, replace them and slide down slowly. The complete upward slide, lift-off, replacement and downward return is one repetition with both arms."],"watchFor":["Odlehčení vzniká pohybem ramen, nikoli odkloněním celého těla od zdi nebo záklonem beder. Lopatky se mohou při vzpažení otáčet vzhůru; nedrž je silou dole. Není nutná maximální výška ani dotyk hlavy se zdí.","The lift-off comes from the shoulders, not from leaning the whole body away from the wall or arching the lower back. Let the shoulder blades rotate upward with the reach rather than forcing them down. Maximum height and head contact with the wall are not required."]},"progression":["Lehčí: nižší pohodlné vzpažení nebo samostatný posun po zdi bez odlehčení. Krátká pauza mimo zeď může nárok zvýšit, pokud trup zůstává klidný. Guma ani širší rozsah nejsou povinným dalším krokem.","Easier: a lower comfortable reach or a separate wall slide without the lift-off. A brief pause away from the wall can increase the demand if the trunk stays steady. A band and a greater range are not mandatory next steps."]}}},"ex26_mob_roller_angels":{"id":"ex26_mob_roller_angels","segment":"C","edits":{"pos":["Lehni na záda podélně na dlouhý pěnový válec, který současně podpírá pánev, záda i hlavu. Pokrč kolena a chodidla polož dost široce na neklouzavou zem, abys zůstal stabilní. Začni s pažemi volně podél těla a dlaněmi vzhůru.","Lie on your back lengthwise along a long foam roller that supports the pelvis, back and head together. Bend the knees and place the feet wide enough on a non-slip floor to stay stable. Begin with the arms comfortably beside the body and the palms facing up."],"exe":["Paže s pohodlně dlouhými lokty veď pomalými oblouky do stran a směrem nad hlavu. Zastav v dostupném rozsahu a stejnou cestou se vrať k bokům. Jeden oblouk tam a zpět oběma pažemi je jedno opakování.","With the elbows comfortably long, sweep both arms slowly out to the sides and toward overhead. Stop within your available range and follow the same path back to the hips. One outward-and-return arc with both arms is one repetition."],"wat":["Hlava a pánev zůstávají podepřené. Paže ani hřbety rukou nemusí dosáhnout podlahy. Nezvětšuj oblouk vykláněním z válce, zvedáním žeber nebo nuceným prohnutím; lopatky mohou přirozeně měnit polohu.","Keep the head and pelvis supported. The arms and backs of the hands do not need to reach the floor. Do not enlarge the arc by rolling off the roller, lifting the ribs or forcing an arch; let the shoulder blades move naturally."],"pro":["Lehčí: menší oblouk, pohodlně pokrčené lokty nebo stejný pohyb přímo na podlaze. Úpravu polohy a loktů si poznamenej. Plynulá kontrola má přednost před větším rozsahem; zvedání nohou ani zátěž nejsou součástí této varianty.","Easier: a smaller arc, comfortably bent elbows or the same movement directly on the floor. Note changes to body position and elbow bend. Smooth control takes priority over a larger range; lifting the feet or adding weights is not part of this version."],"foc":["Pomalé oblouky obou paží s oporou hlavy a pánve na dlouhém válci.","Slow arcs with both arms while the head and pelvis rest on a long roller."],"equipmentDetail":["Dlouhý pěnový válec, který současně podepře hlavu i pánev. Krátký masážní válec tuto oporu nenahrazuje. Vhodná neklouzavá podložka je volitelná podle povrchu.","A long foam roller that supports the head and pelvis at the same time. A short massage roller does not provide this support. A suitable non-slip mat is optional depending on the floor."],"source":{"author":"Jacqueline Crockford / American Council on Exercise","document":"How to Increase Upper-body Stability and Mobility","url":"https://www.acefitness.org/resources/pros/expert-articles/5412/how-to-increase-upper-body-stability-and-mobility/","scope":"Publisher text describes supine arm snow angels on a roller aligned with the spine, beginning with bent elbows. This existing card uses a longer-arm arc from the hips, full head/pelvis support and a comfortable clearance from the floor. Explicit technique adaptation, not an exact copy of the source variant, dose or injury-prevention claims. No source video reviewed."}},"taxonomy":{"regions":["shoulders","chest"],"secondaryRegions":["back"],"movements":["joint"],"focus":["mobility","coordination"],"priority":1,"positions":["supine"],"supports":["head_support","roller_support"],"equipmentRequirements":[["long_foam_roller"]],"aliases":["foam roller snow angels","oblouky na dlouhém válci"]},"policy":{"id":"ex26_mob_roller_angels","measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"none","requirements":[["long_foam_roller"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false,"blockedMotionSources":["/exercise-motion/ex26_mob_roller_angels-3d34f45975539572.mp4"]},"art":{"appId":"ex26_mob_roller_angels","atlasId":"ex26_mob_roller_angels","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"c3c5083f10e0047896d6350555d00c88048bbe979049ffb32607e541c71070e5","thumb":"/expansion-atlas/ex26_mob_roller_angels-original-256.webp","detail":"/expansion-atlas/ex26_mob_roller_angels-original-960.webp","inkThumb":"/expansion-atlas/ex26_mob_roller_angels-ink-256.webp","inkDetail":"/expansion-atlas/ex26_mob_roller_angels-ink-960.webp","fillThumb":"/expansion-atlas/ex26_mob_roller_angels-fill-256.webp","fillDetail":"/expansion-atlas/ex26_mob_roller_angels-fill-960.webp"},"sourceSha256":"c3c5083f10e0047896d6350555d00c88048bbe979049ffb32607e541c71070e5","contourOnly":true,"darkOutline":true},"libraryOrder":4002,"deliveryProfiles":{"5a72ef99ebcf8149":{"fields":{"id":"ex26_mob_roller_angels","cz":"Oblouky pažemi na podélném válci","en":"Longitudinal Foam-Roller Arm Angels","pat":"mobilita","eq":["valec"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":15,"unilateral":false,"sideMode":"none","focus":["Pomalé oblouky obou paží s oporou hlavy a pánve na dlouhém válci.","Slow arcs with both arms while the head and pelvis rest on a long roller."],"startPosition":["Lehni na záda podélně na dlouhý pěnový válec, který současně podpírá pánev, záda i hlavu. Pokrč kolena a chodidla polož dost široce na neklouzavou zem, abys zůstal stabilní. Začni s pažemi volně podél těla a dlaněmi vzhůru.","Lie on your back lengthwise along a long foam roller that supports the pelvis, back and head together. Bend the knees and place the feet wide enough on a non-slip floor to stay stable. Begin with the arms comfortably beside the body and the palms facing up."],"execution":["Paže s pohodlně dlouhými lokty veď pomalými oblouky do stran a směrem nad hlavu. Zastav v dostupném rozsahu a stejnou cestou se vrať k bokům. Jeden oblouk tam a zpět oběma pažemi je jedno opakování.","With the elbows comfortably long, sweep both arms slowly out to the sides and toward overhead. Stop within your available range and follow the same path back to the hips. One outward-and-return arc with both arms is one repetition."],"watchFor":["Hlava a pánev zůstávají podepřené. Paže ani hřbety rukou nemusí dosáhnout podlahy. Nezvětšuj oblouk vykláněním z válce, zvedáním žeber nebo nuceným prohnutím; lopatky mohou přirozeně měnit polohu.","Keep the head and pelvis supported. The arms and backs of the hands do not need to reach the floor. Do not enlarge the arc by rolling off the roller, lifting the ribs or forcing an arch; let the shoulder blades move naturally."]},"progression":["Lehčí: menší oblouk, pohodlně pokrčené lokty nebo stejný pohyb přímo na podlaze. Úpravu polohy a loktů si poznamenej. Plynulá kontrola má přednost před větším rozsahem; zvedání nohou ani zátěž nejsou součástí této varianty.","Easier: a smaller arc, comfortably bent elbows or the same movement directly on the floor. Note changes to body position and elbow bend. Smooth control takes priority over a larger range; lifting the feet or adding weights is not part of this version."]}}},"pullapart":{"id":"pullapart","segment":"D","edits":{"eq":["long_light_band"],"source":{"author":"[P]rehab","document":"Band Pull Apart","url":"https://theprehabguys.com/vimeo-video/band-pull-apart/","scope":"First-party exercise notes support opening the arms against a hand-held band with scapular retraction and a controlled return. Comfortable range is an editorial adaptation; no required chest contact, posture correction, clinical indication or universal dose is claimed."},"pos":["Postav se pohodlně a uchop dlouhou lehkou gumu oběma rukama před hrudníkem přibližně ve výšce ramen. Začni s malým napětím a takovou vzdáleností rukou, abys pohyb zvládl plynule. Lokty nech téměř natažené, bez násilného propnutí.","Stand comfortably and hold a long light band between both hands in front of the chest, around shoulder height. Start with light tension and hand spacing that allows smooth movement. Keep the elbows nearly straight without forcing them into lockout."],"exe":["Pomalu rozevírej paže do stran a nech lopatky přiblížit. Skonči v ovládaném rozsahu, nejvýše přibližně s pažemi v rovině trupu; dotyk gumy s hrudníkem není podmínkou. Vrať ruce před sebe bez povolení gumy trhnutím. Rozevření a návrat je jedno opakování; neprováděj přítah ohýbáním loktů.","Slowly open the arms out to the sides and allow the shoulder blades to draw together. Stop within a controlled range, at most roughly with the arms in line with the torso; the band does not have to touch the chest. Bring the hands forward without letting the band snap back. One opening and return is one repetition; do not turn it into a row by bending the elbows."],"wat":["Trup nech klidný, nevystrkuj žebra a nezískávej rozsah záklonem. Ramena netlač silou dolů ani nezvedej k uším. Zvol menší dráhu nebo lehčí tah, pokud se pohyb mění v cukání.","Keep the trunk steady without flaring the ribs or leaning back to gain range. Do not force the shoulders down or shrug toward the ears. Use a smaller path or lighter tension if the movement becomes jerky."],"pro":["Lehčí: slabší guma, delší volný úsek mezi rukama nebo kratší rozevření. Dále můžeš zpomalit návrat či krátce zastavit, pokud držíš stejnou polohu. Typ gumy a úchop si poznamenej; barva gumy není univerzální hmotnost v kg.","Easier: use a lighter band, a longer free section between the hands or a shorter opening. You may then slow the return or pause briefly while keeping the same position. Note the band and grip used; band colour is not a universal load in kilograms."],"foc":["Rozevírej paže plynule, lopatky se mohou přibližovat i vracet.","Open the arms smoothly, allowing the shoulder blades to draw together and return."],"equipmentDetail":["Dlouhá lehká odporová guma držená mezi oběma rukama, bez kotvy. Potřebuje dost volné délky pro zvolený úchop; krátká smyčka kolem zápěstí není automaticky stejná pomůcka.","A long light resistance band held between both hands, without an anchor. It needs enough free length for the chosen grip; a short loop around the wrists is not automatically equivalent."]},"taxonomy":{"movements":["joint"],"focus":["strength","coordination"],"positions":["standing"],"supports":[],"equipmentRequirements":[["long_light_band"]],"priority":1},"policy":{"id":"pullapart","measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"none","requirements":[["long_light_band"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false,"blockedMotionSources":["/exercise-motion/pullapart-e3e23d51a3e4455f.mp4"]},"art":{"appId":"pullapart","atlasId":"pullapart","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"05c549b6a9fa512d4a5a6dd48b9294fd2e1d6ad0df2b15904cd3df8d5f3c92e6","thumb":"/unified-atlas/pullapart-b459ac5cffe92eda-thumb.webp","detail":"/unified-atlas/pullapart-16102359daf015fd-detail.webp","inkThumb":"/unified-atlas/pullapart-5ede6134ac1b7c58-inkThumb.webp","inkDetail":"/unified-atlas/pullapart-85aa2e5344132fcb-inkDetail.webp","fillThumb":"/unified-atlas/pullapart-263a46b350f7f1d9-fillThumb.webp","fillDetail":"/unified-atlas/pullapart-238adb088b1c0ace-fillDetail.webp"},"sourceSha256":"05c549b6a9fa512d4a5a6dd48b9294fd2e1d6ad0df2b15904cd3df8d5f3c92e6","contourOnly":true,"darkOutline":true},"libraryOrder":2000,"deliveryProfiles":{"77884a869a172146":{"fields":{"id":"pullapart","cz":"Roztahování gumy","en":"Band Pull-Apart","pat":"tah","eq":["long_light_band"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":60,"unilateral":false,"sideMode":"none","focus":["Rozevírej paže plynule, lopatky se mohou přibližovat i vracet.","Open the arms smoothly, allowing the shoulder blades to draw together and return."],"startPosition":["Postav se pohodlně a uchop dlouhou lehkou gumu oběma rukama před hrudníkem přibližně ve výšce ramen. Začni s malým napětím a takovou vzdáleností rukou, abys pohyb zvládl plynule. Lokty nech téměř natažené, bez násilného propnutí.","Stand comfortably and hold a long light band between both hands in front of the chest, around shoulder height. Start with light tension and hand spacing that allows smooth movement. Keep the elbows nearly straight without forcing them into lockout."],"execution":["Pomalu rozevírej paže do stran a nech lopatky přiblížit. Skonči v ovládaném rozsahu, nejvýše přibližně s pažemi v rovině trupu; dotyk gumy s hrudníkem není podmínkou. Vrať ruce před sebe bez povolení gumy trhnutím. Rozevření a návrat je jedno opakování; neprováděj přítah ohýbáním loktů.","Slowly open the arms out to the sides and allow the shoulder blades to draw together. Stop within a controlled range, at most roughly with the arms in line with the torso; the band does not have to touch the chest. Bring the hands forward without letting the band snap back. One opening and return is one repetition; do not turn it into a row by bending the elbows."],"watchFor":["Trup nech klidný, nevystrkuj žebra a nezískávej rozsah záklonem. Ramena netlač silou dolů ani nezvedej k uším. Zvol menší dráhu nebo lehčí tah, pokud se pohyb mění v cukání.","Keep the trunk steady without flaring the ribs or leaning back to gain range. Do not force the shoulders down or shrug toward the ears. Use a smaller path or lighter tension if the movement becomes jerky."]},"progression":["Lehčí: slabší guma, delší volný úsek mezi rukama nebo kratší rozevření. Dále můžeš zpomalit návrat či krátce zastavit, pokud držíš stejnou polohu. Typ gumy a úchop si poznamenej; barva gumy není univerzální hmotnost v kg.","Easier: use a lighter band, a longer free section between the hands or a shorter opening. You may then slow the return or pause briefly while keeping the same position. Note the band and grip used; band colour is not a universal load in kilograms."]}}},"ig27_forearm_scap_press":{"id":"ig27_forearm_scap_press","segment":"D","edits":{"exe":["Odtlač předloktími podlahu tak, aby se lopatky mírně vzdálily a horní část zad se lehce zakulatila. Potom se vrať do výchozí polohy bez nekontrolovaného propadnutí hrudníku. Úhel loktů se nemění. Odtlačení a návrat je jedno opakování obou stran současně, nikoli čas výdrže.","Press the forearms into the floor so the shoulder blades spread slightly and the upper back gently rounds. Return to the starting position without letting the chest collapse. Keep the elbow angle unchanged. One press and return is one repetition with both sides together, not a timed hold."],"equipmentDetail":["Pevná neklouzavá plocha pro obě předloktí a přední části chodidel. Podložka pod předloktí je volitelná; žádná guma ani přídavná zátěž není potřeba. Při lehčí podobě se opírají také kolena.","A firm non-slip surface for both forearms and forefeet. Padding under the forearms is optional; no band or added weight is required. The knees are also supported in the easier version."]},"taxonomy":{"movements":["joint","trunk_stability"],"focus":["strength","coordination"],"positions":["forearm_plank"],"supports":["forearm_support"],"equipmentRequirements":[["telo"]],"priority":1},"policy":{"id":"ig27_forearm_scap_press","measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"none","requirements":[["telo"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false},"art":{"appId":"ig27_forearm_scap_press","atlasId":"ig27_forearm_scap_press","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"bb23b099444e0c148176a39a125acdedd2fe68c9523191f9fbab85c258bed888","thumb":"/expansion-atlas/ig27_forearm_scap_press-original-256.webp","detail":"/expansion-atlas/ig27_forearm_scap_press-original-960.webp","inkThumb":"/expansion-atlas/ig27_forearm_scap_press-ink-256.webp","inkDetail":"/expansion-atlas/ig27_forearm_scap_press-ink-960.webp","fillThumb":"/expansion-atlas/ig27_forearm_scap_press-fill-256.webp","fillDetail":"/expansion-atlas/ig27_forearm_scap_press-fill-960.webp"},"sourceSha256":"bb23b099444e0c148176a39a125acdedd2fe68c9523191f9fbab85c258bed888","contourOnly":true,"darkOutline":true},"libraryOrder":2001,"deliveryProfiles":{"ba62d63108362759":{"fields":{"id":"ig27_forearm_scap_press","cz":"Odtlačování přes lopatky v prkně na předloktí","en":"Forearm-Plank Scapular Press","pat":"stred","eq":["telo"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":60,"unilateral":false,"sideMode":"none","focus":["Předloktí zůstávají opřená, pohybuje se hrudník mezi lopatkami.","Keep the forearms grounded while the chest moves between the shoulder blades."],"startPosition":["Opři se o obě předloktí, lokty přibližně pod rameny. Natáhni nohy a vytvoř prkno s oporou o přední části chodidel. Předloktí nech rovnoběžná.","Rest on both forearms with elbows roughly below the shoulders. Extend the legs into a plank on the forefeet. Keep the forearms parallel."],"execution":["Odtlač předloktími podlahu tak, aby se lopatky mírně vzdálily a horní část zad se lehce zakulatila. Potom se vrať do výchozí polohy bez nekontrolovaného propadnutí hrudníku. Úhel loktů se nemění. Odtlačení a návrat je jedno opakování obou stran současně, nikoli čas výdrže.","Press the forearms into the floor so the shoulder blades spread slightly and the upper back gently rounds. Return to the starting position without letting the chest collapse. Keep the elbow angle unchanged. One press and return is one repetition with both sides together, not a timed hold."],"watchFor":["Pánev drž ve stejné výšce; pohyb neprováděj střídavým prohýbáním beder. Hlava pokračuje v linii trupu a dech neustává. Malý ovládaný rozsah stačí.","Keep pelvic height steady; do not create the movement by repeatedly arching the lower back. Keep the head aligned with the trunk and continue breathing. A small controlled range is enough."]},"progression":["Lehčí: polož kolena na podlahu a zachovej pohyb lopatek. Těžší: krátce vydrž v odtlačení nebo zpomal návrat, aniž bys měnil polohu pánve.","Easier: rest the knees on the floor while keeping the scapular movement. Harder: pause briefly in the reach or return more slowly without changing pelvic position."]}}},"ig27_prone_band_press":{"id":"ig27_prone_band_press","segment":"D","edits":{"eq":["long_light_band"],"pos":["Lehni si na břicho, nohy i pánev nech opřené. Uchop dlouhou lehkou gumu oběma rukama před hlavou a mírně ji napni do stran. Lokty pokrč do polohy W. Krk nech dlouhý a hlavu nízko; čelo můžeš pohodlně podložit, pokud tím neomezíš pohyb rukou.","Lie face down with the legs and pelvis supported. Hold a long light band between both hands in front of the head and apply slight outward tension. Bend the elbows into a W. Keep the neck long and the head low; you may comfortably support the forehead if this leaves the hands free to move."],"exe":["Při mírném tahu rukou od sebe pomalu posouvej paže vpřed směrem do vzpažení jen tak daleko, jak zvládneš bez záklonu. Potom pokrč lokty zpět do W. Ruce zůstávají nízko nad zemí a guma před hlavou. Pohyb z W vpřed a zpět do W je jedno společné opakování.","With gentle outward hand tension, slowly reach the arms forward toward overhead only as far as you can without arching. Then bend the elbows back into a W. Keep the hands low above the floor and the band in front of the head. One reach from W and return to W is one combined repetition."],"pro":["Lehčí: kratší dosah a menší tah, s krátkým odpočinkem paží na zemi mezi opakováními. Pohyb bez gumy je odlehčená podoba; zvolenou verzi si poznamenej. Dále můžeš zpomalit návrat nebo krátce zastavit v ovládané poloze. Silnější guma ani delší výdrž nejsou povinný postup.","Easier: use a shorter reach and lighter tension, briefly resting the arms on the floor between repetitions. Moving without the band is an easier variation; note which version you use. You may then slow the return or pause briefly in a controlled position. A firmer band or longer hold is not a required progression."],"equipmentDetail":["Dlouhá lehká elastická guma držená mezi rukama, bez ukotvení. Nesmí omezovat pohodlný dosah ani vést přes krk či za hlavu. Měkká opora čela a podložka jsou volitelné. Guma kolem nadloktí patří k jinému úkolu.","A long light elastic band held between the hands, without an anchor. It must allow a comfortable reach and must not cross the neck or pass behind the head. Soft forehead support and a mat are optional. A band looped around the upper arm belongs to a different task."]},"taxonomy":{"movements":["joint"],"focus":["strength","coordination"],"positions":["prone"],"supports":[],"equipmentRequirements":[["long_light_band"]],"priority":1},"policy":{"id":"ig27_prone_band_press","measurementType":"REPS_ONLY","loadMode":"none","sideMode":"none","requirements":[["long_light_band"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false},"art":{"appId":"ig27_prone_band_press","atlasId":"ig27_prone_band_press","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"ff7d0f594c86d4783fb0806dd8d52d440e2d18545d3e692758aecc168d09f6ec","thumb":"/expansion-atlas/ig27_prone_band_press-original-256.webp","detail":"/expansion-atlas/ig27_prone_band_press-original-960.webp","inkThumb":"/expansion-atlas/ig27_prone_band_press-ink-256.webp","inkDetail":"/expansion-atlas/ig27_prone_band_press-ink-960.webp","fillThumb":"/expansion-atlas/ig27_prone_band_press-fill-256.webp","fillDetail":"/expansion-atlas/ig27_prone_band_press-fill-960.webp"},"sourceSha256":"ff7d0f594c86d4783fb0806dd8d52d440e2d18545d3e692758aecc168d09f6ec","contourOnly":true,"darkOutline":true},"libraryOrder":2002,"deliveryProfiles":{"ca12a74bd74f7785":{"fields":{"id":"ig27_prone_band_press","cz":"Vzpažování z polohy W s gumou v lehu na břiše","en":"Prone Band W-to-Overhead Press","pat":"tlak","eq":["long_light_band"],"measurementType":"REPS_ONLY","defaultRestSec":60,"unilateral":false,"sideMode":"none","focus":["Drž lehký tah do stran a gumu stále před hlavou.","Maintain light outward tension and keep the band in front of the head."],"startPosition":["Lehni si na břicho, nohy i pánev nech opřené. Uchop dlouhou lehkou gumu oběma rukama před hlavou a mírně ji napni do stran. Lokty pokrč do polohy W. Krk nech dlouhý a hlavu nízko; čelo můžeš pohodlně podložit, pokud tím neomezíš pohyb rukou.","Lie face down with the legs and pelvis supported. Hold a long light band between both hands in front of the head and apply slight outward tension. Bend the elbows into a W. Keep the neck long and the head low; you may comfortably support the forehead if this leaves the hands free to move."],"execution":["Při mírném tahu rukou od sebe pomalu posouvej paže vpřed směrem do vzpažení jen tak daleko, jak zvládneš bez záklonu. Potom pokrč lokty zpět do W. Ruce zůstávají nízko nad zemí a guma před hlavou. Pohyb z W vpřed a zpět do W je jedno společné opakování.","With gentle outward hand tension, slowly reach the arms forward toward overhead only as far as you can without arching. Then bend the elbows back into a W. Keep the hands low above the floor and the band in front of the head. One reach from W and return to W is one combined repetition."],"watchFor":["Nezvětšuj rozsah záklonem hlavy nebo beder. Použij tak lehkou gumu, aby se paže pohybovaly plynule. Nekřiž ruce a neveď gumu přes krk ani za ramena.","Do not gain range by extending the neck or lower back. Use a band light enough for smooth arm movement. Do not cross the hands or bring the band across the neck or behind the shoulders."]},"progression":["Lehčí: kratší dosah a menší tah, s krátkým odpočinkem paží na zemi mezi opakováními. Pohyb bez gumy je odlehčená podoba; zvolenou verzi si poznamenej. Dále můžeš zpomalit návrat nebo krátce zastavit v ovládané poloze. Silnější guma ani delší výdrž nejsou povinný postup.","Easier: use a shorter reach and lighter tension, briefly resting the arms on the floor between repetitions. Moving without the band is an easier variation; note which version you use. You may then slow the return or pause briefly in a controlled position. A firmer band or longer hold is not a required progression."]}}},"ig29_upper_arm_band_scap_retraction":{"id":"ig29_upper_arm_band_scap_retraction","segment":"D","edits":{"eq":["broad_upper_arm_band","fixed_anchor"],"exe":["Malým pohybem přitáhni lopatku směrem k páteři a posuň rameno vzad proti gumě. Úhel lokte ani polohu ruky neměň. Potom pomalu dovol rameni vrátit se vpřed bez trhnutí. Přitažení a návrat je jedno opakování na paži s gumou; po sérii vystřídej stranu.","Draw the shoulder blade a small distance toward the spine, moving the shoulder back against the band. Keep the elbow angle and hand position unchanged. Slowly allow the shoulder to return forward without a jerk. One retraction and return is one repetition for the arm inside the band; change sides after the set."],"equipmentDetail":["Lehká široká guma tvořící pohodlnou smyčku kolem nadloktí A pevná kotva před tělem přibližně ve výšce hrudníku. Smyčka leží nad loktem, netlačí na kloub a nesjíždí. Kotva musí odolat tahu; lehký volně stojící sloupek nestačí. Gumu nedržíš v ruce a odpor nezapisuješ jako odhadnuté kg.","A light broad band forming a comfortable loop around the upper arm AND a fixed anchor in front at about chest height. The loop sits above the elbow without pressing on the joint or slipping. The anchor must withstand the pull; a light freestanding post is not sufficient. Do not hold the band in the hand or record its resistance as estimated kilograms."]},"taxonomy":{"movements":["joint"],"focus":["strength","coordination"],"positions":["standing"],"supports":[],"equipmentRequirements":[["broad_upper_arm_band"],["fixed_anchor"]],"priority":1},"policy":{"id":"ig29_upper_arm_band_scap_retraction","measurementType":"REPS_ONLY","loadMode":"none","sideMode":"perSide","requirements":[["broad_upper_arm_band"],["fixed_anchor"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false,"sideMeaning":["Paže s gumou","Banded arm"]},"art":{"appId":"ig29_upper_arm_band_scap_retraction","atlasId":"ig29_upper_arm_band_scap_retraction","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"66541747d31dc795df4a4dd8110904cd43c992d5fa82609c2c18d88405d3c4e3","thumb":"/expansion-atlas/ig29_upper_arm_band_scap_retraction-original-256.webp","detail":"/expansion-atlas/ig29_upper_arm_band_scap_retraction-original-960.webp","inkThumb":"/expansion-atlas/ig29_upper_arm_band_scap_retraction-ink-256.webp","inkDetail":"/expansion-atlas/ig29_upper_arm_band_scap_retraction-ink-960.webp","fillThumb":"/expansion-atlas/ig29_upper_arm_band_scap_retraction-fill-256.webp","fillDetail":"/expansion-atlas/ig29_upper_arm_band_scap_retraction-fill-960.webp"},"sourceSha256":"66541747d31dc795df4a4dd8110904cd43c992d5fa82609c2c18d88405d3c4e3","contourOnly":true,"darkOutline":true},"libraryOrder":2003,"deliveryProfiles":{"4f494026e768c593":{"fields":{"id":"ig29_upper_arm_band_scap_retraction","cz":"Přitahování lopatky proti gumě kolem paže","en":"Upper-Arm-Band Scapular Retraction","pat":"tah","eq":["broad_upper_arm_band","fixed_anchor"],"measurementType":"REPS_ONLY","defaultRestSec":30,"unilateral":true,"sideMode":"perSide","focus":["Pohybuj lopatkou, úhel lokte a trup drž klidné.","Move the shoulder blade while keeping the elbow angle and torso still."],"startPosition":["Postav se čelem k úchytu. Smyčku lehké gumy nasaď kolem jedné paže nad loket a ruku pohodlně opři o bok. Ustup jen tolik, aby vznikl mírný tah vpřed; ramena nech uvolněná.","Stand facing the anchor. Place the light band loop around one upper arm above the elbow and rest the hand comfortably at the hip. Step back only enough to create a gentle forward pull; keep the shoulders relaxed."],"execution":["Malým pohybem přitáhni lopatku směrem k páteři a posuň rameno vzad proti gumě. Úhel lokte ani polohu ruky neměň. Potom pomalu dovol rameni vrátit se vpřed bez trhnutí. Přitažení a návrat je jedno opakování na paži s gumou; po sérii vystřídej stranu.","Draw the shoulder blade a small distance toward the spine, moving the shoulder back against the band. Keep the elbow angle and hand position unchanged. Slowly allow the shoulder to return forward without a jerk. One retraction and return is one repetition for the arm inside the band; change sides after the set."],"watchFor":["Nepřetáčej trup, nevystrkuj hrudník a nezvedej rameno k uchu. Guma nesmí tlačit na loket ani sjíždět. Ruku nenuť za záda; při tlaku v rameni nebo brnění zmenši tah a cvik přeruš, pokud potíže trvají.","Do not rotate the torso, thrust the chest forward or shrug. The band must not press on the elbow or slip. Do not force the hand behind the back; reduce tension for shoulder pinching or tingling and stop if it persists."]},"progression":["Lehčí: nacvič malý pohyb bez gumy, případně vsedě s opřeným předloktím. Těžší: krátká pauza vzadu a pomalejší návrat; až potom nepatrně větší tah při stejně klidném trupu.","Easier: practise the small motion without a band, or seated with the forearm supported. Harder: briefly pause at the back and return more slowly; only then add a little tension while keeping the torso equally still."]}}},"lateralraise":{"id":"lateralraise","segment":"E","edits":{"cz":"Upažování s jednoručkami","en":"Dumbbell Lateral Raise","pos":["Stůj stabilně s jednoručkou v každé ruce podél boků. Lokty nech mírně pokrčené a zápěstí přibližně v prodloužení předloktí.","Stand steadily with one dumbbell in each hand beside the hips. Keep a slight elbow bend and the wrists approximately aligned with the forearms."],"exe":["Veď obě paže do stran v pohodlné dráze, přibližně do výšky ramen nebo níž podle dostupného rozsahu, a pomalu je spusť. Jedno společné zvednutí a spuštění obou paží je jedno opakování.","Raise both arms out to the sides along a comfortable path, approximately to shoulder height or lower within your available range, then lower slowly. One shared raise and lowering of both arms is one repetition."],"wat":["Nepomáhej si rozhoupáním trupu ani odrazem nohou. Lopatky se při zdvihu mohou přirozeně pohybovat; nedrž ramena násilím dole. Udržuj podobné pokrčení loktů a neotáčej ruce nuceně palci dolů.","Avoid swinging the trunk or driving with the legs. Let the shoulder blades move naturally during the raise rather than forcing the shoulders down. Keep a similar elbow bend and do not force the thumbs downward."],"pro":["Nárok uprav lehčími činkami nebo kratší dráhou. Pomalejší spuštění či krátká pauza jsou volitelné možnosti. Guma mění odpor i způsob záznamu; tato výchozí varianta používá jednoručky.","Adjust the demand with lighter dumbbells or a shorter path. A slower lowering phase or brief pause is optional. A band changes the resistance and recording convention; this default version uses dumbbells."],"foc":["Kontrolované zvedání paží do stran s jednoručkami.","Controlled lateral arm raising with dumbbells."],"equipmentDetail":["Pár jednoruček. Zapisuj zátěž stejným způsobem jako dosud; poznamenej si, zda jde o jednu činku, nebo součet obou. Starší zápisy se nepřepočítávají.","A pair of dumbbells. Keep your existing load convention and note whether it means one dumbbell or the combined pair. Previous records are not converted."],"source":{"author":"Rogue Fitness","document":"Movement Demo | Lateral Raises","url":"https://www.roguefitness.com/theindex/movement-library/movement-demo-lateral-raises","scope":"Primary publisher setup/execution and lighter-load/shorter-range options. App uses comfortable height and free scapular motion; source health, universal suitability, injury-prevention and fixed-tempo claims are not imported. Embedded source video not watched."}},"taxonomy":{"regions":["shoulders"],"secondaryRegions":[],"movements":["joint"],"focus":["strength","coordination"],"positions":["standing"],"supports":[],"priority":1,"equipmentRequirements":[["dumbbell_pair"]],"aliases":["lateral raise","upažování s činkami"]},"policy":{"id":"lateralraise","measurementType":"WEIGHT_REPS","loadMode":"ext","sideMode":"none","requirements":[["dumbbell_pair"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":false,"allowEstimatedMax":false,"allowComparableRecords":false,"blockedMotionSources":["/exercise-motion/lateralraise-ee20d764b9fda0eb.mp4"]},"art":{"appId":"lateralraise","atlasId":"lateralraise","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"59028efa625192b2f70813a68db8d1de28d7fe5baccd5dbefc47c80f2354c515","thumb":"/unified-atlas/lateralraise-2d614661435be5b4-thumb.webp","detail":"/unified-atlas/lateralraise-e837458a81df4857-detail.webp","inkThumb":"/unified-atlas/lateralraise-4eed2280e7720225-inkThumb.webp","inkDetail":"/unified-atlas/lateralraise-9467368d85df21af-inkDetail.webp","fillThumb":"/unified-atlas/lateralraise-2f4d7fe9557c4177-fillThumb.webp","fillDetail":"/unified-atlas/lateralraise-48b7365cfe7e1229-fillDetail.webp"},"sourceSha256":"59028efa625192b2f70813a68db8d1de28d7fe5baccd5dbefc47c80f2354c515","contourOnly":true,"darkOutline":true},"libraryOrder":5000,"deliveryProfiles":{"69302c6ec2bf00d3":{"fields":{"id":"lateralraise","cz":"Upažování s jednoručkami","en":"Dumbbell Lateral Raise","pat":"tlak","eq":["zavazi","guma"],"measurementType":"WEIGHT_REPS","defaultRestSec":90,"unilateral":false,"sideMode":"none","focus":["Kontrolované zvedání paží do stran s jednoručkami.","Controlled lateral arm raising with dumbbells."],"startPosition":["Stůj stabilně s jednoručkou v každé ruce podél boků. Lokty nech mírně pokrčené a zápěstí přibližně v prodloužení předloktí.","Stand steadily with one dumbbell in each hand beside the hips. Keep a slight elbow bend and the wrists approximately aligned with the forearms."],"execution":["Veď obě paže do stran v pohodlné dráze, přibližně do výšky ramen nebo níž podle dostupného rozsahu, a pomalu je spusť. Jedno společné zvednutí a spuštění obou paží je jedno opakování.","Raise both arms out to the sides along a comfortable path, approximately to shoulder height or lower within your available range, then lower slowly. One shared raise and lowering of both arms is one repetition."],"watchFor":["Nepomáhej si rozhoupáním trupu ani odrazem nohou. Lopatky se při zdvihu mohou přirozeně pohybovat; nedrž ramena násilím dole. Udržuj podobné pokrčení loktů a neotáčej ruce nuceně palci dolů.","Avoid swinging the trunk or driving with the legs. Let the shoulder blades move naturally during the raise rather than forcing the shoulders down. Keep a similar elbow bend and do not force the thumbs downward."]},"progression":["Nárok uprav lehčími činkami nebo kratší dráhou. Pomalejší spuštění či krátká pauza jsou volitelné možnosti. Guma mění odpor i způsob záznamu; tato výchozí varianta používá jednoručky.","Adjust the demand with lighter dumbbells or a shorter path. A slower lowering phase or brief pause is optional. A band changes the resistance and recording convention; this default version uses dumbbells."]}}},"cablelatraise":{"id":"cablelatraise","segment":"E","edits":{"ez":null,"cz":"Upažování jednou paží na kladce","en":"Single-Arm Cable Lateral Raise","pos":["Nastav kladku nízko a připoj jednoruční madlo. Postav se bokem tak, aby stroj byl u nepracující paže. Madlo drž vzdálenější rukou před tělem, loket lehce pokrč a zaujmi stabilní postoj.","Set the pulley low and attach a single handle. Stand side-on with the machine beside the non-working arm. Hold the handle across the front of the body in the farther hand, soften the elbow and take a stable stance."],"exe":["Zvedni pracovní paži do strany přibližně k výšce ramene v pohodlném rozsahu. Stejnou cestou kontrolovaně spusť. Zvednutí a spuštění je jedno opakování na zvolenou stranu; druhou stranu zapisuj zvlášť.","Raise the working arm out to the side approximately to shoulder height within a comfortable range. Lower under control along the same path. One raise and lowering is one repetition on the selected side; record the other side separately."],"wat":["Neměň zdvih v úklon trupu nebo prudké přitažení ramene k uchu. Lopatku ale nedrž násilím dole. Kabel musí mít volnou dráhu mimo nohy a tělo; při tření uprav odstup.","Do not turn the raise into a trunk side-bend or a sharp shoulder shrug. Do not pin the shoulder blade down either. Keep the cable path clear of the legs and body; adjust your position if it rubs."],"pro":["Zvol menší odpor nebo kratší dráhu. Jednoručka je příbuzná možnost s jiným průběhem odporu, nikoli povinně lehčí krok. Nastavení výšky kladky a odstup si poznamenej pro příští porovnání.","Use less resistance or a shorter path. A dumbbell is a related option with a different resistance profile, not a mandatory easier step. Note the pulley height and your distance for future comparisons."],"foc":["Jednostranný zdvih proti tahu nízko nastavené kladky.","A single-arm raise against a low cable."],"equipmentDetail":["Spodní nebo nastavitelná kladka nastavená nízko a jedno madlo. Zapisuj nastavení zátěže použitého stroje; číselné údaje různých strojů nemusí znamenat stejný odpor.","A low pulley or an adjustable pulley set low, plus one handle. Record the selected load on the machine used; figures on different machines need not represent the same resistance."],"source":{"author":"Greg Everett / Catalyst Athletics","document":"Cable Lateral Raise","url":"https://www.catalystathletics.com/exercise/811/Cable-Lateral-Raise/","scope":"Primary low-cable, far-hand, lateral raising technique. Source continues above shoulder height; existing card retains an approximately shoulder-height comfortable target. No zero dumbbell tension claim, fixed dose or superiority claim. Source video not watched."}},"taxonomy":{"regions":["shoulders"],"secondaryRegions":[],"movements":["joint"],"focus":["strength","coordination"],"positions":["standing"],"supports":[],"priority":1,"equipmentRequirements":[["low_cable","adjustable_cable"],["cable_handle"]],"aliases":["single arm cable lateral raise","upažování na spodní kladce"]},"policy":{"id":"cablelatraise","measurementType":"WEIGHT_REPS","loadMode":"ext","sideMode":"perSide","requirements":[["low_cable","adjustable_cable"],["cable_handle"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":false,"allowEstimatedMax":false,"allowComparableRecords":false,"blockedMotionSources":[],"sideMeaning":["Paže s madlem","Arm holding the handle"]},"art":{"appId":"cablelatraise","atlasId":"cablelatraise","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"cd4d85dafbb98601689b7416f6ebd924fbfac087aa662a7ac450ad0e5db33df9","thumb":"/unified-atlas/cablelatraise-27bdfadcf3d961b2-thumb.webp","detail":"/unified-atlas/cablelatraise-232a2cf9e4c18912-detail.webp","inkThumb":"/unified-atlas/cablelatraise-beec311f5dde9ae0-inkThumb.webp","inkDetail":"/unified-atlas/cablelatraise-af6e1f6a27533805-inkDetail.webp","fillThumb":"/unified-atlas/cablelatraise-104897f91192d188-fillThumb.webp","fillDetail":"/unified-atlas/cablelatraise-372f799064a1a402-fillDetail.webp"},"sourceSha256":"cd4d85dafbb98601689b7416f6ebd924fbfac087aa662a7ac450ad0e5db33df9","contourOnly":true,"darkOutline":true},"libraryOrder":5002,"deliveryProfiles":{"4ace5fe48dcde7d4":{"fields":{"id":"cablelatraise","cz":"Upažování jednou paží na kladce","en":"Single-Arm Cable Lateral Raise","pat":"tlak","eq":["kladka"],"measurementType":"WEIGHT_REPS","defaultRestSec":45,"unilateral":true,"sideMode":"perSide","focus":["Jednostranný zdvih proti tahu nízko nastavené kladky.","A single-arm raise against a low cable."],"startPosition":["Nastav kladku nízko a připoj jednoruční madlo. Postav se bokem tak, aby stroj byl u nepracující paže. Madlo drž vzdálenější rukou před tělem, loket lehce pokrč a zaujmi stabilní postoj.","Set the pulley low and attach a single handle. Stand side-on with the machine beside the non-working arm. Hold the handle across the front of the body in the farther hand, soften the elbow and take a stable stance."],"execution":["Zvedni pracovní paži do strany přibližně k výšce ramene v pohodlném rozsahu. Stejnou cestou kontrolovaně spusť. Zvednutí a spuštění je jedno opakování na zvolenou stranu; druhou stranu zapisuj zvlášť.","Raise the working arm out to the side approximately to shoulder height within a comfortable range. Lower under control along the same path. One raise and lowering is one repetition on the selected side; record the other side separately."],"watchFor":["Neměň zdvih v úklon trupu nebo prudké přitažení ramene k uchu. Lopatku ale nedrž násilím dole. Kabel musí mít volnou dráhu mimo nohy a tělo; při tření uprav odstup.","Do not turn the raise into a trunk side-bend or a sharp shoulder shrug. Do not pin the shoulder blade down either. Keep the cable path clear of the legs and body; adjust your position if it rubs."]},"progression":["Zvol menší odpor nebo kratší dráhu. Jednoručka je příbuzná možnost s jiným průběhem odporu, nikoli povinně lehčí krok. Nastavení výšky kladky a odstup si poznamenej pro příští porovnání.","Use less resistance or a shorter path. A dumbbell is a related option with a different resistance profile, not a mandatory easier step. Note the pulley height and your distance for future comparisons."]}}},"cableyraise":{"id":"cableyraise","segment":"E","edits":{"cz":"Zdvih paží do Y na dvou kladkách","en":"Standing Dual-Cable Y Raise","pos":["Dvě nastavitelné kladky nastav nízko a připoj po jednom madle. Stůj čelem k zařízení, v každé ruce drž protilehlé madlo a začni s rukama před pánví. Odstup zvol tak, aby kabely vedly volně a postoj byl stabilní.","Set two adjustable pulleys low and attach one handle to each. Face the station, hold the opposite handle in each hand and begin with the hands in front of the pelvis. Choose a distance that leaves the cables clear and your stance stable."],"exe":["S mírně pokrčenými lokty zvedej paže šikmo vzhůru do pohodlného Y a vrať je před pánev. Palce nech směřovat přibližně vzhůru. Jedno společné zvednutí a spuštění obou paží je jedno opakování.","With a slight elbow bend, raise the arms diagonally upward into a comfortable Y, then return them in front of the pelvis. Keep the thumbs approximately upward. One shared raise and lowering of both arms is one repetition."],"wat":["Při vzpažení nech lopatky otáčet vzhůru. Výšku nezískávej záklonem trupu, prudkým škubnutím nebo nuceným propnutím loktů. Není nutné dosáhnout maximálního vzpažení.","Allow the shoulder blades to rotate upward as the arms rise. Do not gain height by leaning backward, jerking or forcing the elbows to lock. Maximum overhead height is not required."],"pro":["Uprav odpor nebo zkrať dráhu, pokud ztrácíš kontrolu. Krátká pauza nahoře je volitelná; samotný vyšší dosah není povinný postup. Varianta vkleče mění postoj a patří do poznámky.","Adjust the resistance or shorten the path if control is lost. A brief pause at the top is optional; a higher reach is not a required progression. Kneeling changes the setup and should be noted."],"foc":["Koordinované zvedání paží a lopatek proti lehkému tahu dvou kladek.","Coordinated raising of the arms and shoulder blades against two lightly loaded cables."],"equipmentDetail":["Dvě nastavitelné kladky použitelné současně v dolní poloze a pár madel. Jedna kladka se dvěma madly není totéž. Poznamenej nastavení obou stran i to, zda zapisuješ jednu stranu, nebo součet; dřívější zátěže se nemění.","Two adjustable pulleys usable together at the low setting, plus a pair of handles. One pulley with two handles is not equivalent. Note both settings and whether you log one side or the sum; earlier load records remain unchanged."],"source":{"author":"Jeff Cavaliere / ATHLEAN-X","document":"Best Lower Trap Exercises · Cable Overhead Trap Raise","url":"https://learn.athleanx.com/articles/back-for-men/lower-trap-exercises","scope":"Primary author describes two low cables, opposite handles and an overhead Y in kneeling. This existing app card is an explicit standing adaptation with comfortable range. Source dosage, prevention, isolated-muscle and imbalance claims are not adopted. Source video not watched."}},"taxonomy":{"regions":["shoulders"],"secondaryRegions":["back"],"movements":["joint"],"focus":["strength","coordination"],"positions":["standing"],"supports":[],"priority":2,"equipmentRequirements":[["adjustable_cable_pair"],["cable_handle_pair"]],"aliases":["standing cable Y raise","zdvih do Y na kladce"]},"policy":{"id":"cableyraise","measurementType":"WEIGHT_REPS","loadMode":"ext","sideMode":"none","requirements":[["adjustable_cable_pair"],["cable_handle_pair"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":false,"allowEstimatedMax":false,"allowComparableRecords":false,"blockedMotionSources":[]},"art":{"appId":"cableyraise","atlasId":"cableyraise","unified":true,"contourOnly":true,"darkOutline":true,"sourceSha256":"74d3b9b5ffee1f2c67f9f77bbb75bb212d3ef09adb8daceaf3ed97c4fd583b8b","primary":{"width":960,"height":960,"thumb":"/movement-audit/cableyraise-74d3b9b5ffee-256.webp","inkThumb":"/movement-audit/cableyraise-74d3b9b5ffee-256.webp","detail":"/movement-audit/cableyraise-74d3b9b5ffee-960.webp","inkDetail":"/movement-audit/cableyraise-74d3b9b5ffee-960.webp","sourceSha256":"74d3b9b5ffee1f2c67f9f77bbb75bb212d3ef09adb8daceaf3ed97c4fd583b8b"}},"libraryOrder":5004,"deliveryProfiles":{"ea4e06e4ceda99a6":{"fields":{"id":"cableyraise","cz":"Zdvih paží do Y na dvou kladkách","en":"Standing Dual-Cable Y Raise","pat":"tah","eq":["kladka"],"measurementType":"WEIGHT_REPS","defaultRestSec":45,"unilateral":false,"sideMode":"none","focus":["Koordinované zvedání paží a lopatek proti lehkému tahu dvou kladek.","Coordinated raising of the arms and shoulder blades against two lightly loaded cables."],"startPosition":["Dvě nastavitelné kladky nastav nízko a připoj po jednom madle. Stůj čelem k zařízení, v každé ruce drž protilehlé madlo a začni s rukama před pánví. Odstup zvol tak, aby kabely vedly volně a postoj byl stabilní.","Set two adjustable pulleys low and attach one handle to each. Face the station, hold the opposite handle in each hand and begin with the hands in front of the pelvis. Choose a distance that leaves the cables clear and your stance stable."],"execution":["S mírně pokrčenými lokty zvedej paže šikmo vzhůru do pohodlného Y a vrať je před pánev. Palce nech směřovat přibližně vzhůru. Jedno společné zvednutí a spuštění obou paží je jedno opakování.","With a slight elbow bend, raise the arms diagonally upward into a comfortable Y, then return them in front of the pelvis. Keep the thumbs approximately upward. One shared raise and lowering of both arms is one repetition."],"watchFor":["Při vzpažení nech lopatky otáčet vzhůru. Výšku nezískávej záklonem trupu, prudkým škubnutím nebo nuceným propnutím loktů. Není nutné dosáhnout maximálního vzpažení.","Allow the shoulder blades to rotate upward as the arms rise. Do not gain height by leaning backward, jerking or forcing the elbows to lock. Maximum overhead height is not required."]},"progression":["Uprav odpor nebo zkrať dráhu, pokud ztrácíš kontrolu. Krátká pauza nahoře je volitelná; samotný vyšší dosah není povinný postup. Varianta vkleče mění postoj a patří do poznámky.","Adjust the resistance or shorten the path if control is lost. A brief pause at the top is optional; a higher reach is not a required progression. Kneeling changes the setup and should be noted."]}}},"ex26_plate_front":{"id":"ex26_plate_front","segment":"E","edits":{"ez":null,"pos":["Stůj stabilně a drž jeden kotouč oběma rukama před stehny. Zvol kotouč, jehož protilehlé okraje nebo otvory bezpečně uchopíš. Lokty nech mírně pokrčené.","Stand steadily and hold one plate with both hands in front of the thighs. Choose a plate whose opposite edges or grip holes you can hold securely. Keep a slight elbow bend."],"exe":["Zvedni kotouč před sebe přibližně do výše ramen nebo do nižší pohodlné výšky a kontrolovaně jej spusť. Jedno zvednutí a spuštění společně oběma rukama je jedno opakování.","Raise the plate in front approximately to shoulder height or a lower comfortable height, then lower under control. One shared raise and lowering with both hands is one repetition."],"wat":["Nevyháněj kotouč vzhůru záklonem či švihem. Drž jej pevně, ale nenásilně; při nejistém úchopu zvol jinou pomůcku. Lopatky se mohou přirozeně pohybovat.","Avoid driving the plate upward by leaning back or swinging. Keep a secure, comfortable grip; choose another implement if the grip is uncertain. Allow natural movement of the shoulder blades."],"pro":["Nárok lze snížit lehčím kotoučem nebo kratší dráhou. Pauza či pomalejší spuštění jsou volitelné. Jednoručky jsou jiná možnost úchopu, ne automaticky lehčí stupeň.","Reduce the demand with a lighter plate or a shorter path. A pause or slower lowering is optional. Dumbbells offer a different grip, not an automatically easier level."],"foc":["Předpažení s jedním kotoučem drženým oběma rukama.","A front raise with one plate held in both hands."],"equipmentDetail":["Jeden bezpečně uchopitelný kotouč. Zapisuje se hmotnost celého kotouče jednou; nezdvojuj ji podle počtu rukou.","One plate that can be gripped securely. Record the weight of the whole plate once; do not double it for two hands."],"source":{"author":"Hevy","document":"Plate Front Raise","url":"https://www.hevyapp.com/exercises/how-to-plate-front-raise/","scope":"Primary publisher instructions for opposite-side plate grip and a front raise to roughly shoulder height. Comfortable range, counting and load wording are app coaching clarifications. No aesthetic, injury-prevention or prescribed-dose claims. Video not watched."}},"taxonomy":{"regions":["shoulders"],"secondaryRegions":[],"movements":["joint"],"focus":["strength","coordination"],"positions":["standing"],"supports":[],"priority":2,"equipmentRequirements":[["plate"]],"aliases":["plate front raise","předpažení s kotoučem"]},"policy":{"id":"ex26_plate_front","measurementType":"WEIGHT_REPS","loadMode":"ext","sideMode":"none","requirements":[["plate"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":false,"allowEstimatedMax":false,"allowComparableRecords":false,"blockedMotionSources":["/exercise-motion/ex26_plate_front-644c9df551e0cf54.mp4"]},"art":{"appId":"ex26_plate_front","atlasId":"ex26_plate_front","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"a0c161cd4b9a7862dc9ce8c8b8ea293109cf55c8595417cfe98f12ddfacdd3cc","thumb":"/expansion-atlas/ex26_plate_front-original-256.webp","detail":"/expansion-atlas/ex26_plate_front-original-960.webp","inkThumb":"/expansion-atlas/ex26_plate_front-ink-256.webp","inkDetail":"/expansion-atlas/ex26_plate_front-ink-960.webp","fillThumb":"/expansion-atlas/ex26_plate_front-fill-256.webp","fillDetail":"/expansion-atlas/ex26_plate_front-fill-960.webp"},"sourceSha256":"a0c161cd4b9a7862dc9ce8c8b8ea293109cf55c8595417cfe98f12ddfacdd3cc","contourOnly":true,"darkOutline":true},"libraryOrder":5006,"deliveryProfiles":{"c1cb47fd068b619b":{"fields":{"id":"ex26_plate_front","cz":"Předpažování s kotoučem","en":"Plate Front Raise","pat":"tlak","eq":["zavazi"],"measurementType":"WEIGHT_REPS","defaultRestSec":60,"unilateral":false,"sideMode":"none","focus":["Předpažení s jedním kotoučem drženým oběma rukama.","A front raise with one plate held in both hands."],"startPosition":["Stůj stabilně a drž jeden kotouč oběma rukama před stehny. Zvol kotouč, jehož protilehlé okraje nebo otvory bezpečně uchopíš. Lokty nech mírně pokrčené.","Stand steadily and hold one plate with both hands in front of the thighs. Choose a plate whose opposite edges or grip holes you can hold securely. Keep a slight elbow bend."],"execution":["Zvedni kotouč před sebe přibližně do výše ramen nebo do nižší pohodlné výšky a kontrolovaně jej spusť. Jedno zvednutí a spuštění společně oběma rukama je jedno opakování.","Raise the plate in front approximately to shoulder height or a lower comfortable height, then lower under control. One shared raise and lowering with both hands is one repetition."],"watchFor":["Nevyháněj kotouč vzhůru záklonem či švihem. Drž jej pevně, ale nenásilně; při nejistém úchopu zvol jinou pomůcku. Lopatky se mohou přirozeně pohybovat.","Avoid driving the plate upward by leaning back or swinging. Keep a secure, comfortable grip; choose another implement if the grip is uncertain. Allow natural movement of the shoulder blades."]},"progression":["Nárok lze snížit lehčím kotoučem nebo kratší dráhou. Pauza či pomalejší spuštění jsou volitelné. Jednoručky jsou jiná možnost úchopu, ne automaticky lehčí stupeň.","Reduce the demand with a lighter plate or a shorter path. A pause or slower lowering is optional. Dumbbells offer a different grip, not an automatically easier level."]}}},"ex26_machine_lateral":{"id":"ex26_machine_lateral","segment":"E","edits":{"cz":"Upažování na stroji s oporami nad lokty","en":"Seated Lateral Raise Machine","pos":["Nastav sedadlo a zátěž podle konstrukce stroje. Sedni si stabilně s chodidly na podlaze a oporami na pažích těsně nad lokty, nikoli přímo na loketním kloubu. Lokty zůstávají pokrčené; využij opěradlo, pokud je součástí stroje.","Adjust the seat and resistance to the machine design. Sit steadily with the feet on the floor and pads against the upper arms just above the elbows, not directly on the elbow joints. Keep the elbows bent and use the back support if the machine has one."],"exe":["Zvedej obě paže do stran vedením stroje přibližně k výšce ramen nebo do nižšího pohodlného rozsahu. Vrať se bez nárazu do dorazu. Jeden společný zdvih a návrat je jedno opakování.","Raise both upper arms out to the sides along the machine path, approximately to shoulder height or a lower comfortable range. Return without striking the stop. One shared raise and return is one repetition."],"wat":["Nesnaž se nevhodné nastavení obejít nakláněním trupu nebo tlakem loktů do hran opor. Pokud vedení neodpovídá tvému pohodlnému pohybu, zvol jinou variantu. Lopatky nejsou násilím přitažené dolů.","Do not compensate for unsuitable settings by leaning or pressing the elbows into pad edges. Choose a different variant if the guided path does not fit your comfortable movement. Do not force the shoulder blades down."],"pro":["Uprav nastavení, rozsah nebo zátěž. Menší krok zátěže či klidnější návrat jsou možnosti, ne povinné pořadí. Při přechodu na jiný stroj začni porovnáním provedení a nastavení.","Adjust the setup, range or load. A smaller load increment or steadier return is an option, not a required sequence. When changing machines, first compare the movement and settings."],"foc":["Upažování vsedě s oporami stroje nad lokty.","Seated lateral raising with machine pads above the elbows."],"equipmentDetail":["Stroj určený pro upažování s oporami paží nad lokty. Obecný posilovací stroj nebo kladka jej nenahrazuje. Zapiš nastavení sedadla a zvolenou zátěž; hodnoty mezi stroji nejsou přímo srovnatelné.","A lateral-raise machine with upper-arm pads above the elbows. A generic exercise machine or cable is not equivalent. Note the seat setting and selected load; numbers are not directly comparable between machines."],"source":{"author":"American Council on Exercise","document":"Lateral Shoulder Raise","url":"https://www.acefitness.org/resources/everyone/exercise-library/295/lateral-shoulder-raise/","scope":"Exact primary seated machine variant with pads above the elbows and bent elbows. App adds fit-dependent comfortable range and non-comparable machine loads. No joint-health promise or universal seat/axis prescription; source video/photographs not visually reviewed."}},"taxonomy":{"regions":["shoulders"],"secondaryRegions":[],"movements":["joint"],"focus":["strength","coordination"],"positions":["seated"],"supports":["machine"],"priority":1,"equipmentRequirements":[["lateral_raise_machine"]],"aliases":["machine lateral raise","strojové upažování"]},"policy":{"id":"ex26_machine_lateral","measurementType":"WEIGHT_REPS","loadMode":"ext","sideMode":"none","requirements":[["lateral_raise_machine"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":false,"allowEstimatedMax":false,"allowComparableRecords":false,"familyOverride":"lateral_raise","blockedMotionSources":[]},"art":{"appId":"ex26_machine_lateral","atlasId":"ex26_machine_lateral","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"c12c87dc32244028b0d7e9c3eb4e66bcda65916ccf638d6927c235c94ded8544","thumb":"/expansion-atlas/ex26_machine_lateral-original-256.webp","detail":"/expansion-atlas/ex26_machine_lateral-original-960.webp","inkThumb":"/expansion-atlas/ex26_machine_lateral-ink-256.webp","inkDetail":"/expansion-atlas/ex26_machine_lateral-ink-960.webp","fillThumb":"/expansion-atlas/ex26_machine_lateral-fill-256.webp","fillDetail":"/expansion-atlas/ex26_machine_lateral-fill-960.webp"},"sourceSha256":"c12c87dc32244028b0d7e9c3eb4e66bcda65916ccf638d6927c235c94ded8544","contourOnly":true,"darkOutline":true},"libraryOrder":5001,"deliveryProfiles":{"d1b4c0964ebf8cc7":{"fields":{"id":"ex26_machine_lateral","cz":"Upažování na stroji s oporami nad lokty","en":"Seated Lateral Raise Machine","pat":"tlak","eq":["stroj"],"measurementType":"WEIGHT_REPS","defaultRestSec":60,"unilateral":false,"sideMode":"none","focus":["Upažování vsedě s oporami stroje nad lokty.","Seated lateral raising with machine pads above the elbows."],"startPosition":["Nastav sedadlo a zátěž podle konstrukce stroje. Sedni si stabilně s chodidly na podlaze a oporami na pažích těsně nad lokty, nikoli přímo na loketním kloubu. Lokty zůstávají pokrčené; využij opěradlo, pokud je součástí stroje.","Adjust the seat and resistance to the machine design. Sit steadily with the feet on the floor and pads against the upper arms just above the elbows, not directly on the elbow joints. Keep the elbows bent and use the back support if the machine has one."],"execution":["Zvedej obě paže do stran vedením stroje přibližně k výšce ramen nebo do nižšího pohodlného rozsahu. Vrať se bez nárazu do dorazu. Jeden společný zdvih a návrat je jedno opakování.","Raise both upper arms out to the sides along the machine path, approximately to shoulder height or a lower comfortable range. Return without striking the stop. One shared raise and return is one repetition."],"watchFor":["Nesnaž se nevhodné nastavení obejít nakláněním trupu nebo tlakem loktů do hran opor. Pokud vedení neodpovídá tvému pohodlnému pohybu, zvol jinou variantu. Lopatky nejsou násilím přitažené dolů.","Do not compensate for unsuitable settings by leaning or pressing the elbows into pad edges. Choose a different variant if the guided path does not fit your comfortable movement. Do not force the shoulder blades down."]},"progression":["Uprav nastavení, rozsah nebo zátěž. Menší krok zátěže či klidnější návrat jsou možnosti, ne povinné pořadí. Při přechodu na jiný stroj začni porovnáním provedení a nastavení.","Adjust the setup, range or load. A smaller load increment or steadier return is an option, not a required sequence. When changing machines, first compare the movement and settings."]}}},"ex26_v_raise":{"id":"ex26_v_raise","segment":"E","edits":{"cz":"Šikmé předpažování s jednoručkami do V","en":"Dumbbell V-Raise","pos":["Stůj s jednoručkou v každé ruce před stehny. Dlaně natoč šikmo vzhůru v pohodlném úhlu a lokty nech mírně pokrčené.","Stand with a dumbbell in each hand in front of the thighs. Turn the palms diagonally upward at a comfortable angle and keep a slight elbow bend."],"exe":["Zvedej obě paže šikmo vpřed a do stran, mezi předpažením a upažením. Skonči přibližně ve výši ramen, případně níž, a kontrolovaně vrať. Jedno společné zvednutí a spuštění obou paží je jedno opakování.","Raise both arms diagonally forward and outward, between a front raise and a lateral raise. Finish approximately at shoulder height, or lower, then return under control. One shared raise and lowering of both arms is one repetition."],"wat":["Nesměruj činky nad hlavu jen kvůli většímu V. Trup nerozhoupávej a lokty násilím nedopínej. Zvol úhel dlaní a dráhu, ve kterých pohyb zůstává pohodlný.","Do not take the dumbbells overhead just to make a larger V. Avoid trunk swinging or forcing the elbows to lock. Choose a palm angle and path that remain comfortable."],"pro":["Nárok sníží lehčí činky nebo kratší zdvih. Pauza či pomalejší spuštění jsou volitelné. Tato dráha není povinným stupněm mezi předpažením a upažením.","Lighter dumbbells or a shorter raise reduce the demand. A pause or slower lowering is optional. This path is not a required stage between front and lateral raises."],"foc":["Zdvih šikmo vpřed a ven do výše ramen, nikoli nad hlavu.","A diagonal forward-and-outward raise to shoulder height, rather than overhead."],"equipmentDetail":["Pár jednoruček. Zapisuj zátěž stejným způsobem jako dosud; poznamenej si, zda jde o jednu činku, nebo součet obou. Starší zápisy se nepřepočítávají.","A pair of dumbbells. Keep your existing load convention and note whether it means one dumbbell or the combined pair. Previous records are not converted."],"source":{"author":"American Council on Exercise","document":"V-Raise","url":"https://www.acefitness.org/resources/everyone/exercise-library/370/v-raise/","scope":"Primary standing paired-dumbbell diagonal raise with partly upward palms and a shoulder-height endpoint. Approximate geometry is retained without imposing an exact joint angle. Source photographs/video not visually reviewed."}},"taxonomy":{"regions":["shoulders"],"secondaryRegions":[],"movements":["joint"],"focus":["strength","coordination"],"positions":["standing"],"supports":[],"priority":2,"equipmentRequirements":[["dumbbell_pair"]],"aliases":["V raise","šikmé předpažení"]},"policy":{"id":"ex26_v_raise","measurementType":"WEIGHT_REPS","loadMode":"ext","sideMode":"none","requirements":[["dumbbell_pair"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":false,"allowEstimatedMax":false,"allowComparableRecords":false,"blockedMotionSources":[]},"art":{"appId":"ex26_v_raise","atlasId":"ex26_v_raise","unified":true,"contourOnly":true,"darkOutline":true,"sourceSha256":"db92bc4a2fe5b0d8dbbfea3fa5212acbc16e66b37ca6555ae9a3bb013ef1eabb","primary":{"width":960,"height":960,"thumb":"/movement-audit/ex26_v_raise-db92bc4a2fe5-256.webp","inkThumb":"/movement-audit/ex26_v_raise-db92bc4a2fe5-256.webp","detail":"/movement-audit/ex26_v_raise-db92bc4a2fe5-960.webp","inkDetail":"/movement-audit/ex26_v_raise-db92bc4a2fe5-960.webp","sourceSha256":"db92bc4a2fe5b0d8dbbfea3fa5212acbc16e66b37ca6555ae9a3bb013ef1eabb"}},"libraryOrder":5003,"deliveryProfiles":{"bb7ce320fa251dbd":{"fields":{"id":"ex26_v_raise","cz":"Šikmé předpažování s jednoručkami do V","en":"Dumbbell V-Raise","pat":"tlak","eq":["zavazi"],"measurementType":"WEIGHT_REPS","defaultRestSec":60,"unilateral":false,"sideMode":"none","focus":["Zdvih šikmo vpřed a ven do výše ramen, nikoli nad hlavu.","A diagonal forward-and-outward raise to shoulder height, rather than overhead."],"startPosition":["Stůj s jednoručkou v každé ruce před stehny. Dlaně natoč šikmo vzhůru v pohodlném úhlu a lokty nech mírně pokrčené.","Stand with a dumbbell in each hand in front of the thighs. Turn the palms diagonally upward at a comfortable angle and keep a slight elbow bend."],"execution":["Zvedej obě paže šikmo vpřed a do stran, mezi předpažením a upažením. Skonči přibližně ve výši ramen, případně níž, a kontrolovaně vrať. Jedno společné zvednutí a spuštění obou paží je jedno opakování.","Raise both arms diagonally forward and outward, between a front raise and a lateral raise. Finish approximately at shoulder height, or lower, then return under control. One shared raise and lowering of both arms is one repetition."],"watchFor":["Nesměruj činky nad hlavu jen kvůli většímu V. Trup nerozhoupávej a lokty násilím nedopínej. Zvol úhel dlaní a dráhu, ve kterých pohyb zůstává pohodlný.","Do not take the dumbbells overhead just to make a larger V. Avoid trunk swinging or forcing the elbows to lock. Choose a palm angle and path that remain comfortable."]},"progression":["Nárok sníží lehčí činky nebo kratší zdvih. Pauza či pomalejší spuštění jsou volitelné. Tato dráha není povinným stupněm mezi předpažením a upažením.","Lighter dumbbells or a shorter raise reduce the demand. A pause or slower lowering is optional. This path is not a required stage between front and lateral raises."]}}},"ex26_diagonal_raise":{"id":"ex26_diagonal_raise","segment":"E","edits":{"cz":"Šikmý zdvih jedné jednoručky přes tělo","en":"Single-Arm Diagonal Raise","pos":["Stůj stabilně a drž jednu jednoručku před protilehlým stehnem. Pracovní loket nech lehce pokrčený, volná ruka je bez zátěže.","Stand steadily with one dumbbell in front of the opposite thigh. Keep the working elbow slightly bent and the free hand unloaded."],"exe":["Veď činku šikmo přes přední část těla a ven na stranu pracovní paže, přibližně do výše ramene nebo níž. Stejnou cestou vrať. Jedna cesta nahoru a zpět je jedno opakování na zvolenou stranu; druhou stranu zapisuj zvlášť.","Raise the dumbbell diagonally across the front of the body and outward toward the working side, approximately to shoulder height or lower. Return along the same path. One raise and return is one repetition on the selected side; record the other side separately."],"wat":["Směr tvoří pohyb paže, nikoli otočení nebo záklon celého těla. Nesnaž se činku dostat nad hlavu. Úchop a malý ohyb lokte udržuj pohodlné; nejde o švih.","Create the path with the arm rather than rotating or leaning back with the whole body. Do not force an overhead finish. Keep a comfortable grip and slight elbow bend; this is not a swing."],"pro":["Zvol lehčí jednoručku nebo kratší šikmou dráhu. Plynulé spuštění či pauza jsou volitelné; větší výška ani druhá činka nejsou součástí postupu této varianty.","Choose a lighter dumbbell or a shorter diagonal path. Smooth lowering or a pause is optional; extra height or a second dumbbell is not part of progressing this version."],"foc":["Kontrolovaný šikmý pohyb jedné paže přes tělo.","A controlled diagonal cross-body movement of one arm."],"equipmentDetail":["Jedna jednoručka. Zapiš její hmotnost a opakování dané strany; volná ruka nic nedrží.","One dumbbell. Record its weight and the repetitions on that side; the free hand holds nothing."],"source":{"author":"American Council on Exercise","document":"Diagonal Raise","url":"https://www.acefitness.org/resources/everyone/exercise-library/371/diagonal-raise/","scope":"Exact primary one-dumbbell path from the opposite thigh across and outward to shoulder height. App allows a soft elbow and comfortable lower endpoint. No named clinical diagonal, rehabilitation claim, imposed end rotation or source-video approval."}},"taxonomy":{"regions":["shoulders"],"secondaryRegions":[],"movements":["joint"],"focus":["strength","coordination"],"positions":["standing"],"supports":[],"priority":2,"equipmentRequirements":[["dumbbell"]],"aliases":["single arm diagonal raise","šikmé předpažení jednou rukou"]},"policy":{"id":"ex26_diagonal_raise","measurementType":"WEIGHT_REPS","loadMode":"ext","sideMode":"perSide","requirements":[["dumbbell"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":false,"allowEstimatedMax":false,"allowComparableRecords":false,"blockedMotionSources":["/exercise-motion/ex26_diagonal_raise-93fed909748ce007.mp4"],"sideMeaning":["Paže s činkou","Arm holding the dumbbell"]},"art":{"appId":"ex26_diagonal_raise","atlasId":"ex26_diagonal_raise","unified":true,"contourOnly":true,"darkOutline":true,"sourceSha256":"301ef2f61f2df7ced518d850fb36d6657fc31dcf6e2635e382a480579f401372","primary":{"width":960,"height":960,"thumb":"/movement-audit/ex26_diagonal_raise-301ef2f61f2d-256.webp","inkThumb":"/movement-audit/ex26_diagonal_raise-301ef2f61f2d-256.webp","detail":"/movement-audit/ex26_diagonal_raise-301ef2f61f2d-960.webp","inkDetail":"/movement-audit/ex26_diagonal_raise-301ef2f61f2d-960.webp","sourceSha256":"301ef2f61f2df7ced518d850fb36d6657fc31dcf6e2635e382a480579f401372"}},"libraryOrder":5007,"deliveryProfiles":{"d5d51d5154d7c4bd":{"fields":{"id":"ex26_diagonal_raise","cz":"Šikmý zdvih jedné jednoručky přes tělo","en":"Single-Arm Diagonal Raise","pat":"tlak","eq":["zavazi"],"measurementType":"WEIGHT_REPS","defaultRestSec":60,"unilateral":true,"sideMode":"perSide","focus":["Kontrolovaný šikmý pohyb jedné paže přes tělo.","A controlled diagonal cross-body movement of one arm."],"startPosition":["Stůj stabilně a drž jednu jednoručku před protilehlým stehnem. Pracovní loket nech lehce pokrčený, volná ruka je bez zátěže.","Stand steadily with one dumbbell in front of the opposite thigh. Keep the working elbow slightly bent and the free hand unloaded."],"execution":["Veď činku šikmo přes přední část těla a ven na stranu pracovní paže, přibližně do výše ramene nebo níž. Stejnou cestou vrať. Jedna cesta nahoru a zpět je jedno opakování na zvolenou stranu; druhou stranu zapisuj zvlášť.","Raise the dumbbell diagonally across the front of the body and outward toward the working side, approximately to shoulder height or lower. Return along the same path. One raise and return is one repetition on the selected side; record the other side separately."],"watchFor":["Směr tvoří pohyb paže, nikoli otočení nebo záklon celého těla. Nesnaž se činku dostat nad hlavu. Úchop a malý ohyb lokte udržuj pohodlné; nejde o švih.","Create the path with the arm rather than rotating or leaning back with the whole body. Do not force an overhead finish. Keep a comfortable grip and slight elbow bend; this is not a swing."]},"progression":["Zvol lehčí jednoručku nebo kratší šikmou dráhu. Plynulé spuštění či pauza jsou volitelné; větší výška ani druhá činka nejsou součástí postupu této varianty.","Choose a lighter dumbbell or a shorter diagonal path. Smooth lowering or a pause is optional; extra height or a second dumbbell is not part of progressing this version."]}}},"revfly":{"id":"revfly","segment":"F","edits":{"cz":"Rozpažování s jednoručkami v předklonu","en":"Bent-over Dumbbell Reverse Fly","eq":["dumbbell_pair"],"load":"ext","measurementType":"WEIGHT_REPS","foc":["Paže se rozevírají v ramenou. Lopatky pohyb přirozeně doprovázejí, trup zůstává klidný.","Open the arms through the shoulders. Let the shoulder blades accompany the movement while the trunk stays steady."],"pos":["Postav se stabilně, změkči kolena a předkloň se v kyčlích do polohy, kterou udržíš. V každé ruce drž lehkou jednoručku pod hrudníkem, dlaně proti sobě a lokty mírně pokrčené. Hlava navazuje na trup.","Take a stable stance, soften the knees and hinge at the hips to an angle you can maintain. Hold a light dumbbell in each hand beneath the chest, palms facing each other and elbows slightly bent. Keep the head aligned with the trunk."],"exe":["Plynule otevři obě paže do stran, přibližně k úrovni trupu nebo do kratšího pohodlného rozsahu. Zachovej podobné pokrčení loktů a pomalu vrať činky pod hrudník. Zdvih a návrat obou paží dohromady jsou jedno opakování.","Open both arms smoothly to the sides, roughly in line with the torso or through a shorter comfortable range. Keep a similar elbow bend and lower the dumbbells slowly beneath the chest. One raise and return of both arms together is one repetition."],"wat":["Nezvedej trup kvůli činkám a netahej je ohýbáním loktů jako při přítahu. Nenuť paže co nejvýš ani lopatky do trvalého sevření. Pokud předklon nedokážeš udržet, zvol menší zátěž nebo jiné provedení s oporou.","Do not lift the trunk to move the dumbbells or bend the elbows into a row. Do not force the arms as high as possible or pin the shoulder blades together. Reduce the load or choose a supported variation if you cannot maintain the hinge."],"pro":["Začni lehčími činkami a rozsahem, který ovládáš. Náročnost měň po malých krocích při stejném předklonu a tempu. Rozpažení s gumou je alternativa s jiným odporem; stroj přidává oporu hrudníku, není to přímý převod zátěže.","Start with lighter dumbbells and a range you control. Change the demand in small steps with the same hinge angle and pace. A band pull-apart is an alternative with different resistance; the machine provides chest support and its load is not directly interchangeable."],"equipmentDetail":["Pár jednoruček. Do poznámky uveď, zda tvoje kg znamenají jednu činku, nebo součet páru, a drž se stejné konvence. Staré hodnoty bez tohoto údaje nepřepočítávej.","A pair of dumbbells. Note whether your kg entry means one dumbbell or the combined pair, and use the same convention consistently. Do not reinterpret older values without that information."],"source":{"author":"Muscle & Strength","document":"Bent Over Dumbbell Reverse Fly — exercise instructions","url":"https://www.muscleandstrength.com/exercises/bent-over-dumbbell-reverse-fly.html","scope":"First-party method for a standing bilateral dumbbell reverse fly. Controlled hinge and arm raise retained; this card does not prescribe scapular fixation, a mandatory 90-degree hinge, the source pain workaround, or appearance/posture claims. Counting and recording notes are Tanmay editorial clarifications."}},"taxonomy":{"regions":["shoulders","back"],"secondaryRegions":[],"movements":["joint"],"focus":["strength"],"priority":1,"positions":["standing"],"supports":["unsupported"],"equipmentRequirements":[["dumbbell_pair"]],"aliases":["Rozpažky v předklonu","Reverse Fly","bent-over rear delt fly"]},"policy":{"id":"revfly","measurementType":"WEIGHT_REPS","loadMode":"ext","sideMode":"none","requirements":[["dumbbell_pair"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":false,"allowEstimatedMax":false,"allowComparableRecords":false,"familyOverride":"rear_delt","blockedMotionSources":["/exercise-motion/revfly-0b88dd31e6440646.mp4"]},"art":{"appId":"revfly","atlasId":"revfly","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"3e7ef2ee453842bb6e2578c51ab330f91c45c1beb203e96c91902f487797cae6","thumb":"/unified-atlas/revfly-a1c972b5a6d6fbda-thumb.webp","detail":"/unified-atlas/revfly-ac53c3fe4d521447-detail.webp","inkThumb":"/unified-atlas/revfly-bdbd7447f31b39d5-inkThumb.webp","inkDetail":"/unified-atlas/revfly-f18728dca6c4f20d-inkDetail.webp","fillThumb":"/unified-atlas/revfly-c90f8192d19be3b8-fillThumb.webp","fillDetail":"/unified-atlas/revfly-8b1f90b74f24aabf-fillDetail.webp"},"sourceSha256":"3e7ef2ee453842bb6e2578c51ab330f91c45c1beb203e96c91902f487797cae6","contourOnly":true,"darkOutline":true},"libraryOrder":6000,"deliveryProfiles":{"e4146c2ad0ea242d":{"fields":{"id":"revfly","cz":"Rozpažování s jednoručkami v předklonu","en":"Bent-over Dumbbell Reverse Fly","pat":"tah","eq":["dumbbell_pair"],"measurementType":"WEIGHT_REPS","defaultRestSec":120,"unilateral":false,"sideMode":"none","focus":["Paže se rozevírají v ramenou. Lopatky pohyb přirozeně doprovázejí, trup zůstává klidný.","Open the arms through the shoulders. Let the shoulder blades accompany the movement while the trunk stays steady."],"startPosition":["Postav se stabilně, změkči kolena a předkloň se v kyčlích do polohy, kterou udržíš. V každé ruce drž lehkou jednoručku pod hrudníkem, dlaně proti sobě a lokty mírně pokrčené. Hlava navazuje na trup.","Take a stable stance, soften the knees and hinge at the hips to an angle you can maintain. Hold a light dumbbell in each hand beneath the chest, palms facing each other and elbows slightly bent. Keep the head aligned with the trunk."],"execution":["Plynule otevři obě paže do stran, přibližně k úrovni trupu nebo do kratšího pohodlného rozsahu. Zachovej podobné pokrčení loktů a pomalu vrať činky pod hrudník. Zdvih a návrat obou paží dohromady jsou jedno opakování.","Open both arms smoothly to the sides, roughly in line with the torso or through a shorter comfortable range. Keep a similar elbow bend and lower the dumbbells slowly beneath the chest. One raise and return of both arms together is one repetition."],"watchFor":["Nezvedej trup kvůli činkám a netahej je ohýbáním loktů jako při přítahu. Nenuť paže co nejvýš ani lopatky do trvalého sevření. Pokud předklon nedokážeš udržet, zvol menší zátěž nebo jiné provedení s oporou.","Do not lift the trunk to move the dumbbells or bend the elbows into a row. Do not force the arms as high as possible or pin the shoulder blades together. Reduce the load or choose a supported variation if you cannot maintain the hinge."]},"progression":["Začni lehčími činkami a rozsahem, který ovládáš. Náročnost měň po malých krocích při stejném předklonu a tempu. Rozpažení s gumou je alternativa s jiným odporem; stroj přidává oporu hrudníku, není to přímý převod zátěže.","Start with lighter dumbbells and a range you control. Change the demand in small steps with the same hinge angle and pace. A band pull-apart is an alternative with different resistance; the machine provides chest support and its load is not directly interchangeable."]}}},"revpecdeck":{"id":"revpecdeck","segment":"F","edits":{"cz":"Rozpažování dozadu na stroji s oporou hrudníku","en":"Chest-supported Reverse Pec Deck","eq":["rear_delt_machine"],"load":"ext","measurementType":"WEIGHT_REPS","foc":["Rozpažení v ramenou se stabilní oporou hrudníku. Lopatky se mohou přirozeně pohybovat.","Open the arms through the shoulders with stable chest support. Allow the shoulder blades to move naturally."],"pos":["Použij stroj určený pro zadní rozpažování a nastav jeho ramena do tohoto režimu. Uprav sedadlo a výchozí rozevření podle návodu tak, aby byly ruce přibližně v úrovni ramen. Sedni čelem k hrudní opoře, opři chodidla a uchop madla s mírně pokrčenými lokty.","Use a machine designed for reverse flyes and set its arms to that mode. Adjust the seat and starting opening according to its instructions so the hands are roughly at shoulder level. Face the chest pad, support the feet and grasp the handles with slightly bent elbows."],"exe":["Otevři obě paže do stran v rozsahu, který ovládáš bez odlepení hrudníku. Pokrčení loktů se výrazně nemění. Pomalu vrať madla vpřed bez nárazu závaží; celý pohyb tam a zpět je jedno opakování. Po sérii nech zátěž úplně dosednout a potom pusť madla.","Open both arms to the sides through a range you control without lifting the chest from the pad. Keep a similar elbow bend. Return the handles slowly without slamming the stack; the complete outward-and-return movement is one repetition. Let the load settle fully after the set before releasing the handles."],"wat":["Nezaměňuj rozpažení za přítah s rostoucím pokrčením loktů. Krk drž pohodlně, ramena násilím nestahuj dolů a nesnaž se paže dostat co nejdál za tělo. Sedadlo, dorazy a zátěž přestavuj až po odložení odporu.","Do not turn the fly into a row by progressively bending the elbows. Keep the neck comfortable, avoid forcing the shoulders down and do not chase the farthest reach behind the body. Adjust the seat, stops and load only after unloading the mechanism."],"pro":["Lehčí: menší odpor nebo kratší pohodlná dráha. Náročnější: malý přírůstek při stejném stroji, úchopu a nastavení. Rozpažování s jednoručkami vyžaduje jinou oporu trupu; není automaticky vyšší stupeň.","Easier: less resistance or a shorter comfortable path. More demanding: a small increase on the same machine with the same grip and settings. Dumbbell reverse flyes impose a different trunk-support demand rather than an automatic next level."],"equipmentDetail":["Zadní pecdeck s madly, sedadlem a hrudní oporou; kombinovaný stroj musí mít režim zadního rozpažování. Samotný prsní pecdeck ani libovolný stroj nestačí. Zapisuj údaj odporu konkrétního stroje jednou a poznamenej nastavení; čísla různých strojů nejsou přímo srovnatelná.","A handle-based reverse pec deck with a seat and chest pad; a combined machine must support reverse-fly mode. A chest-fly-only machine or an unspecified machine is insufficient. Record the resistance setting of that machine once and note its setup; readings from different machines are not directly comparable."],"source":{"author":"Life Fitness","document":"Insignia Series Owner’s Manual 9481201 REV BE — SS-FLY, printed page 28","url":"https://device.report/m/3521428b010246f374eaa7db89ec14ec7658e756f9f35a50ad2971001bfbc4fc","scope":"Manufacturer-authored manual hosted as a mirror. Rear-deltoid mode with chest support and handles; model-specific instructions take precedence. The pictured app machine is generic, not identified as SS-FLY. No universal handle orientation, exact stop number or machine-to-machine kg equivalence is asserted."}},"taxonomy":{"regions":["shoulders","back"],"secondaryRegions":[],"movements":["joint"],"focus":["strength"],"priority":1,"positions":["seated"],"supports":["machine"],"equipmentRequirements":[["rear_delt_machine"]],"aliases":["Rozpažování na stroji","Reverse Pec Deck","zadní pecdeck"]},"policy":{"id":"revpecdeck","measurementType":"WEIGHT_REPS","loadMode":"ext","sideMode":"none","requirements":[["rear_delt_machine"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":false,"allowEstimatedMax":false,"allowComparableRecords":false,"blockedMotionSources":[]},"art":{"appId":"revpecdeck","atlasId":"revpecdeck","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"3540de7d91bc8d236192121d9bb502901cc3b5950e242a4f0fd5e6c9f3bbcef7","thumb":"/unified-atlas/revpecdeck-8862cf5eb540715e-thumb.webp","detail":"/unified-atlas/revpecdeck-71377614f93b52b5-detail.webp","inkThumb":"/unified-atlas/revpecdeck-6111e799ce63c007-inkThumb.webp","inkDetail":"/unified-atlas/revpecdeck-fb43dbd1a20496f0-inkDetail.webp","fillThumb":"/unified-atlas/revpecdeck-53772a32489b1a69-fillThumb.webp","fillDetail":"/unified-atlas/revpecdeck-33a95a894e9b6159-fillDetail.webp"},"sourceSha256":"3540de7d91bc8d236192121d9bb502901cc3b5950e242a4f0fd5e6c9f3bbcef7","contourOnly":true,"darkOutline":true},"libraryOrder":6001,"deliveryProfiles":{"5f06e55d90d8269d":{"fields":{"id":"revpecdeck","cz":"Rozpažování dozadu na stroji s oporou hrudníku","en":"Chest-supported Reverse Pec Deck","pat":"tah","eq":["rear_delt_machine"],"measurementType":"WEIGHT_REPS","defaultRestSec":45,"unilateral":false,"sideMode":"none","focus":["Rozpažení v ramenou se stabilní oporou hrudníku. Lopatky se mohou přirozeně pohybovat.","Open the arms through the shoulders with stable chest support. Allow the shoulder blades to move naturally."],"startPosition":["Použij stroj určený pro zadní rozpažování a nastav jeho ramena do tohoto režimu. Uprav sedadlo a výchozí rozevření podle návodu tak, aby byly ruce přibližně v úrovni ramen. Sedni čelem k hrudní opoře, opři chodidla a uchop madla s mírně pokrčenými lokty.","Use a machine designed for reverse flyes and set its arms to that mode. Adjust the seat and starting opening according to its instructions so the hands are roughly at shoulder level. Face the chest pad, support the feet and grasp the handles with slightly bent elbows."],"execution":["Otevři obě paže do stran v rozsahu, který ovládáš bez odlepení hrudníku. Pokrčení loktů se výrazně nemění. Pomalu vrať madla vpřed bez nárazu závaží; celý pohyb tam a zpět je jedno opakování. Po sérii nech zátěž úplně dosednout a potom pusť madla.","Open both arms to the sides through a range you control without lifting the chest from the pad. Keep a similar elbow bend. Return the handles slowly without slamming the stack; the complete outward-and-return movement is one repetition. Let the load settle fully after the set before releasing the handles."],"watchFor":["Nezaměňuj rozpažení za přítah s rostoucím pokrčením loktů. Krk drž pohodlně, ramena násilím nestahuj dolů a nesnaž se paže dostat co nejdál za tělo. Sedadlo, dorazy a zátěž přestavuj až po odložení odporu.","Do not turn the fly into a row by progressively bending the elbows. Keep the neck comfortable, avoid forcing the shoulders down and do not chase the farthest reach behind the body. Adjust the seat, stops and load only after unloading the mechanism."]},"progression":["Lehčí: menší odpor nebo kratší pohodlná dráha. Náročnější: malý přírůstek při stejném stroji, úchopu a nastavení. Rozpažování s jednoručkami vyžaduje jinou oporu trupu; není automaticky vyšší stupeň.","Easier: less resistance or a shorter comfortable path. More demanding: a small increase on the same machine with the same grip and settings. Dumbbell reverse flyes impose a different trunk-support demand rather than an automatic next level."]}}},"ex26_bb_shrug":{"id":"ex26_bb_shrug","segment":"F","edits":{"pos":["Připrav osu před stehny, nadhmat přibližně na šířku ramen nebo trochu širší. Převezmi ji z bezpečných stojanů nebo ji nejdřív zvedni samostatným zvládnutým tahem ze země. Pak se stabilně postav s měkkými koleny, dlouhými lokty a hlavou nad trupem.","Set up with the bar in front of the thighs and an overhand grip around shoulder width or slightly wider. Take it from secure rack supports or first lift it from the floor with a separate, familiar deadlift. Then stand steadily with soft knees, long elbows and head aligned over the trunk."],"exe":["Zvedni obě ramena plynule vzhůru bez pomoci nohou, krátce zastav a pomalu je spusť. Zdvih a návrat dohromady jsou jedno opakování. Po sérii vrať osu kontrolovaně do stojanů nebo na zem způsobem, který zvládáš.","Raise both shoulders smoothly without leg drive, pause briefly and lower them slowly. One raise and return is one repetition. After the set, return the bar under control to the rack or floor using a method you can manage."],"wat":["Lokty výrazně nepokrčuj, nepřidávej kruh rameny ani podřep a nevysunuj hlavu. Zátěž nesmí vytrhávat úchop. Tato karta není výbušné krčení ramen ani technika vzpěračského tahu.","Do not noticeably bend the elbows, add a shoulder circle or dip the knees, or jut the head forward. The load must remain securely gripped. This card is not a power shrug or an Olympic-pull drill."],"pro":["Začni lehčí osou nebo menší zátěží. Přidávej opakování či váhu po malých krocích při stejné dráze a tempu. Jednoručky jsou jiná pomůcka, ne automaticky lehčí stupeň; není cílem nejdelší možný zdvih.","Start with a lighter bar or less load. Add repetitions or weight in small steps with the same path and pace. Dumbbells are a different implement, not automatically an easier level; the longest possible lift is not the goal."],"equipmentDetail":["Velká činka. Pro převzetí ze stojanů jsou potřeba vhodné stojany; při variantě ze země musíš bezpečně zvládat zvednutí i odložení činky. Zapisuj celkovou hmotnost osy a kotoučů jednou, ne za každou ruku. Starší čísla ani předpisy tato poznámka nepřepočítává.","A barbell. Rack pickup requires suitable rack supports; floor pickup requires a safe, familiar lift and return. Record the total bar-and-plate mass once, not per hand. This clarification does not convert earlier values or prescriptions."],"ez":null},"taxonomy":{"regions":["shoulders","back"],"secondaryRegions":["forearms_hands"],"movements":["joint"],"focus":["strength"],"priority":1,"positions":["standing"],"supports":["unsupported"],"equipmentRequirements":[["cinka"]]},"policy":{"id":"ex26_bb_shrug","measurementType":"WEIGHT_REPS","loadMode":"ext","sideMode":"none","requirements":[["cinka"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":false,"allowEstimatedMax":false,"allowComparableRecords":false,"blockedMotionSources":["/exercise-motion/ex26_bb_shrug-cdbe7e4109789e0f.mp4"]},"art":{"appId":"ex26_bb_shrug","atlasId":"ex26_bb_shrug","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"1286c147532af8f9138f4b891c602156b8a013e7c0bbdad646785cf71cea29ce","thumb":"/expansion-atlas/ex26_bb_shrug-original-256.webp","detail":"/expansion-atlas/ex26_bb_shrug-original-960.webp","inkThumb":"/expansion-atlas/ex26_bb_shrug-ink-256.webp","inkDetail":"/expansion-atlas/ex26_bb_shrug-ink-960.webp","fillThumb":"/expansion-atlas/ex26_bb_shrug-fill-256.webp","fillDetail":"/expansion-atlas/ex26_bb_shrug-fill-960.webp"},"sourceSha256":"1286c147532af8f9138f4b891c602156b8a013e7c0bbdad646785cf71cea29ce","contourOnly":true,"darkOutline":true},"libraryOrder":6004,"deliveryProfiles":{"3385425924b18af4":{"fields":{"id":"ex26_bb_shrug","cz":"Krčení ramen s velkou činkou","en":"Barbell Shrug","pat":"tah","eq":["cinka"],"measurementType":"WEIGHT_REPS","defaultRestSec":60,"unilateral":false,"sideMode":"none","focus":["Zvedni ramena směrem vzhůru, krátce zastav a pomalu je spusť.","Raise the shoulders upward, pause briefly and lower slowly."],"startPosition":["Připrav osu před stehny, nadhmat přibližně na šířku ramen nebo trochu širší. Převezmi ji z bezpečných stojanů nebo ji nejdřív zvedni samostatným zvládnutým tahem ze země. Pak se stabilně postav s měkkými koleny, dlouhými lokty a hlavou nad trupem.","Set up with the bar in front of the thighs and an overhand grip around shoulder width or slightly wider. Take it from secure rack supports or first lift it from the floor with a separate, familiar deadlift. Then stand steadily with soft knees, long elbows and head aligned over the trunk."],"execution":["Zvedni obě ramena plynule vzhůru bez pomoci nohou, krátce zastav a pomalu je spusť. Zdvih a návrat dohromady jsou jedno opakování. Po sérii vrať osu kontrolovaně do stojanů nebo na zem způsobem, který zvládáš.","Raise both shoulders smoothly without leg drive, pause briefly and lower them slowly. One raise and return is one repetition. After the set, return the bar under control to the rack or floor using a method you can manage."],"watchFor":["Lokty výrazně nepokrčuj, nepřidávej kruh rameny ani podřep a nevysunuj hlavu. Zátěž nesmí vytrhávat úchop. Tato karta není výbušné krčení ramen ani technika vzpěračského tahu.","Do not noticeably bend the elbows, add a shoulder circle or dip the knees, or jut the head forward. The load must remain securely gripped. This card is not a power shrug or an Olympic-pull drill."]},"progression":["Začni lehčí osou nebo menší zátěží. Přidávej opakování či váhu po malých krocích při stejné dráze a tempu. Jednoručky jsou jiná pomůcka, ne automaticky lehčí stupeň; není cílem nejdelší možný zdvih.","Start with a lighter bar or less load. Add repetitions or weight in small steps with the same path and pace. Dumbbells are a different implement, not automatically an easier level; the longest possible lift is not the goal."]}}},"cablefly":{"id":"cablefly","segment":"G","edits":{"eq":["adjustable_cable_pair","cable_handle_pair"],"ez":null,"source":{"author":"American Council on Exercise","document":"Standing cable fly technique: decline and incline variations","url":"https://www.acefitness.org/resources/everyone/exercise-library/161/standing-decline-cable-flyes/","relatedUrl":"https://www.acefitness.org/resources/everyone/exercise-library/163/standing-incline-cable-flyes/","scope":"First-party descriptions support bilateral cable arcs and stable elbow angle. This pre-existing broad card permits different pulley heights; neither source makes all its historical records a single high-to-low variant. No universal outcome, dose or machine-load conversion is adopted."},"pos":["Postav se mezi dvě kladky s jedním madlem v každé ruce. Vykroč jednou nohou a zvol pevný, pohodlný postoj. Výšku kladek nastav pro zvolenou dráhu a během série ji neměň. Lokty nech mírně pokrčené, zápěstí v návaznosti na předloktí.","Stand between two pulleys, one handle in each hand. Use a comfortable, stable split stance. Set the pulley height for the chosen path and keep it unchanged through the set. Keep a slight elbow bend and the wrists aligned with the forearms."],"exe":["Plynule přibliž madla obloukem před hrudník a stejnou cestou je vrať do pohodlného rozevření. Úhel loktů se výrazně nemění, ruce není nutné křížit. Přiblížení a návrat obou paží současně je jedno opakování.","Bring the handles together in an arc in front of the chest, then return along the same path to a comfortable opening. Keep the elbow angle nearly constant; the hands need not cross. One closing and return of both arms together is one repetition."],"wat":["Trup drž klidně v zvoleném sklonu; nepřidávej předklon, záklon ani rotaci při každém opakování. Rozevření nesmí táhnout ramena násilím za tělo. Při bolesti zkrať dráhu nebo pohyb ukonči.","Keep the torso steady at the chosen angle without adding a forward lean, backward arch or twist on each repetition. Do not let the opening pull the shoulders forcibly behind the body. Shorten the path or stop if it hurts."],"pro":["Lehčí: menší odpor nebo kratší oblouk. Dále přidávej opakování či malý odpor při stejné dráze. Změna výšky kladek mění variantu, není povinný postup. Zapiš kg podle stupnice a své dosavadní konvence. Poznamenej konkrétní stroj, nastavení výšky a zda údaj znamená jednu věž nebo součet; staré zápisy nepřepočítávej. Převod kladky může měnit odpor v ruce.","Easier: less resistance or a shorter arc. Add repetitions or a small resistance increase while keeping the same path. Changing pulley height changes the variation and is not a required progression. Log kilograms using the scale and your established convention. Note the machine, pulley height and whether the figure represents one stack or the total; do not recalculate past entries. The pulley ratio can change the resistance at the hand."],"equipmentDetail":["Dvě kladky po stranách těla A pár samostatných madel; výšku musí jít nastavit pro zvolenou dráhu. Před cvičením zkontroluj zajištění madel a nech kolem sebe volný prostor. Jedna kladka se dvěma konci lana není stejná sestava.","Two pulleys on either side of the body AND a pair of separate handles, adjustable to the chosen path. Check the handle attachments and leave clear space around you. One pulley with two rope ends is not the same setup."],"load":"ext","measurementType":"WEIGHT_REPS"},"taxonomy":{"regions":["chest"],"secondaryRegions":["shoulders"],"movements":["joint"],"focus":["strength"],"priority":1,"positions":["standing"],"supports":[],"equipmentRequirements":[["adjustable_cable_pair"],["cable_handle_pair"]],"aliases":["rozpažování na kladkách","bilateral cable fly"]},"policy":{"id":"cablefly","measurementType":"WEIGHT_REPS","loadMode":"ext","sideMode":"none","requirements":[["adjustable_cable_pair"],["cable_handle_pair"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":false,"allowEstimatedMax":false,"allowComparableRecords":false},"art":{"appId":"cablefly","atlasId":"cablefly","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"93d3740070100e14b0fb6f241f670f5544b23d64d5321eb47dcaa1a3a516f194","thumb":"/unified-atlas/cablefly-165b3e4c1d5c0161-thumb.webp","detail":"/unified-atlas/cablefly-e52bb4cf457eb8fe-detail.webp","inkThumb":"/unified-atlas/cablefly-1ca0d6510d7125e3-inkThumb.webp","inkDetail":"/unified-atlas/cablefly-b53aa54b9607b891-inkDetail.webp","fillThumb":"/unified-atlas/cablefly-6730251af6573258-fillThumb.webp","fillDetail":"/unified-atlas/cablefly-16e040a52aaf7849-fillDetail.webp"},"sourceSha256":"93d3740070100e14b0fb6f241f670f5544b23d64d5321eb47dcaa1a3a516f194","contourOnly":true,"darkOutline":true},"libraryOrder":7000,"deliveryProfiles":{"34e94445f786e14b":{"fields":{"id":"cablefly","cz":"Stahování kladek","en":"Cable Fly","pat":"tlak","eq":["adjustable_cable_pair","cable_handle_pair"],"measurementType":"WEIGHT_REPS","defaultRestSec":120,"unilateral":false,"sideMode":"none","focus":["Objímáš strom — lokty drží stálý oblouk.","You're hugging a tree — the elbows hold one constant arc."],"startPosition":["Postav se mezi dvě kladky s jedním madlem v každé ruce. Vykroč jednou nohou a zvol pevný, pohodlný postoj. Výšku kladek nastav pro zvolenou dráhu a během série ji neměň. Lokty nech mírně pokrčené, zápěstí v návaznosti na předloktí.","Stand between two pulleys, one handle in each hand. Use a comfortable, stable split stance. Set the pulley height for the chosen path and keep it unchanged through the set. Keep a slight elbow bend and the wrists aligned with the forearms."],"execution":["Plynule přibliž madla obloukem před hrudník a stejnou cestou je vrať do pohodlného rozevření. Úhel loktů se výrazně nemění, ruce není nutné křížit. Přiblížení a návrat obou paží současně je jedno opakování.","Bring the handles together in an arc in front of the chest, then return along the same path to a comfortable opening. Keep the elbow angle nearly constant; the hands need not cross. One closing and return of both arms together is one repetition."],"watchFor":["Trup drž klidně v zvoleném sklonu; nepřidávej předklon, záklon ani rotaci při každém opakování. Rozevření nesmí táhnout ramena násilím za tělo. Při bolesti zkrať dráhu nebo pohyb ukonči.","Keep the torso steady at the chosen angle without adding a forward lean, backward arch or twist on each repetition. Do not let the opening pull the shoulders forcibly behind the body. Shorten the path or stop if it hurts."]},"progression":["Lehčí: menší odpor nebo kratší oblouk. Dále přidávej opakování či malý odpor při stejné dráze. Změna výšky kladek mění variantu, není povinný postup. Zapiš kg podle stupnice a své dosavadní konvence. Poznamenej konkrétní stroj, nastavení výšky a zda údaj znamená jednu věž nebo součet; staré zápisy nepřepočítávej. Převod kladky může měnit odpor v ruce.","Easier: less resistance or a shorter arc. Add repetitions or a small resistance increase while keeping the same path. Changing pulley height changes the variation and is not a required progression. Log kilograms using the scale and your established convention. Note the machine, pulley height and whether the figure represents one stack or the total; do not recalculate past entries. The pulley ratio can change the resistance at the hand."]}}},"ex26_db_flat_fly":{"id":"ex26_db_flat_fly","segment":"G","edits":{"eq":["dumbbell_pair","flat_bench"],"exe":["Otevírej obě paže do stran v oblouku. Zastav v pohodlném rozsahu, zpravidla kolem úrovně trupu, a stejným obloukem je vrať nad hrudník. Lokty zůstávají mírně pokrčené a činky do sebe nenarážejí. Rozevření a návrat obou paží je jedno opakování.","Open both arms sideways in an arc. Stop in a comfortable range, usually around torso level, then reverse the arc above the chest. Keep the elbows slightly bent and avoid banging the dumbbells together. One opening and return of both arms is one repetition."],"pro":["Lehčí: menší činky nebo kratší oblouk. Dále přidej opakování a teprve podle kontroly malou zátěž; větší hloubka není nutný postup. Prsní stroj je jiná možnost s vlastními záznamy, ne automaticky lehčí úroveň. U páru činek dodrž dosavadní konvenci zápisu kg a poznamenej, zda uvádíš jednu činku nebo součet. Staré záznamy neděl ani nenásob.","Easier: lighter dumbbells or a shorter arc. Add repetitions and, when control permits, a small load increase; extra depth is not required. A chest-fly machine is another option with separate records, not automatically an easier level. For a dumbbell pair, retain your established kilogram convention and note whether you record one dumbbell or the total. Do not divide or multiply old entries."],"equipmentDetail":["Pár jednoruček A pevná rovná lavice s oporou hlavy, zad a pánve. Chodidla opři o zem nebo vhodnou stabilní podložku, pokud nedosáhnou. Vstup i odložení činek musí být ovladatelné; podle potřeby využij připravenou dopomoc.","A pair of dumbbells AND a stable flat bench supporting the head, back and pelvis. Plant the feet on the floor or a suitable firm riser if needed. Keep setup and putting the weights down under control; use prepared assistance when required."]},"taxonomy":{"regions":["chest"],"secondaryRegions":["shoulders"],"movements":["joint"],"focus":["strength"],"priority":1,"positions":["supine"],"supports":["chair_bench"],"equipmentRequirements":[["dumbbell_pair"],["flat_bench"]],"aliases":[]},"policy":{"id":"ex26_db_flat_fly","measurementType":"WEIGHT_REPS","loadMode":"ext","sideMode":"none","requirements":[["dumbbell_pair"],["flat_bench"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":false,"allowEstimatedMax":false,"allowComparableRecords":false,"blockedMotionSources":["/exercise-motion/ex26_db_flat_fly-7062e913a5650d19.mp4"]},"art":{"appId":"ex26_db_flat_fly","atlasId":"ex26_db_flat_fly","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"19e0c3e6ead2f53876c016b31f93eb0dee2e406dd50c3a4937c37357c3e0bd68","thumb":"/expansion-atlas/ex26_db_flat_fly-original-256.webp","detail":"/expansion-atlas/ex26_db_flat_fly-original-960.webp","inkThumb":"/expansion-atlas/ex26_db_flat_fly-ink-256.webp","inkDetail":"/expansion-atlas/ex26_db_flat_fly-ink-960.webp","fillThumb":"/expansion-atlas/ex26_db_flat_fly-fill-256.webp","fillDetail":"/expansion-atlas/ex26_db_flat_fly-fill-960.webp"},"sourceSha256":"19e0c3e6ead2f53876c016b31f93eb0dee2e406dd50c3a4937c37357c3e0bd68","contourOnly":true,"darkOutline":true},"libraryOrder":7002,"deliveryProfiles":{"98649d06b73def90":{"fields":{"id":"ex26_db_flat_fly","cz":"Rozpažování s jednoručkami na rovné lavici","en":"Flat Dumbbell Fly","pat":"tlak","eq":["dumbbell_pair","flat_bench"],"measurementType":"WEIGHT_REPS","defaultRestSec":60,"unilateral":false,"sideMode":"none","focus":["Otevírej paže do stran v oblouku.","Open the arms sideways in an arc."],"startPosition":["Lehni si na rovnou lavici s chodidly na zemi. Drž lehké činky nad hrudníkem, dlaně proti sobě a lokty mírně pokrčené.","Lie on a flat bench with feet grounded. Hold light dumbbells above the chest, palms facing and elbows slightly bent."],"execution":["Otevírej obě paže do stran v oblouku. Zastav v pohodlném rozsahu, zpravidla kolem úrovně trupu, a stejným obloukem je vrať nad hrudník. Lokty zůstávají mírně pokrčené a činky do sebe nenarážejí. Rozevření a návrat obou paží je jedno opakování.","Open both arms sideways in an arc. Stop in a comfortable range, usually around torso level, then reverse the arc above the chest. Keep the elbows slightly bent and avoid banging the dumbbells together. One opening and return of both arms is one repetition."],"watchFor":["Nespouštěj lokty hluboko za tělo a neměň cvik v tlak opakovaným ohýbáním loktů.","Do not lower the elbows far behind the torso or turn the movement into a press by repeatedly bending the elbows."]},"progression":["Lehčí: menší činky nebo kratší oblouk. Dále přidej opakování a teprve podle kontroly malou zátěž; větší hloubka není nutný postup. Prsní stroj je jiná možnost s vlastními záznamy, ne automaticky lehčí úroveň. U páru činek dodrž dosavadní konvenci zápisu kg a poznamenej, zda uvádíš jednu činku nebo součet. Staré záznamy neděl ani nenásob.","Easier: lighter dumbbells or a shorter arc. Add repetitions and, when control permits, a small load increase; extra depth is not required. A chest-fly machine is another option with separate records, not automatically an easier level. For a dumbbell pair, retain your established kilogram convention and note whether you record one dumbbell or the total. Do not divide or multiply old entries."]}}},"ex26_pecdeck":{"id":"ex26_pecdeck","segment":"G","edits":{"eq":["chest_fly_machine"],"hd":null,"pos":["Nastav prsní rozpažovací stroj podle jeho návodu: opři záda, chodidla a nastav sed tak, aby nadloktí nebyla vytažená vysoko nad ramena. U madlové verze drž madla, u opěrkové polož předloktí na určené polštáře. Zvol pohodlné výchozí rozevření a zajištěnou zátěž.","Set up the chest-fly machine according to its instructions: support the back and feet and adjust the seat so the upper arms are not raised high above the shoulders. Hold the handles on a handle-based model, or place the forearms on the designated pads. Select a comfortable starting width and secure the load setting."],"exe":["Plynule přibliž obě paže před hrudník a pomalu je vrať do zvoleného rozevření. Trup zůstává opřený a úhel loktů odpovídá konkrétnímu stroji; nevytvářej tlak dopínáním loktů. Přiblížení a návrat je jedno společné opakování.","Bring both arms together in front of the chest and return slowly to the chosen opening. Keep the torso supported and the elbow angle appropriate to the machine; do not turn it into a press by straightening the elbows. One closing and return is one combined repetition."],"pro":["Lehčí: menší odpor a užší rozevření. Dále přidávej opakování či malý odpor při stejném nastavení. Zapisuj údaj na konkrétním stroji a poznamenej model i nastavení sedu/rozsahu. Číslo není přenosný ekvivalent jednoruček nebo jiného stroje.","Easier: less resistance and a narrower opening. Add repetitions or a small resistance increase with the same settings. Record the indicated load and note the machine, seat and range settings. The number is not a transferable equivalent of dumbbells or another machine."],"equipmentDetail":["Prsní rozpažovací stroj s nastavitelným sedem, zádovou opěrou a madly nebo opěrkami předloktí. Kombinovaný pec deck musí být nastavený na přední rozpažování. Stroj pouze na rozpažení dozadu ani běžný prsní tlak tuto funkci nesplňuje.","A chest-fly machine with an adjustable seat, back support and handles or forearm pads. A combination pec deck must be set to its chest-fly mode. A rear-delt-only machine or a chest-press machine does not meet this requirement."]},"taxonomy":{"regions":["chest"],"secondaryRegions":["shoulders"],"movements":["joint"],"focus":["strength"],"priority":1,"positions":["seated"],"supports":["machine"],"equipmentRequirements":[["chest_fly_machine"]],"aliases":["prsní pec deck"]},"policy":{"id":"ex26_pecdeck","measurementType":"WEIGHT_REPS","loadMode":"ext","sideMode":"none","requirements":[["chest_fly_machine"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":false,"allowEstimatedMax":false,"allowComparableRecords":false},"art":{"appId":"ex26_pecdeck","atlasId":"ex26_pecdeck","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"1e8bb73ab90c77dfe0aab6a3c67a539c0f9ce1e9d73cbeef7760a1e4179c9372","thumb":"/expansion-atlas/ex26_pecdeck-original-256.webp","detail":"/expansion-atlas/ex26_pecdeck-original-960.webp","inkThumb":"/expansion-atlas/ex26_pecdeck-ink-256.webp","inkDetail":"/expansion-atlas/ex26_pecdeck-ink-960.webp","fillThumb":"/expansion-atlas/ex26_pecdeck-fill-256.webp","fillDetail":"/expansion-atlas/ex26_pecdeck-fill-960.webp"},"sourceSha256":"1e8bb73ab90c77dfe0aab6a3c67a539c0f9ce1e9d73cbeef7760a1e4179c9372","contourOnly":true,"darkOutline":true},"libraryOrder":7003,"deliveryProfiles":{"f69ef477e4993355":{"fields":{"id":"ex26_pecdeck","cz":"Rozpažování na prsním stroji","en":"Pec Deck Chest Fly","pat":"tlak","eq":["chest_fly_machine"],"measurementType":"WEIGHT_REPS","defaultRestSec":60,"unilateral":false,"sideMode":"none","focus":["Přibližuj paže před hrudníkem a pomalu je rozevírej.","Bring the arms together in front of the chest, then open slowly."],"startPosition":["Nastav prsní rozpažovací stroj podle jeho návodu: opři záda, chodidla a nastav sed tak, aby nadloktí nebyla vytažená vysoko nad ramena. U madlové verze drž madla, u opěrkové polož předloktí na určené polštáře. Zvol pohodlné výchozí rozevření a zajištěnou zátěž.","Set up the chest-fly machine according to its instructions: support the back and feet and adjust the seat so the upper arms are not raised high above the shoulders. Hold the handles on a handle-based model, or place the forearms on the designated pads. Select a comfortable starting width and secure the load setting."],"execution":["Plynule přibliž obě paže před hrudník a pomalu je vrať do zvoleného rozevření. Trup zůstává opřený a úhel loktů odpovídá konkrétnímu stroji; nevytvářej tlak dopínáním loktů. Přiblížení a návrat je jedno společné opakování.","Bring both arms together in front of the chest and return slowly to the chosen opening. Keep the torso supported and the elbow angle appropriate to the machine; do not turn it into a press by straightening the elbows. One closing and return is one combined repetition."],"watchFor":["Nepouštěj paže za rozsah, který ovládáš, a nenech závaží dopadat. Vstup do stroje nesmí vyžadovat bolestivé vytočení ramene.","Stay within controlled range and do not drop the stack. Getting into the machine must not require painful shoulder rotation."]},"progression":["Lehčí: menší odpor a užší rozevření. Dále přidávej opakování či malý odpor při stejném nastavení. Zapisuj údaj na konkrétním stroji a poznamenej model i nastavení sedu/rozsahu. Číslo není přenosný ekvivalent jednoruček nebo jiného stroje.","Easier: less resistance and a narrower opening. Add repetitions or a small resistance increase with the same settings. Record the indicated load and note the machine, seat and range settings. The number is not a transferable equivalent of dumbbells or another machine."]}}},"ex26_cable_decline_fly":{"id":"ex26_cable_decline_fly","segment":"G","edits":{"eq":["adjustable_cable_pair","cable_handle_pair"],"pos":["Obě kladky nastav přibližně k hlavě a připoj samostatná madla. Uchop je, vykroč do stabilního postoje a drž trup přibližně vzpřímeně. Lokty mírně pokrč, zápěstí drž v návaznosti na předloktí.","Set both pulleys around head height and attach separate handles. Take the handles, adopt a stable split stance and keep the torso roughly upright. Keep the elbows softly bent and the wrists aligned with the forearms."],"exe":["Spoj ruce obloukem shora dolů před spodní částí hrudníku. Pomalu otevři paže stejnou cestou do pohodlného rozsahu, bez tažení rukou hluboko za tělo. Úhel loktů drž přibližně stejný. Přiblížení a návrat obou paží je jedno opakování.","Sweep the hands down and inward to meet in front of the lower chest. Reopen along the same path within a comfortable range, without letting the hands travel far behind the body. Keep the elbow angle nearly constant. One closing and return of both arms is one repetition."],"pro":["Lehčí: menší odpor a kratší oblouk. Dále přidej opakování či malý odpor při stejné dráze a klidném trupu. Zapiš kg podle stupnice a své dosavadní konvence. Poznamenej konkrétní stroj, nastavení výšky a zda údaj znamená jednu věž nebo součet; staré zápisy nepřepočítávej. Převod kladky může měnit odpor v ruce.","Easier: lighter resistance and a smaller arc. Add repetitions or a small resistance increase while keeping the path and torso steady. Log kilograms using the scale and your established convention. Note the machine, pulley height and whether the figure represents one stack or the total; do not recalculate past entries. The pulley ratio can change the resistance at the hand."],"equipmentDetail":["Dvě kladky po stranách těla A pár samostatných madel; výšku musí jít nastavit pro zvolenou dráhu. Před cvičením zkontroluj zajištění madel a nech kolem sebe volný prostor. Jedna kladka se dvěma konci lana není stejná sestava.","Two pulleys on either side of the body AND a pair of separate handles, adjustable to the chosen path. Check the handle attachments and leave clear space around you. One pulley with two rope ends is not the same setup."]},"taxonomy":{"regions":["chest"],"secondaryRegions":["shoulders"],"movements":["joint"],"focus":["strength"],"priority":1,"positions":["standing"],"supports":[],"equipmentRequirements":[["adjustable_cable_pair"],["cable_handle_pair"]],"aliases":[]},"policy":{"id":"ex26_cable_decline_fly","measurementType":"WEIGHT_REPS","loadMode":"ext","sideMode":"none","requirements":[["adjustable_cable_pair"],["cable_handle_pair"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":false,"allowEstimatedMax":false,"allowComparableRecords":false},"art":{"appId":"ex26_cable_decline_fly","atlasId":"ex26_cable_decline_fly","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"346d39d70b93590d9eab4a210937ea88db8cbfc24c32539445c85859a9c9a943","thumb":"/expansion-atlas/ex26_cable_decline_fly-original-256.webp","detail":"/expansion-atlas/ex26_cable_decline_fly-original-960.webp","inkThumb":"/expansion-atlas/ex26_cable_decline_fly-ink-256.webp","inkDetail":"/expansion-atlas/ex26_cable_decline_fly-ink-960.webp","fillThumb":"/expansion-atlas/ex26_cable_decline_fly-fill-256.webp","fillDetail":"/expansion-atlas/ex26_cable_decline_fly-fill-960.webp"},"sourceSha256":"346d39d70b93590d9eab4a210937ea88db8cbfc24c32539445c85859a9c9a943","contourOnly":true,"darkOutline":true},"libraryOrder":7004,"deliveryProfiles":{"e368b4fd17444922":{"fields":{"id":"ex26_cable_decline_fly","cz":"Rozpažování na kladkách shora dolů","en":"High-to-Low Cable Fly","pat":"tlak","eq":["adjustable_cable_pair","cable_handle_pair"],"measurementType":"WEIGHT_REPS","defaultRestSec":60,"unilateral":false,"sideMode":"none","focus":["S lehce pokrčenými lokty spoj ruce obloukem před spodní částí hrudníku.","With softly bent elbows, sweep hands together in front of the lower chest."],"startPosition":["Obě kladky nastav přibližně k hlavě a připoj samostatná madla. Uchop je, vykroč do stabilního postoje a drž trup přibližně vzpřímeně. Lokty mírně pokrč, zápěstí drž v návaznosti na předloktí.","Set both pulleys around head height and attach separate handles. Take the handles, adopt a stable split stance and keep the torso roughly upright. Keep the elbows softly bent and the wrists aligned with the forearms."],"execution":["Spoj ruce obloukem shora dolů před spodní částí hrudníku. Pomalu otevři paže stejnou cestou do pohodlného rozsahu, bez tažení rukou hluboko za tělo. Úhel loktů drž přibližně stejný. Přiblížení a návrat obou paží je jedno opakování.","Sweep the hands down and inward to meet in front of the lower chest. Reopen along the same path within a comfortable range, without letting the hands travel far behind the body. Keep the elbow angle nearly constant. One closing and return of both arms is one repetition."],"watchFor":["Neměň cvik v tlak ohýbáním loktů a nezískávej rozsah záklonem.","Do not turn the fly into a press by bending elbows or gain range by arching back."]},"progression":["Lehčí: menší odpor a kratší oblouk. Dále přidej opakování či malý odpor při stejné dráze a klidném trupu. Zapiš kg podle stupnice a své dosavadní konvence. Poznamenej konkrétní stroj, nastavení výšky a zda údaj znamená jednu věž nebo součet; staré zápisy nepřepočítávej. Převod kladky může měnit odpor v ruce.","Easier: lighter resistance and a smaller arc. Add repetitions or a small resistance increase while keeping the path and torso steady. Log kilograms using the scale and your established convention. Note the machine, pulley height and whether the figure represents one stack or the total; do not recalculate past entries. The pulley ratio can change the resistance at the hand."]}}},"ex26_cable_incline_fly":{"id":"ex26_cable_incline_fly","segment":"G","edits":{"eq":["adjustable_cable_pair","cable_handle_pair"],"pos":["Samostatná madla nízkých kladek drž vedle boků; obě kladky jsou pod úrovní rukou v konečné poloze. Stůj pevně s jednou nohou vpředu a trupem přibližně vzpřímeně. Lokty mírně pokrč a udržuj zápěstí v návaznosti na předloktí.","Hold separate low-pulley handles beside the hips, with both pulleys below the hands at the finish. Use a stable split stance and a roughly upright torso. Keep a slight elbow bend and the wrists aligned with the forearms."],"exe":["Veď obě ruce obloukem vpřed a vzhůru před horní část hrudníku, případně k obličeji, pokud je tato výška pohodlná. Potom je vrať stejnou cestou. Lokty nezamykáš ani jimi opakovaně netlačíš. Zdvih a návrat obou paží je jedno opakování; vzpažení nad hlavu není podmínkou.","Sweep both hands forward and upward toward the upper chest, or face height if comfortable, then return along the same path. Avoid locking the elbows or repeatedly pressing through them. One raise and return of both arms is one repetition; reaching overhead is not required."],"pro":["Lehčí: nižší konec pohybu nebo menší odpor. Dále přidej opakování či malý odpor při stále ovládané dráze. Zapiš kg podle stupnice a své dosavadní konvence. Poznamenej konkrétní stroj, nastavení výšky a zda údaj znamená jednu věž nebo součet; staré zápisy nepřepočítávej. Převod kladky může měnit odpor v ruce.","Easier: a lower finish or less resistance. Add repetitions or a small resistance increase while keeping control of the path. Log kilograms using the scale and your established convention. Note the machine, pulley height and whether the figure represents one stack or the total; do not recalculate past entries. The pulley ratio can change the resistance at the hand."],"equipmentDetail":["Dvě kladky po stranách těla A pár samostatných madel; výšku musí jít nastavit pro zvolenou dráhu. Před cvičením zkontroluj zajištění madel a nech kolem sebe volný prostor. Jedna kladka se dvěma konci lana není stejná sestava.","Two pulleys on either side of the body AND a pair of separate handles, adjustable to the chosen path. Check the handle attachments and leave clear space around you. One pulley with two rope ends is not the same setup."]},"taxonomy":{"regions":["chest"],"secondaryRegions":["shoulders"],"movements":["joint"],"focus":["strength"],"priority":1,"positions":["standing"],"supports":[],"equipmentRequirements":[["adjustable_cable_pair"],["cable_handle_pair"]],"aliases":[]},"policy":{"id":"ex26_cable_incline_fly","measurementType":"WEIGHT_REPS","loadMode":"ext","sideMode":"none","requirements":[["adjustable_cable_pair"],["cable_handle_pair"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":false,"allowEstimatedMax":false,"allowComparableRecords":false},"art":{"appId":"ex26_cable_incline_fly","atlasId":"ex26_cable_incline_fly","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"8a9578410ae02079a37d5de14409d08700401a892d3f01d75b3d4e520a23520c","thumb":"/expansion-atlas/ex26_cable_incline_fly-original-256.webp","detail":"/expansion-atlas/ex26_cable_incline_fly-original-960.webp","inkThumb":"/expansion-atlas/ex26_cable_incline_fly-ink-256.webp","inkDetail":"/expansion-atlas/ex26_cable_incline_fly-ink-960.webp","fillThumb":"/expansion-atlas/ex26_cable_incline_fly-fill-256.webp","fillDetail":"/expansion-atlas/ex26_cable_incline_fly-fill-960.webp"},"sourceSha256":"8a9578410ae02079a37d5de14409d08700401a892d3f01d75b3d4e520a23520c","contourOnly":true,"darkOutline":true},"libraryOrder":7005,"deliveryProfiles":{"00864e5a6ce4e8ea":{"fields":{"id":"ex26_cable_incline_fly","cz":"Rozpažování na kladkách zdola nahoru","en":"Low-to-High Cable Fly","pat":"tlak","eq":["adjustable_cable_pair","cable_handle_pair"],"measurementType":"WEIGHT_REPS","defaultRestSec":60,"unilateral":false,"sideMode":"none","focus":["Veď téměř natažené paže obloukem vpřed a vzhůru k úrovni horní části hrudníku až obličeje.","Sweep softly extended arms forward and upward toward upper-chest to face height, then return smoothly."],"startPosition":["Samostatná madla nízkých kladek drž vedle boků; obě kladky jsou pod úrovní rukou v konečné poloze. Stůj pevně s jednou nohou vpředu a trupem přibližně vzpřímeně. Lokty mírně pokrč a udržuj zápěstí v návaznosti na předloktí.","Hold separate low-pulley handles beside the hips, with both pulleys below the hands at the finish. Use a stable split stance and a roughly upright torso. Keep a slight elbow bend and the wrists aligned with the forearms."],"execution":["Veď obě ruce obloukem vpřed a vzhůru před horní část hrudníku, případně k obličeji, pokud je tato výška pohodlná. Potom je vrať stejnou cestou. Lokty nezamykáš ani jimi opakovaně netlačíš. Zdvih a návrat obou paží je jedno opakování; vzpažení nad hlavu není podmínkou.","Sweep both hands forward and upward toward the upper chest, or face height if comfortable, then return along the same path. Avoid locking the elbows or repeatedly pressing through them. One raise and return of both arms is one repetition; reaching overhead is not required."],"watchFor":["Konečnou výšku určuje pohodlí ramen. Nevytlačuj žebra vpřed.","Let shoulder comfort determine finish height. Avoid flaring the ribs."]},"progression":["Lehčí: nižší konec pohybu nebo menší odpor. Dále přidej opakování či malý odpor při stále ovládané dráze. Zapiš kg podle stupnice a své dosavadní konvence. Poznamenej konkrétní stroj, nastavení výšky a zda údaj znamená jednu věž nebo součet; staré zápisy nepřepočítávej. Převod kladky může měnit odpor v ruce.","Easier: a lower finish or less resistance. Add repetitions or a small resistance increase while keeping control of the path. Log kilograms using the scale and your established convention. Note the machine, pulley height and whether the figure represents one stack or the total; do not recalculate past entries. The pulley ratio can change the resistance at the hand."]}}},"ex26_around_world":{"id":"ex26_around_world","segment":"G","edits":{"eq":["dumbbell_pair","flat_bench"],"ez":null,"exe":["Obě paže veď od boků širokým obloukem do stran a směrem nad hlavu jen v pohodlném rozsahu. Lokty zůstávají mírně pokrčené. Stejnou cestou vrať činky k bokům; tento celý oblouk tam a zpět je jedno opakování obou paží. Nemusíš dosáhnout za hlavu ani spojovat činky.","Sweep both arms from the hips in a wide arc out to the sides and toward overhead, only within a comfortable range. Keep the elbows slightly bent. Return along the same path to the hips; this complete out-and-back arc is one repetition with both arms. You do not have to reach behind the head or touch the dumbbells together."],"pro":["Lehčí: oblouk bez činek nebo kratší dráha. Zachovej stejný rozsah a ovladatelnost; zátěž zvyšuj jen po malých krocích, pokud to odpovídá cíli. Rozpažování před hrudníkem je jiný úkol. U páru činek dodrž dosavadní konvenci zápisu kg a poznamenej, zda uvádíš jednu činku nebo součet. Staré záznamy neděl ani nenásob.","Easier: unloaded arcs or a shorter path. Keep the chosen range controlled; increase load only in small steps when it serves the goal. Bringing the arms together above the chest is a different task. For a dumbbell pair, retain your established kilogram convention and note whether you record one dumbbell or the total. Do not divide or multiply old entries."],"equipmentDetail":["Pár velmi lehkých jednoruček A pevná rovná lavice s oporou hlavy, zad a pánve; chodidla opřená. Kolem celé dráhy paží musí být volno. Přípravu činek nad hrudníkem a přesun k bokům proveď s pokrčenými lokty pod kontrolou; po sérii je odlož bezpečně stejným způsobem.","A pair of very light dumbbells AND a stable flat bench supporting the head, back and pelvis, with the feet supported. Leave room for the entire arm path. Set up the dumbbells above the chest and move them to the hips under control with bent elbows; reverse this controlled setup when putting them down."]},"taxonomy":{"regions":["chest","shoulders"],"secondaryRegions":[],"movements":["joint"],"focus":["strength"],"priority":2,"positions":["supine"],"supports":["chair_bench"],"equipmentRequirements":[["dumbbell_pair"],["flat_bench"]],"aliases":[]},"policy":{"id":"ex26_around_world","measurementType":"WEIGHT_REPS","loadMode":"ext","sideMode":"none","requirements":[["dumbbell_pair"],["flat_bench"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":false,"allowEstimatedMax":false,"allowComparableRecords":false},"art":{"appId":"ex26_around_world","atlasId":"ex26_around_world","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"2ad2b7ffc326d7771ec9655828de8deb7a4d4a5252afdd1958c58b8b5ead8878","thumb":"/expansion-atlas/ex26_around_world-original-256.webp","detail":"/expansion-atlas/ex26_around_world-original-960.webp","inkThumb":"/expansion-atlas/ex26_around_world-ink-256.webp","inkDetail":"/expansion-atlas/ex26_around_world-ink-960.webp","fillThumb":"/expansion-atlas/ex26_around_world-fill-256.webp","fillDetail":"/expansion-atlas/ex26_around_world-fill-960.webp"},"sourceSha256":"2ad2b7ffc326d7771ec9655828de8deb7a4d4a5252afdd1958c58b8b5ead8878","contourOnly":true,"darkOutline":true},"libraryOrder":7006,"deliveryProfiles":{"b38c72aa89fedcef":{"fields":{"id":"ex26_around_world","cz":"Oblouky s jednoručkami vleže","en":"Dumbbell Around the World","pat":"tlak","eq":["dumbbell_pair","flat_bench"],"measurementType":"WEIGHT_REPS","defaultRestSec":120,"unilateral":false,"sideMode":"none","focus":["Veď paže širokým obloukem do stran a směrem nad hlavu pouze v pohodlném rozsahu.","Sweep the arms in a wide arc sideways and toward overhead only within a comfortable range."],"startPosition":["Lehni si na rovnou lavici a drž velmi lehké činky u boků, dlaně vzhůru. Lokty jsou mírně pokrčené.","Lie on a flat bench with very light dumbbells beside the hips, palms upward and elbows slightly bent."],"execution":["Obě paže veď od boků širokým obloukem do stran a směrem nad hlavu jen v pohodlném rozsahu. Lokty zůstávají mírně pokrčené. Stejnou cestou vrať činky k bokům; tento celý oblouk tam a zpět je jedno opakování obou paží. Nemusíš dosáhnout za hlavu ani spojovat činky.","Sweep both arms from the hips in a wide arc out to the sides and toward overhead, only within a comfortable range. Keep the elbows slightly bent. Return along the same path to the hips; this complete out-and-back arc is one repetition with both arms. You do not have to reach behind the head or touch the dumbbells together."],"watchFor":["Nepropadej pažemi pod úroveň trupu ani nezvedej žebra. Cvik vyžaduje volný pohyb ramen; není nutný pro základní trénink prsou.","Do not drop arms below torso level or flare the ribs. This requires comfortable shoulder motion and is optional for basic chest training."]},"progression":["Lehčí: oblouk bez činek nebo kratší dráha. Zachovej stejný rozsah a ovladatelnost; zátěž zvyšuj jen po malých krocích, pokud to odpovídá cíli. Rozpažování před hrudníkem je jiný úkol. U páru činek dodrž dosavadní konvenci zápisu kg a poznamenej, zda uvádíš jednu činku nebo součet. Staré záznamy neděl ani nenásob.","Easier: unloaded arcs or a shorter path. Keep the chosen range controlled; increase load only in small steps when it serves the goal. Bringing the arms together above the chest is a different task. For a dumbbell pair, retain your established kilogram convention and note whether you record one dumbbell or the total. Do not divide or multiply old entries."]}}},"ex26_kb_halo":{"id":"ex26_kb_halo","segment":"H","edits":{"eq":["kettlebell"],"pos":["Postav se pohodlně a lehký kettlebell uchop oběma rukama za boční části madla před hrudníkem. Zápěstí drž přibližně v prodloužení předloktí a zvol pevný úchop, ve kterém činku bezpečně ovládáš.","Stand comfortably and hold a light kettlebell by the sides of its handle in front of the chest with both hands. Keep the wrists roughly aligned with the forearms and use a secure grip that lets you control the bell."],"exe":["Pomalu veď kettlebell kolem jedné strany hlavy, za ní a druhou stranou zpět před hrudník. Obě ruce jej drží po celou dobu; hlava se neuhýbá čince. Jeden celý okruh je jedno opakování. Proveď oba směry a u nových sérií je rozliš podle prvního pohybu činky ze středu na svou levou nebo pravou stranu.","Slowly guide the kettlebell around one side of the head, behind it and around the other side back to the chest. Keep both hands on it throughout; do not move the head out of its way. One complete circle is one repetition. Work both directions; for new sets distinguish them by the first movement from the centre toward your own left or right side."],"wat":["Činku veď s rezervou kolem hlavy a jen v pohodlné výšce. Netlač ji co nejníž za krk, neprohýbej bedra a neotáčej celý trup, abys získal prostor. Pokud se dráha rozpadá nebo rameno bolí, zmenši rozsah či odlož zátěž.","Keep clearance around the head and choose a comfortable height. Do not force the bell low behind the neck, arch the lower back or turn the whole torso to create space. Reduce the range or put down the load if the path becomes uncontrolled or the shoulder hurts."],"pro":["Lehčí: nejprve nacvič dráhu bez zátěže nebo použij lehčí kettlebell. Dále můžeš pohyb zpomalit a krátce zastavit v ovládaném místě. Zapisuj kg jednoho kettlebellu; těžší zátěž ani více kruhů nejsou povinný postup. Směr není pracovní ruka a staré L/R štítky zpětně nepřeznačuj.","Easier: rehearse the path without a load or use a lighter kettlebell. You may then slow the movement or pause briefly at a controlled point. Record the mass of the single kettlebell; heavier loading or more circles is not a compulsory progression. Direction is not a working hand; do not relabel earlier L/R records retrospectively."],"foc":["Činka obíhá klidnou hlavu; obě ruce pracují společně.","The bell moves around a steady head; both hands work together."],"equipmentDetail":["Jeden lehký kettlebell s madlem, které lze bezpečně držet oběma rukama, a volný prostor kolem hlavy. Kotouč nebo jednoručka mají jiný úchop; nejsou automatická náhrada tohoto vybavení.","One light kettlebell with a handle that can be securely held by both hands, plus clearance around the head. A plate or dumbbell uses a different grip and does not automatically satisfy this setup."]},"taxonomy":{"movements":["joint","trunk_stability"],"focus":["mobility","coordination"],"positions":["standing"],"supports":[],"equipmentRequirements":[["kettlebell"]],"priority":1},"policy":{"id":"ex26_kb_halo","measurementType":"WEIGHT_REPS","loadMode":"ext","sideMode":"perSide","requirements":[["kettlebell"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":false,"sideMeaning":["Směr začátku kruhu (obě ruce)","Circle start direction (both hands)"],"allowEstimatedMax":false,"allowComparableRecords":false},"art":{"appId":"ex26_kb_halo","atlasId":"ex26_kb_halo","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"db3d2c2053183b246c0611ed14e9aaa9932c3bef58bd6821e654266408e3cd9b","thumb":"/expansion-atlas/ex26_kb_halo-original-256.webp","detail":"/expansion-atlas/ex26_kb_halo-original-960.webp","inkThumb":"/expansion-atlas/ex26_kb_halo-ink-256.webp","inkDetail":"/expansion-atlas/ex26_kb_halo-ink-960.webp","fillThumb":"/expansion-atlas/ex26_kb_halo-fill-256.webp","fillDetail":"/expansion-atlas/ex26_kb_halo-fill-960.webp"},"sourceSha256":"db3d2c2053183b246c0611ed14e9aaa9932c3bef58bd6821e654266408e3cd9b","contourOnly":true,"darkOutline":true},"libraryOrder":8000,"deliveryProfiles":{"4b5f3906cf55e557":{"fields":{"id":"ex26_kb_halo","cz":"Kroužení kettlebellem kolem hlavy","en":"Kettlebell Halo","pat":"mobilita","eq":["kettlebell"],"measurementType":"WEIGHT_REPS","defaultRestSec":15,"unilateral":true,"sideMode":"perSide","focus":["Činka obíhá klidnou hlavu; obě ruce pracují společně.","The bell moves around a steady head; both hands work together."],"startPosition":["Postav se pohodlně a lehký kettlebell uchop oběma rukama za boční části madla před hrudníkem. Zápěstí drž přibližně v prodloužení předloktí a zvol pevný úchop, ve kterém činku bezpečně ovládáš.","Stand comfortably and hold a light kettlebell by the sides of its handle in front of the chest with both hands. Keep the wrists roughly aligned with the forearms and use a secure grip that lets you control the bell."],"execution":["Pomalu veď kettlebell kolem jedné strany hlavy, za ní a druhou stranou zpět před hrudník. Obě ruce jej drží po celou dobu; hlava se neuhýbá čince. Jeden celý okruh je jedno opakování. Proveď oba směry a u nových sérií je rozliš podle prvního pohybu činky ze středu na svou levou nebo pravou stranu.","Slowly guide the kettlebell around one side of the head, behind it and around the other side back to the chest. Keep both hands on it throughout; do not move the head out of its way. One complete circle is one repetition. Work both directions; for new sets distinguish them by the first movement from the centre toward your own left or right side."],"watchFor":["Činku veď s rezervou kolem hlavy a jen v pohodlné výšce. Netlač ji co nejníž za krk, neprohýbej bedra a neotáčej celý trup, abys získal prostor. Pokud se dráha rozpadá nebo rameno bolí, zmenši rozsah či odlož zátěž.","Keep clearance around the head and choose a comfortable height. Do not force the bell low behind the neck, arch the lower back or turn the whole torso to create space. Reduce the range or put down the load if the path becomes uncontrolled or the shoulder hurts."]},"progression":["Lehčí: nejprve nacvič dráhu bez zátěže nebo použij lehčí kettlebell. Dále můžeš pohyb zpomalit a krátce zastavit v ovládaném místě. Zapisuj kg jednoho kettlebellu; těžší zátěž ani více kruhů nejsou povinný postup. Směr není pracovní ruka a staré L/R štítky zpětně nepřeznačuj.","Easier: rehearse the path without a load or use a lighter kettlebell. You may then slow the movement or pause briefly at a controlled point. Record the mass of the single kettlebell; heavier loading or more circles is not a compulsory progression. Direction is not a working hand; do not relabel earlier L/R records retrospectively."]}}},"ex26_side_armroll":{"id":"ex26_side_armroll","segment":"H","edits":{"eq":["dumbbell","towel","support_cushion"],"pos":["Lehni si na záda s oběma koleny pokrčenými a chodidly opřenými. Hlavu nízce podlož složeným ručníkem nebo pevným malým polštářem. Jednu velmi lehkou jednoručku nastav s pomocí druhé ruky nad rameno; zápěstí drž rovně. Volnou paži polož vedle těla.","Lie on your back with both knees bent and feet supported. Place a low folded towel or small firm cushion under the head. Help a very light dumbbell into position above one shoulder with the other hand; keep the wrist aligned. Rest the free arm beside the body."],"exe":["Pomalu přetoč trup i pokrčené nohy k volné paži, tedy na opačný bok než je činka. Zatížená paže zůstává svislá a loket natažený bez násilného propnutí. Zastav v ovládaném rozsahu a vrať se na záda. Přetočení a návrat je jedno opakování pro paži s činkou; potom bezpečně vystřídej strany.","Slowly roll the trunk and bent legs toward the free arm, onto the side opposite the dumbbell. Keep the loaded arm vertical with the elbow straight without forcing lockout. Stop within a controlled range and return to your back. One roll and return is one repetition for the loaded arm; then change sides safely."],"wat":["Hlava zůstává nízko na opoře, nezvedej trup přitlačením do volného lokte. Činka se nepřeklápí za tělo ani k obličeji. Pohyb zkrať dřív, než se rameno či zápěstí začnou viklat; nejde o pasivní protažení pod těžkou zátěží.","Keep the head low on its support rather than lifting the trunk by pressing into the free elbow. Do not let the dumbbell tip behind the body or toward the face. Shorten the roll before the shoulder or wrist becomes unsteady; this is not a passive stretch under a heavy load."],"pro":["Lehčí: prázdná ruka a částečné přetočení při stejné opoře hlavy. Dále můžeš zpomalit návrat s lehkou činkou. Před odložením se vrať do stabilního lehu a činku převezmi oběma rukama. Zapisuj kg jedné jednoručky a provedení bez zátěže odliš poznámkou; nepřecházej automaticky na kettlebell ani vstávání.","Easier: use an empty hand and a partial roll with the same head support. You may then slow the return with a light dumbbell. Return to stable lying and take the dumbbell with both hands before putting it down. Record the mass of one dumbbell and note unloaded practice; do not automatically progress to a kettlebell or a get-up."],"foc":["Trup se přetáčí nízko, činka zůstává nad ramenem.","The trunk rolls close to the floor while the dumbbell stays above the shoulder."],"equipmentDetail":["Jedna velmi lehká jednoručka A nízká opora hlavy: složený ručník NEBO pevný malý polštář. Pevná neklouzavá podlaha s místem pro obě pokrčené nohy. Vysoká nebo klouzající opora hlavy není vhodná.","One very light dumbbell AND low head support: a folded towel OR a small firm cushion. Use a firm non-slip floor with room for both bent legs. Avoid high or slippery head support."]},"taxonomy":{"movements":["trunk_movement","joint"],"focus":["mobility","coordination"],"positions":["supine","side_lying"],"supports":["head_support"],"equipmentRequirements":[["dumbbell"],["towel","support_cushion"]],"priority":2},"policy":{"id":"ex26_side_armroll","measurementType":"WEIGHT_REPS","loadMode":"ext","sideMode":"perSide","requirements":[["dumbbell"],["towel","support_cushion"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":false,"sideMeaning":["Paže se zátěží","Loaded arm"],"requiresEquipmentCheck":true,"allowEstimatedMax":false,"allowComparableRecords":false},"art":{"appId":"ex26_side_armroll","atlasId":"ex26_side_armroll","unified":true,"contourOnly":true,"darkOutline":true,"sourceSha256":"378e8e4354dadcbc6b493b9bd0a38d2933727d1b60a5012c93732ea51ade576d","primary":{"width":960,"height":960,"thumb":"/movement-audit/ex26_side_armroll-378e8e4354da-256.webp","inkThumb":"/movement-audit/ex26_side_armroll-378e8e4354da-256.webp","detail":"/movement-audit/ex26_side_armroll-378e8e4354da-960.webp","inkDetail":"/movement-audit/ex26_side_armroll-378e8e4354da-960.webp","sourceSha256":"378e8e4354dadcbc6b493b9bd0a38d2933727d1b60a5012c93732ea51ade576d"}},"libraryOrder":8001,"deliveryProfiles":{"94aef70b5656a76d":{"fields":{"id":"ex26_side_armroll","cz":"Přetočení na bok s činkou nad ramenem","en":"Side Roll with Vertical Dumbbell","pat":"mobilita","eq":["dumbbell","towel","support_cushion"],"measurementType":"WEIGHT_REPS","defaultRestSec":90,"unilateral":true,"sideMode":"perSide","focus":["Trup se přetáčí nízko, činka zůstává nad ramenem.","The trunk rolls close to the floor while the dumbbell stays above the shoulder."],"startPosition":["Lehni si na záda s oběma koleny pokrčenými a chodidly opřenými. Hlavu nízce podlož složeným ručníkem nebo pevným malým polštářem. Jednu velmi lehkou jednoručku nastav s pomocí druhé ruky nad rameno; zápěstí drž rovně. Volnou paži polož vedle těla.","Lie on your back with both knees bent and feet supported. Place a low folded towel or small firm cushion under the head. Help a very light dumbbell into position above one shoulder with the other hand; keep the wrist aligned. Rest the free arm beside the body."],"execution":["Pomalu přetoč trup i pokrčené nohy k volné paži, tedy na opačný bok než je činka. Zatížená paže zůstává svislá a loket natažený bez násilného propnutí. Zastav v ovládaném rozsahu a vrať se na záda. Přetočení a návrat je jedno opakování pro paži s činkou; potom bezpečně vystřídej strany.","Slowly roll the trunk and bent legs toward the free arm, onto the side opposite the dumbbell. Keep the loaded arm vertical with the elbow straight without forcing lockout. Stop within a controlled range and return to your back. One roll and return is one repetition for the loaded arm; then change sides safely."],"watchFor":["Hlava zůstává nízko na opoře, nezvedej trup přitlačením do volného lokte. Činka se nepřeklápí za tělo ani k obličeji. Pohyb zkrať dřív, než se rameno či zápěstí začnou viklat; nejde o pasivní protažení pod těžkou zátěží.","Keep the head low on its support rather than lifting the trunk by pressing into the free elbow. Do not let the dumbbell tip behind the body or toward the face. Shorten the roll before the shoulder or wrist becomes unsteady; this is not a passive stretch under a heavy load."]},"progression":["Lehčí: prázdná ruka a částečné přetočení při stejné opoře hlavy. Dále můžeš zpomalit návrat s lehkou činkou. Před odložením se vrať do stabilního lehu a činku převezmi oběma rukama. Zapisuj kg jedné jednoručky a provedení bez zátěže odliš poznámkou; nepřecházej automaticky na kettlebell ani vstávání.","Easier: use an empty hand and a partial roll with the same head support. You may then slow the return with a light dumbbell. Return to stable lying and take the dumbbell with both hands before putting it down. Record the mass of one dumbbell and note unloaded practice; do not automatically progress to a kettlebell or a get-up."]}}},"kb26_armbar":{"id":"kb26_armbar","segment":"H","edits":{"eq":["kettlebell"],"pos":["Na boku uchop velmi lehký kettlebell oběma rukama a přetoč se na záda. S pomocí druhé ruky jej nastav nad pracovní rameno. Koleno na straně činky pokrč a opři chodidlo; druhá noha zůstává dlouhá a volná paže leží na zemi nad hlavou.","On your side, take a very light kettlebell with both hands and roll onto your back. Use the other hand to help position it above the working shoulder. Bend the bell-side knee and plant that foot; keep the other leg long and the free arm on the floor overhead."],"exe":["Zatlač chodidlem na straně činky a přetoč se na opačný bok. Horní pokrčené koleno opři před trupem, dolní nohu nech dlouhou. Kettlebell drž svisle nad ramenem a hlavu nízko u spodní paže. Klidně dýchej ve stabilní poloze; zapisuj sekundy samotné výdrže pro paži s činkou, bez nástupu a návratu.","Push through the bell-side foot and roll onto the opposite side. Rest the upper bent knee in front of the trunk and keep the lower leg long. Hold the kettlebell vertically above the shoulder, keeping the head low by the lower arm. Breathe steadily in this stable position; record seconds of the hold itself for the loaded arm, excluding entry and return."],"wat":["Paži drž stabilně, loket natažený bez násilného propnutí a zápěstí v prodloužení předloktí. Neotáčej se násilím na břicho ani nepřidávej vstávání na loket. Nástup nejprve nacvič bez činky pod dohledem; při ztrátě kontroly potřebuješ domluvenou dopomoc, ne zachytávání padající činky u obličeje.","Keep the arm steady, the elbow straight without forcing lockout and the wrist aligned with the forearm. Do not force a roll onto the stomach or add a rise onto the elbow. Rehearse the setup unloaded with supervision first; if control is lost, use agreed assistance rather than trying to catch a falling bell near the face."],"pro":["Lehčí: stejná poloha bez zátěže a kratší výdrž. Z boku se vrať pomalu na záda, činku převezmi oběma rukama a bezpečně odlož přes bok; pak vystřídej stranu. Dále pracuj na klidném držení a dechu, nikoli automaticky na delším čase či větší váze. Zapisuj kg jednoho kettlebellu.","Easier: use the same position without a load and a shorter hold. Roll slowly back onto your back, take the bell with both hands and put it down safely through side lying; then change sides. Develop steadiness and breathing rather than automatically increasing time or weight. Record the mass of the single kettlebell."],"foc":["Horní koleno drží oporu před tělem, kettlebell zůstává svisle nad ramenem.","The upper knee supports you in front of the body while the kettlebell stays vertical above the shoulder."],"equipmentDetail":["Jeden velmi lehký kettlebell a pevná neklouzavá plocha s místem na přetočení. Při prvním nácviku se zátěží přítomná osoba schopná bezpečně převzít kettlebell. Volná paže leží nad hlavou; není to opora na lokti jako při get-upu.","One very light kettlebell and a firm non-slip surface with room to roll. During initial loaded practice, have someone present who can safely take the bell. The free arm lies overhead; this is not elbow support as in a get-up."]},"taxonomy":{"movements":["position","trunk_stability"],"focus":["mobility","coordination"],"positions":["side_lying"],"supports":[],"equipmentRequirements":[["kettlebell"]],"priority":2},"policy":{"id":"kb26_armbar","measurementType":"WEIGHT_DURATION","loadMode":"ext","sideMode":"perSide","requirements":[["kettlebell"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":false,"sideMeaning":["Paže se zátěží","Loaded arm"],"requiresCoach":true,"allowEstimatedMax":false,"allowComparableRecords":false},"art":{"appId":"kb26_armbar","atlasId":"kb26_armbar","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"dd9357d36f11856973f0f3caf237ace586eea28af84d4b2949ba4a562d2578e6","thumb":"/expansion-atlas/kb26_armbar-original-256.webp","detail":"/expansion-atlas/kb26_armbar-original-960.webp","inkThumb":"/expansion-atlas/kb26_armbar-ink-256.webp","inkDetail":"/expansion-atlas/kb26_armbar-ink-960.webp","fillThumb":"/expansion-atlas/kb26_armbar-fill-256.webp","fillDetail":"/expansion-atlas/kb26_armbar-fill-960.webp"},"sourceSha256":"dd9357d36f11856973f0f3caf237ace586eea28af84d4b2949ba4a562d2578e6","contourOnly":true,"darkOutline":true},"libraryOrder":8002,"deliveryProfiles":{"49554a4f3e56b763":{"fields":{"id":"kb26_armbar","cz":"Přetočení do opory ramene s kettlebellem","en":"Kettlebell Arm Bar","pat":"mobilita","eq":["kettlebell"],"measurementType":"WEIGHT_DURATION","defaultRestSec":30,"unilateral":true,"sideMode":"perSide","focus":["Horní koleno drží oporu před tělem, kettlebell zůstává svisle nad ramenem.","The upper knee supports you in front of the body while the kettlebell stays vertical above the shoulder."],"startPosition":["Na boku uchop velmi lehký kettlebell oběma rukama a přetoč se na záda. S pomocí druhé ruky jej nastav nad pracovní rameno. Koleno na straně činky pokrč a opři chodidlo; druhá noha zůstává dlouhá a volná paže leží na zemi nad hlavou.","On your side, take a very light kettlebell with both hands and roll onto your back. Use the other hand to help position it above the working shoulder. Bend the bell-side knee and plant that foot; keep the other leg long and the free arm on the floor overhead."],"execution":["Zatlač chodidlem na straně činky a přetoč se na opačný bok. Horní pokrčené koleno opři před trupem, dolní nohu nech dlouhou. Kettlebell drž svisle nad ramenem a hlavu nízko u spodní paže. Klidně dýchej ve stabilní poloze; zapisuj sekundy samotné výdrže pro paži s činkou, bez nástupu a návratu.","Push through the bell-side foot and roll onto the opposite side. Rest the upper bent knee in front of the trunk and keep the lower leg long. Hold the kettlebell vertically above the shoulder, keeping the head low by the lower arm. Breathe steadily in this stable position; record seconds of the hold itself for the loaded arm, excluding entry and return."],"watchFor":["Paži drž stabilně, loket natažený bez násilného propnutí a zápěstí v prodloužení předloktí. Neotáčej se násilím na břicho ani nepřidávej vstávání na loket. Nástup nejprve nacvič bez činky pod dohledem; při ztrátě kontroly potřebuješ domluvenou dopomoc, ne zachytávání padající činky u obličeje.","Keep the arm steady, the elbow straight without forcing lockout and the wrist aligned with the forearm. Do not force a roll onto the stomach or add a rise onto the elbow. Rehearse the setup unloaded with supervision first; if control is lost, use agreed assistance rather than trying to catch a falling bell near the face."]},"progression":["Lehčí: stejná poloha bez zátěže a kratší výdrž. Z boku se vrať pomalu na záda, činku převezmi oběma rukama a bezpečně odlož přes bok; pak vystřídej stranu. Dále pracuj na klidném držení a dechu, nikoli automaticky na delším čase či větší váze. Zapisuj kg jednoho kettlebellu.","Easier: use the same position without a load and a shorter hold. Roll slowly back onto your back, take the bell with both hands and put it down safely through side lying; then change sides. Develop steadiness and breathing rather than automatically increasing time or weight. Record the mass of the single kettlebell."]}}},"neckiso":{"id":"neckiso","segment":"I","edits":{"cz":"Izometrie krku proti dlani","en":"Manual Neck Isometrics","hd":null,"pos":["Sedni si na pevné sedadlo s chodidly na podlaze. Hlava je v pohodlném napřímení, čelist a ramena uvolněné. Dlaň polož podle zvoleného směru na čelo, bok hlavy nad uchem nebo zátylek.","Sit on a stable seat with feet on the floor. Keep the head comfortably upright and the jaw and shoulders relaxed. Place the palm on the forehead, side of the head above the ear, or back of the head for the chosen direction."],"exe":["Postupně vytvoř lehký tlak hlavy proti dlani a stejný protitlak ruky, aby hlava zůstala na místě. Volně dýchej, potom tlak plynule uvolni. Zapisuj čas jedné výdrže a její směr; jednotlivé směry nesčítej do jedné výdrže.","Gradually press the head lightly into the palm and match it with the hand so the head stays still. Breathe freely, then release smoothly. Record the duration and direction of one hold; do not combine different directions into one hold."],"wat":["Pohyb ani tlak nevynucuj. Při závrati, brnění, vystřelující bolesti nebo nové bolesti hlavy přestaň; přetrvávající nebo opakované potíže řeš s odborníkem.","Do not force movement or pressure. Stop for dizziness, tingling, radiating pain or a new headache; seek professional advice for persistent or recurring symptoms."],"pro":["Sílu tlaku, délku výdrže a počet směrů přizpůsob zadání a tomu, co klidně zvládáš. Větší tlak ani delší čas nejsou automaticky lepší. Kroužení krkem je jiný úkol.","Adapt the effort, hold duration and directions to the task and what you can manage calmly. More pressure or time is not automatically better. Neck circles are a different task."],"foc":["Lehký ruční odpor, klidná hlava a volný dech.","Light manual resistance, a steady head and free breathing."],"equipmentDetail":["Pevná židle nebo rovná lavice pro sed. Odpor vytváří vlastní ruka, ne závaží; směr a přibližnou míru úsilí poznamenej.","A stable chair or flat bench for sitting. Your own hand provides resistance, without a weight; note the direction and approximate effort."],"source":{"author":"Veterans Health Library / StayWell Custom Communications","document":"Neck Exercises: Neck Isometrics","url":"https://www.veteranshealthlibrary.va.gov/rehab/physicaltherapy/Neck/3,89949","scope":"Primary publisher text read: seated manual forehead, side and back resistance. App does not copy the source fixed dose, assign universal effort percentages, or make treatment claims. Direction/time logging is app convention. Source illustrations not visually reviewed."}},"taxonomy":{"regions":["neck"],"secondaryRegions":[],"movements":["position","joint"],"focus":["strength"],"positions":["seated"],"supports":["chair_bench"],"priority":1,"equipmentRequirements":[["chair","flat_bench"]],"aliases":["neck isometric hold","izometrická výdrž krku"]},"policy":{"id":"neckiso","measurementType":"DURATION","loadMode":"none","sideMode":"none","requirements":[["chair","flat_bench"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false,"blockedMotionSources":[]},"art":{"appId":"neckiso","atlasId":"neckiso","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"904011154eb77a8bc4bf6df4ef2bbe3e2304691972834e7b608ced55fb335d28","thumb":"/unified-atlas/neckiso-859fae17a563b0e1-thumb.webp","detail":"/unified-atlas/neckiso-3ff58e9524468048-detail.webp","inkThumb":"/unified-atlas/neckiso-cdffdb3848dc18ad-inkThumb.webp","inkDetail":"/unified-atlas/neckiso-d02e7cc275e3e2a4-inkDetail.webp","fillThumb":"/unified-atlas/neckiso-c522fb0933619efb-fillThumb.webp","fillDetail":"/unified-atlas/neckiso-b1490da84e44bdc8-fillDetail.webp"},"sourceSha256":"904011154eb77a8bc4bf6df4ef2bbe3e2304691972834e7b608ced55fb335d28","contourOnly":true,"darkOutline":true},"libraryOrder":10004,"deliveryProfiles":{"1fd93ca3558570f1":{"fields":{"id":"neckiso","cz":"Izometrie krku proti dlani","en":"Manual Neck Isometrics","pat":"krk","eq":["telo"],"measurementType":"DURATION","defaultRestSec":60,"unilateral":false,"sideMode":"none","focus":["Lehký ruční odpor, klidná hlava a volný dech.","Light manual resistance, a steady head and free breathing."],"startPosition":["Sedni si na pevné sedadlo s chodidly na podlaze. Hlava je v pohodlném napřímení, čelist a ramena uvolněné. Dlaň polož podle zvoleného směru na čelo, bok hlavy nad uchem nebo zátylek.","Sit on a stable seat with feet on the floor. Keep the head comfortably upright and the jaw and shoulders relaxed. Place the palm on the forehead, side of the head above the ear, or back of the head for the chosen direction."],"execution":["Postupně vytvoř lehký tlak hlavy proti dlani a stejný protitlak ruky, aby hlava zůstala na místě. Volně dýchej, potom tlak plynule uvolni. Zapisuj čas jedné výdrže a její směr; jednotlivé směry nesčítej do jedné výdrže.","Gradually press the head lightly into the palm and match it with the hand so the head stays still. Breathe freely, then release smoothly. Record the duration and direction of one hold; do not combine different directions into one hold."],"watchFor":["Pohyb ani tlak nevynucuj. Při závrati, brnění, vystřelující bolesti nebo nové bolesti hlavy přestaň; přetrvávající nebo opakované potíže řeš s odborníkem.","Do not force movement or pressure. Stop for dizziness, tingling, radiating pain or a new headache; seek professional advice for persistent or recurring symptoms."]},"progression":["Sílu tlaku, délku výdrže a počet směrů přizpůsob zadání a tomu, co klidně zvládáš. Větší tlak ani delší čas nejsou automaticky lepší. Kroužení krkem je jiný úkol.","Adapt the effort, hold duration and directions to the task and what you can manage calmly. More pressure or time is not automatically better. Neck circles are a different task."]}}},"neckcars":{"id":"neckcars","segment":"I","edits":{"cz":"Pomalé kroužení krkem · CARs","en":"Controlled Neck Circles · CARs","ez":null,"pos":["Sedni si nebo stůj stabilně. Ramena nech uvolněná a trup klidný; nestahuj je silou dolů.","Sit or stand steadily. Keep the shoulders relaxed and the trunk quiet; do not force the shoulders downward."],"exe":["Pomalu spoj přikývnutí, otočení, úklon a mírný záklon do plynulého okruhu v pohodlném rozsahu. Nezvětšuj kruh tlakem ani švihem. Jeden celý okruh je jedno opakování; další můžeš vést opačně.","Slowly connect nodding, turning, side bending and gentle backward movement into a smooth circle within a comfortable range. Do not enlarge it by forcing or swinging. One complete circle is one repetition; the next may go the other way."],"wat":["Pohyb ani tlak nevynucuj. Při závrati, brnění, vystřelující bolesti nebo nové bolesti hlavy přestaň; přetrvávající nebo opakované potíže řeš s odborníkem.","Do not force movement or pressure. Stop for dizziness, tingling, radiating pain or a new headache; seek professional advice for persistent or recurring symptoms."],"pro":["Začni menším klidným rozsahem. Pokud celý okruh není pohodlný, zvol jen jednotlivý pohyb a poznamenej změnu; nepočítej jej jako celý kruh. Cílem není největší kruh ani pevně daná délka opakování.","Start with a smaller controlled range. If a complete circle is uncomfortable, choose a single movement and note the change rather than counting it as a full circle. The aim is neither the largest possible circle nor a fixed repetition duration."],"foc":["Plynulý vlastní rozsah krku bez nuceného krajního pohybu.","Smooth active neck movement without forcing an end range."],"equipmentDetail":["Ve stoji bez pomůcek; pro sed použij pevnou židli nebo lavici. Obrázek ukazuje sed.","No equipment while standing; use a stable chair or bench for sitting. The illustration shows sitting."],"source":{"author":"Dr Notley, Chiropractic & Athletic Therapy","document":"Neck Circles (CARs) for neck mobility","url":"https://drnotley.com/neck-circles-cars-for-neck-mobility/","scope":"Direct exercise author describes combined active cervical circles. App deliberately adapts away from largest-circle, maximal-end-range effort and 30–60 second dose; comfortable motion context also checked against NHS/CUH. This is not a verified FRC certification protocol, diagnostic self-test or treatment. No source video viewed."}},"taxonomy":{"regions":["neck"],"secondaryRegions":[],"movements":["joint"],"focus":["mobility","coordination"],"positions":["seated","standing"],"supports":[],"priority":2,"equipmentRequirements":[["telo"]],"aliases":["neck circles","cervical CARs","kroužení hlavou"]},"policy":{"id":"neckcars","measurementType":"REPS_ONLY","loadMode":"none","sideMode":"none","requirements":[["telo"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false,"blockedMotionSources":[]},"art":{"appId":"neckcars","atlasId":"neckcars","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"e84a1e90abaa68fdcdd3445a5e63eb20ef2eba21601c7f71a111cd7a2e4f4854","thumb":"/unified-atlas/neckcars-e0d930fbfc32cba5-thumb.webp","detail":"/unified-atlas/neckcars-a337162bd64f6853-detail.webp","inkThumb":"/unified-atlas/neckcars-fb0ea4069894123e-inkThumb.webp","inkDetail":"/unified-atlas/neckcars-5b19d0e03e0b4dc1-inkDetail.webp","fillThumb":"/unified-atlas/neckcars-12132aabcf58d764-fillThumb.webp","fillDetail":"/unified-atlas/neckcars-2ae204d487a1e2fe-fillDetail.webp"},"sourceSha256":"e84a1e90abaa68fdcdd3445a5e63eb20ef2eba21601c7f71a111cd7a2e4f4854","contourOnly":true,"darkOutline":true},"libraryOrder":10005,"deliveryProfiles":{"6d50e625ee1c143e":{"fields":{"id":"neckcars","cz":"Pomalé kroužení krkem · CARs","en":"Controlled Neck Circles · CARs","pat":"krk","eq":["telo"],"measurementType":"REPS_ONLY","defaultRestSec":20,"unilateral":false,"sideMode":"none","focus":["Plynulý vlastní rozsah krku bez nuceného krajního pohybu.","Smooth active neck movement without forcing an end range."],"startPosition":["Sedni si nebo stůj stabilně. Ramena nech uvolněná a trup klidný; nestahuj je silou dolů.","Sit or stand steadily. Keep the shoulders relaxed and the trunk quiet; do not force the shoulders downward."],"execution":["Pomalu spoj přikývnutí, otočení, úklon a mírný záklon do plynulého okruhu v pohodlném rozsahu. Nezvětšuj kruh tlakem ani švihem. Jeden celý okruh je jedno opakování; další můžeš vést opačně.","Slowly connect nodding, turning, side bending and gentle backward movement into a smooth circle within a comfortable range. Do not enlarge it by forcing or swinging. One complete circle is one repetition; the next may go the other way."],"watchFor":["Pohyb ani tlak nevynucuj. Při závrati, brnění, vystřelující bolesti nebo nové bolesti hlavy přestaň; přetrvávající nebo opakované potíže řeš s odborníkem.","Do not force movement or pressure. Stop for dizziness, tingling, radiating pain or a new headache; seek professional advice for persistent or recurring symptoms."]},"progression":["Začni menším klidným rozsahem. Pokud celý okruh není pohodlný, zvol jen jednotlivý pohyb a poznamenej změnu; nepočítej jej jako celý kruh. Cílem není největší kruh ani pevně daná délka opakování.","Start with a smaller controlled range. If a complete circle is uncomfortable, choose a single movement and note the change rather than counting it as a full circle. The aim is neither the largest possible circle nor a fixed repetition duration."]}}},"ex26_chin_tuck":{"id":"ex26_chin_tuck","segment":"I","edits":{"pos":["Sedni si na pevnou židli nebo lavici, chodidla opři. Dívej se vodorovně a čelist nech uvolněnou.","Sit on a stable chair or bench with feet supported. Keep the gaze level and the jaw relaxed."],"exe":["Posuň bradu jemně dozadu, jako by se hlava zasouvala po vodorovné kolejnici. Krátce podrž a povol. Jeden pohyb a návrat je jedno opakování.","Slide the chin gently backward along a horizontal line, pause briefly and release. One movement and return is one repetition."],"pro":["Zmenši posun nebo využij opěradlo. Krátká pauza je volitelná; netlač hlavu rukou a nesnaž se vytvořit co největší dvojitou bradu.","Reduce the movement or use a backrest. A brief pause is optional; do not push the head with a hand or try to make the largest possible double chin."],"foc":["Jemný posun hlavy dozadu při vodorovném pohledu.","A gentle backward head glide while keeping the gaze level."],"equipmentDetail":["Pevná židle nebo rovná lavice pro sed, chodidla na podlaze.","A stable chair or flat bench for sitting, with feet on the floor."],"source":{"author":"Cambridge University Hospitals NHS Foundation Trust","document":"Neck exercises and advice — Chin retraction","url":"https://www.cuh.nhs.uk/patient-information/neck-exercises-and-advice/","scope":"Primary text read. Horizontal seated retraction differs from a small supported chin nod and from a head lift. No prescribed dose or posture-correction guarantee imported. Source illustration not viewed."}},"taxonomy":{"regions":["neck"],"secondaryRegions":[],"movements":["joint"],"focus":["coordination"],"positions":["seated"],"supports":["chair_bench"],"priority":1,"equipmentRequirements":[["chair","flat_bench"]],"aliases":["cervical retraction","retrakce hlavy"]},"policy":{"id":"ex26_chin_tuck","measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"none","requirements":[["chair","flat_bench"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false,"blockedMotionSources":[]},"art":{"appId":"ex26_chin_tuck","atlasId":"ex26_chin_tuck","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"d3b00a29a51be56953e21584ff285c20acb323750d9aec91648d04a0ff06b110","thumb":"/expansion-atlas/ex26_chin_tuck-original-256.webp","detail":"/expansion-atlas/ex26_chin_tuck-original-960.webp","inkThumb":"/expansion-atlas/ex26_chin_tuck-ink-256.webp","inkDetail":"/expansion-atlas/ex26_chin_tuck-ink-960.webp","fillThumb":"/expansion-atlas/ex26_chin_tuck-fill-256.webp","fillDetail":"/expansion-atlas/ex26_chin_tuck-fill-960.webp"},"sourceSha256":"d3b00a29a51be56953e21584ff285c20acb323750d9aec91648d04a0ff06b110","contourOnly":true,"darkOutline":true},"libraryOrder":10000,"deliveryProfiles":{"340eead987b662fe":{"fields":{"id":"ex26_chin_tuck","cz":"Zasunutí brady vsedě","en":"Seated Chin Retraction","pat":"krk","eq":["telo"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":90,"unilateral":false,"sideMode":"none","focus":["Jemný posun hlavy dozadu při vodorovném pohledu.","A gentle backward head glide while keeping the gaze level."],"startPosition":["Sedni si na pevnou židli nebo lavici, chodidla opři. Dívej se vodorovně a čelist nech uvolněnou.","Sit on a stable chair or bench with feet supported. Keep the gaze level and the jaw relaxed."],"execution":["Posuň bradu jemně dozadu, jako by se hlava zasouvala po vodorovné kolejnici. Krátce podrž a povol. Jeden pohyb a návrat je jedno opakování.","Slide the chin gently backward along a horizontal line, pause briefly and release. One movement and return is one repetition."],"watchFor":["Neskláněj bradu k hrudníku ani netlač silou. Při závrati pohyb přeruš.","Do not tip the chin toward the chest or force pressure. Stop if dizziness occurs."]},"progression":["Zmenši posun nebo využij opěradlo. Krátká pauza je volitelná; netlač hlavu rukou a nesnaž se vytvořit co největší dvojitou bradu.","Reduce the movement or use a backrest. A brief pause is optional; do not push the head with a hand or try to make the largest possible double chin."]}}},"ex26_mob_supine_chin_nod":{"id":"ex26_mob_supine_chin_nod","segment":"I","edits":{"exe":["Proveď drobné přikývnutí jako tiché ano. Zadní část hlavy zůstává opřená, potom povol. Jeden pohyb a návrat je jedno opakování.","Make a tiny nod as if quietly saying yes. Keep the back of the head supported, then relax. One movement and return is one repetition."],"pro":["Rozsah může být nepatrný, pauza není nutná. Opora pod hlavou slouží pohodlné poloze, nikoli k tlačení krku do určitého úhlu. Zvedání hlavy je samostatný náročnější úkol.","The movement may be tiny and needs no pause. Head support serves comfort rather than forcing a particular neck angle. Lifting the head is a separate, more demanding task."],"equipmentDetail":["Leh na pohodlné pevné podložce. Tenký složený ručník pod hlavu je volitelný podle polohy; zadní část hlavy zůstává opřená.","Lie on a comfortable firm surface. A thin folded towel under the head is optional as needed for positioning; the back of the head stays supported."],"source":{"author":"Gwendolen Jull, Michele Sterling / University of Queensland; TIMS NHS host","document":"Whiplash Injury Recovery 2019 — head nod, printed pp.24–25","url":"https://www.tims.nhs.uk/wp-content/uploads/2020/09/Whiplash-Injury-Recovery-booklet-2019.pdf","scope":"Original clinical booklet text read; supported nod with optional folded towel. App retains existing nonclinical coaching without importing pain-relief/deep-muscle-isolation claims or the clinical dose. PDF image fetch did not provide a viewable raster; figures not certified."}},"taxonomy":{"regions":["neck"],"secondaryRegions":[],"movements":["joint"],"focus":["mobility","coordination"],"positions":["supine"],"supports":["head_support"],"priority":1,"equipmentRequirements":[["telo"]],"aliases":["supported chin nod","přikývnutí s oporou hlavy"]},"policy":{"id":"ex26_mob_supine_chin_nod","measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"none","requirements":[["telo"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false,"blockedMotionSources":["/exercise-motion/ex26_mob_supine_chin_nod-453a63fe9b225837.mp4"]},"art":{"appId":"ex26_mob_supine_chin_nod","atlasId":"ex26_mob_supine_chin_nod","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"b4dc257f96af7928f5693b90a07ee17c10d9c7dfe2efed66931038cf04b6e537","thumb":"/expansion-atlas/ex26_mob_supine_chin_nod-original-256.webp","detail":"/expansion-atlas/ex26_mob_supine_chin_nod-original-960.webp","inkThumb":"/expansion-atlas/ex26_mob_supine_chin_nod-ink-256.webp","inkDetail":"/expansion-atlas/ex26_mob_supine_chin_nod-ink-960.webp","fillThumb":"/expansion-atlas/ex26_mob_supine_chin_nod-fill-256.webp","fillDetail":"/expansion-atlas/ex26_mob_supine_chin_nod-fill-960.webp"},"sourceSha256":"b4dc257f96af7928f5693b90a07ee17c10d9c7dfe2efed66931038cf04b6e537","contourOnly":true,"darkOutline":true},"libraryOrder":10001,"deliveryProfiles":{"71c0bf94143d1d47":{"fields":{"id":"ex26_mob_supine_chin_nod","cz":"Jemné přikývnutí vleže s opřenou hlavou","en":"Supine Chin Nod","pat":"mobilita","eq":["telo"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":15,"unilateral":false,"sideMode":"none","focus":["Proveď drobné přikývnutí jako tiché ano.","Make a tiny nod as if quietly saying yes."],"startPosition":["Lehni na záda a pokrč kolena. Hlavu podepři jen tolik, aby krk spočíval pohodlně.","Lie supine with knees bent, using only enough head support for a comfortable neck position."],"execution":["Proveď drobné přikývnutí jako tiché ano. Zadní část hlavy zůstává opřená, potom povol. Jeden pohyb a návrat je jedno opakování.","Make a tiny nod as if quietly saying yes. Keep the back of the head supported, then relax. One movement and return is one repetition."],"watchFor":["Nezvedej hlavu ze země a netlač bradu silou k hrudníku.","Do not lift the head or force the chin toward the chest."]},"progression":["Rozsah může být nepatrný, pauza není nutná. Opora pod hlavou slouží pohodlné poloze, nikoli k tlačení krku do určitého úhlu. Zvedání hlavy je samostatný náročnější úkol.","The movement may be tiny and needs no pause. Head support serves comfort rather than forcing a particular neck angle. Lifting the head is a separate, more demanding task."]}}},"ex26_mob_quadruped_head_rotation":{"id":"ex26_mob_quadruped_head_rotation","segment":"I","edits":{"exe":["Pomalu otoč hlavu v pohodlném rozsahu a vrať do středu. Hrudník zůstává klidný. Otočení na jednu stranu a návrat do středu je jedno opakování; strany střídej a zapisuj jejich celkový počet.","Slowly turn the head within a comfortable range and return to centre. Keep the chest quiet. One turn to either side and return to centre is one repetition; alternate sides and record the total."],"pro":["Zmenši otočení nebo sérii přeruš a odpočiň si. Opora předloktí o pevný vysoký stůl je jiná možnost nastavení, pokud ti vyhovuje; poznamenej ji a neporovnávej přímo s polohou na čtyřech.","Reduce the turn or pause the set to rest. Forearm support on a stable high table is another setup option if it suits you; note it and do not compare it directly with all fours."],"equipmentDetail":["Pro zobrazenou polohu na čtyřech stačí pevná pohodlná plocha. Stůl není součástí této varianty; potřebuješ jej jen při výslovné změně opory.","The illustrated all-fours position needs only a firm comfortable surface. A table is not part of this version; it is needed only when explicitly changing the support."],"source":{"author":"Gwendolen Jull, Michele Sterling / University of Queensland; TIMS NHS host","document":"Whiplash Injury Recovery 2019 — quadruped rotation, printed p.22","url":"https://www.tims.nhs.uk/wp-content/uploads/2020/09/Whiplash-Injury-Recovery-booklet-2019.pdf","scope":"Original text explicitly offers rotation on hands and knees. Existing app coaching is kept; one turn plus return as one repetition is an app logging convention, not a claim about source dosage. No automatic historical pair/turn conversion. PDF figures not visually certified."}},"taxonomy":{"regions":["neck"],"secondaryRegions":["shoulders"],"movements":["joint"],"focus":["mobility","coordination"],"positions":["quadruped"],"supports":["hand_support"],"priority":1,"equipmentRequirements":[["telo"]],"aliases":["quadruped neck rotation","rotace krku na čtyřech"]},"policy":{"id":"ex26_mob_quadruped_head_rotation","measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"alternating","requirements":[["telo"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false,"blockedMotionSources":["/exercise-motion/ex26_mob_quadruped_head_rotation-277a3d2e34344e3a.mp4"]},"art":{"appId":"ex26_mob_quadruped_head_rotation","atlasId":"ex26_mob_quadruped_head_rotation","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"ebd0189f4b0fc7c997f126d38aecb88c3bd79cf18455ce34e2d02b049de61320","thumb":"/expansion-atlas/ex26_mob_quadruped_head_rotation-original-256.webp","detail":"/expansion-atlas/ex26_mob_quadruped_head_rotation-original-960.webp","inkThumb":"/expansion-atlas/ex26_mob_quadruped_head_rotation-ink-256.webp","inkDetail":"/expansion-atlas/ex26_mob_quadruped_head_rotation-ink-960.webp","fillThumb":"/expansion-atlas/ex26_mob_quadruped_head_rotation-fill-256.webp","fillDetail":"/expansion-atlas/ex26_mob_quadruped_head_rotation-fill-960.webp"},"sourceSha256":"ebd0189f4b0fc7c997f126d38aecb88c3bd79cf18455ce34e2d02b049de61320","contourOnly":true,"darkOutline":true},"libraryOrder":10002,"deliveryProfiles":{"57e54abf64371256":{"fields":{"id":"ex26_mob_quadruped_head_rotation","cz":"Otáčení hlavy v opoře na čtyřech","en":"Quadruped Cervical Rotation","pat":"mobilita","eq":["telo"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":15,"unilateral":true,"sideMode":"alternating","focus":["Pomalu otoč hlavu k jednomu rameni a zpět.","Slowly turn the head toward one shoulder and return, alternating without rotating the chest."],"startPosition":["Na čtyřech polož dlaně pod ramena a kolena pod kyčle. Krk navazuje na trup.","Set hands beneath shoulders and knees beneath hips, with the neck continuing the trunk line."],"execution":["Pomalu otoč hlavu v pohodlném rozsahu a vrať do středu. Hrudník zůstává klidný. Otočení na jednu stranu a návrat do středu je jedno opakování; strany střídej a zapisuj jejich celkový počet.","Slowly turn the head within a comfortable range and return to centre. Keep the chest quiet. One turn to either side and return to centre is one repetition; alternate sides and record the total."],"watchFor":["Nenech hlavu viset a neopírej ji o zem. Při závrati pohyb ukonči.","Do not let the head hang or rest it on the floor. Stop the movement if dizzy."]},"progression":["Zmenši otočení nebo sérii přeruš a odpočiň si. Opora předloktí o pevný vysoký stůl je jiná možnost nastavení, pokud ti vyhovuje; poznamenej ji a neporovnávej přímo s polohou na čtyřech.","Reduce the turn or pause the set to rest. Forearm support on a stable high table is another setup option if it suits you; note it and do not compare it directly with all fours."]}}},"ex26_mob_quadruped_neck_control":{"id":"ex26_mob_quadruped_neck_control","segment":"I","edits":{"ez":null,"exe":["Hlavu lehce spusť a potom pomalu vrať do linie trupu. Při návratu ponech bradu mírně zasunutou. Jeden pohyb a návrat je jedno opakování.","Lower the head slightly, then slowly restore trunk alignment while keeping the chin gently tucked. One movement and return is one repetition."],"pro":["Zvol malý pohodlný pohyb, případně krátkou pauzu v ose. Vyšší opora předloktí o pevný stůl mění nastavení a nárok; není povinným postupem. Přikývnutí vleže není totožný pohyb proti gravitaci.","Choose a small comfortable movement, with an optional brief pause in alignment. A higher forearm support on a stable table changes the setup and demand; it is not a required progression. A supine nod is not the same movement against gravity."],"equipmentDetail":["Pro tuto variantu dlaně a kolena na pevné pohodlné ploše. Případnou změnu opory na stůl zaznamenej zvlášť.","For this version, support hands and knees on a firm comfortable surface. Record any switch to table support separately."],"source":{"author":"Gwendolen Jull, Michele Sterling / University of Queensland; TIMS NHS host","document":"Whiplash Injury Recovery 2019 — neck extensor control, printed pp.26–27","url":"https://www.tims.nhs.uk/wp-content/uploads/2020/09/Whiplash-Injury-Recovery-booklet-2019.pdf","scope":"Original text offers elbow support or hands/knees and return from flexion while retaining a gently tucked upper neck. App uses the existing smaller movement to trunk alignment, without clinical muscle isolation, pain relief or mandatory progression. PDF figures not visually certified."}},"taxonomy":{"regions":["neck"],"secondaryRegions":["shoulders"],"movements":["joint"],"focus":["coordination"],"positions":["quadruped"],"supports":["hand_support"],"priority":1,"equipmentRequirements":[["telo"]],"aliases":["quadruped neck control","návrat hlavy do osy na čtyřech"]},"policy":{"id":"ex26_mob_quadruped_neck_control","measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"none","requirements":[["telo"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false,"blockedMotionSources":[]},"art":{"appId":"ex26_mob_quadruped_neck_control","atlasId":"ex26_mob_quadruped_neck_control","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"511f5feff8389edf113fa38bc95e23f64af146df1effd358ab18c91465a88e36","thumb":"/expansion-atlas/ex26_mob_quadruped_neck_control-original-256.webp","detail":"/expansion-atlas/ex26_mob_quadruped_neck_control-original-960.webp","inkThumb":"/expansion-atlas/ex26_mob_quadruped_neck_control-ink-256.webp","inkDetail":"/expansion-atlas/ex26_mob_quadruped_neck_control-ink-960.webp","fillThumb":"/expansion-atlas/ex26_mob_quadruped_neck_control-fill-256.webp","fillDetail":"/expansion-atlas/ex26_mob_quadruped_neck_control-fill-960.webp"},"sourceSha256":"511f5feff8389edf113fa38bc95e23f64af146df1effd358ab18c91465a88e36","contourOnly":true,"darkOutline":true},"libraryOrder":10003,"deliveryProfiles":{"325b433ab81295dc":{"fields":{"id":"ex26_mob_quadruped_neck_control","cz":"Řízené napřímení krku na čtyřech","en":"Quadruped Neck Extension with Chin Control","pat":"mobilita","eq":["telo"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":15,"unilateral":false,"sideMode":"none","focus":["Hlavu lehce spusť a potom pomalu vrať do linie trupu.","Lower the head slightly, then slowly restore trunk alignment while keeping the chin gently tucked."],"startPosition":["Začni na čtyřech, dlaně pod rameny a hlava v prodloužení zad. Dívej se mezi ruce.","Begin on all fours with palms beneath shoulders and head aligned with the back, looking between the hands."],"execution":["Hlavu lehce spusť a potom pomalu vrať do linie trupu. Při návratu ponech bradu mírně zasunutou. Jeden pohyb a návrat je jedno opakování.","Lower the head slightly, then slowly restore trunk alignment while keeping the chin gently tucked. One movement and return is one repetition."],"watchFor":["Nevystrkuj bradu a nezvedej hlavu do výrazného záklonu.","Avoid jutting the chin or lifting into marked neck extension."]},"progression":["Zvol malý pohodlný pohyb, případně krátkou pauzu v ose. Vyšší opora předloktí o pevný stůl mění nastavení a nárok; není povinným postupem. Přikývnutí vleže není totožný pohyb proti gravitaci.","Choose a small comfortable movement, with an optional brief pause in alignment. A higher forearm support on a stable table changes the setup and demand; it is not a required progression. A supine nod is not the same movement against gravity."]}}},"ex26_dns_prone_turn":{"id":"ex26_dns_prone_turn","segment":"I","edits":{"pos":["Lehni na břicho. Lokty dej mírně od těla, opři lokty a předloktí a nech pánev i nohy na podložce. Zvedni hrudník jen tolik, aby opora a poloha krku zůstaly pohodlné.","Lie on your stomach. Set the elbows slightly out from the body, support the elbows and forearms, and keep the pelvis and legs on the surface. Raise the chest only as far as the support and neck position remain comfortable."],"exe":["Udržuj lehkou oporu paží a volný dech. Otoč hlavu v pohodlném rozsahu bez otáčení hrudníku, vrať do středu a střídej směr. Otočení na jednu stranu a návrat do středu je jedno opakování; strany střídej a zapisuj jejich celkový počet.","Maintain light arm support and free breathing. Turn the head comfortably without rotating the chest, return to centre and alternate directions. One turn to either side and return to centre is one repetition; alternate sides and record the total."],"pro":["Zmenši otočení nebo výšku hrudníku a znovu najdi pohodlnou oporu. Pohyb není testem správného vývoje ani povinným stupněm jiné dovednosti.","Reduce the turn or chest height and find a comfortable support again. This movement is not a test of normal development or a required stage for another skill."],"foc":["Otáčení hlavy při stabilní opoře předloktí a klidném trupu.","Head turning with steady forearm support and a quiet trunk."],"equipmentDetail":["Pohodlná pevná plocha, případně podložka pod lokty a pánev; bez dalšího odporu.","A firm comfortable surface, optionally padded under the elbows and pelvis; no added resistance."],"source":{"author":"Alena Kobesova, Ida Nørgaard, Pavel Kolar","document":"Dynamic Neuromuscular Stabilization — prone support and head rotation, chapter p.14","url":"https://rehabps.com/DATA/DNS_Neurorehab_Chapter.pdf","scope":"Original authors’ text read at PDF page13: elbow-supported prone developmental position and optional isolated head rotation. App adapts setup to comfort, does not enforce diagnostic support geometry or claim neurological normalization. One turn/return convention is editorial. Source PDF figures could not be visually certified."}},"taxonomy":{"regions":["neck"],"secondaryRegions":["shoulders","trunk","back"],"movements":["joint"],"focus":["coordination"],"positions":["prone"],"supports":["forearm_support"],"priority":2,"equipmentRequirements":[["telo"]],"aliases":["prone supported head rotation","rotace hlavy v opoře na loktech"]},"policy":{"id":"ex26_dns_prone_turn","measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"alternating","requirements":[["telo"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false,"blockedMotionSources":["/exercise-motion/ex26_dns_prone_turn-1025c54977f83de2.mp4"]},"art":{"appId":"ex26_dns_prone_turn","atlasId":"ex26_dns_prone_turn","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"d007d8bd9b0b225d795557aac3422af8e3e6c8209c13f42295259f1afab9d54e","thumb":"/expansion-atlas/ex26_dns_prone_turn-original-256.webp","detail":"/expansion-atlas/ex26_dns_prone_turn-original-960.webp","inkThumb":"/expansion-atlas/ex26_dns_prone_turn-ink-256.webp","inkDetail":"/expansion-atlas/ex26_dns_prone_turn-ink-960.webp","fillThumb":"/expansion-atlas/ex26_dns_prone_turn-fill-256.webp","fillDetail":"/expansion-atlas/ex26_dns_prone_turn-fill-960.webp"},"sourceSha256":"d007d8bd9b0b225d795557aac3422af8e3e6c8209c13f42295259f1afab9d54e","contourOnly":true,"darkOutline":true},"libraryOrder":10006,"deliveryProfiles":{"4fb0de78774d8d6f":{"fields":{"id":"ex26_dns_prone_turn","cz":"DNS · opora o lokty s otáčením hlavy","en":"DNS Prone Elbow Support with Head Rotation","pat":"stred","eq":["telo"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":90,"unilateral":true,"sideMode":"alternating","focus":["Otáčení hlavy při stabilní opoře předloktí a klidném trupu.","Head turning with steady forearm support and a quiet trunk."],"startPosition":["Lehni na břicho. Lokty dej mírně od těla, opři lokty a předloktí a nech pánev i nohy na podložce. Zvedni hrudník jen tolik, aby opora a poloha krku zůstaly pohodlné.","Lie on your stomach. Set the elbows slightly out from the body, support the elbows and forearms, and keep the pelvis and legs on the surface. Raise the chest only as far as the support and neck position remain comfortable."],"execution":["Udržuj lehkou oporu paží a volný dech. Otoč hlavu v pohodlném rozsahu bez otáčení hrudníku, vrať do středu a střídej směr. Otočení na jednu stranu a návrat do středu je jedno opakování; strany střídej a zapisuj jejich celkový počet.","Maintain light arm support and free breathing. Turn the head comfortably without rotating the chest, return to centre and alternate directions. One turn to either side and return to centre is one repetition; alternate sides and record the total."],"watchFor":["Nezakláněj hlavu a nedrž se v poloze sevřením hýždí. Otáčej pouze v pohodlném rozsahu.","Avoid throwing the head backward or maintaining the position by clenching the glutes. Turn within a comfortable range."]},"progression":["Zmenši otočení nebo výšku hrudníku a znovu najdi pohodlnou oporu. Pohyb není testem správného vývoje ani povinným stupněm jiné dovednosti.","Reduce the turn or chest height and find a comfortable support again. This movement is not a test of normal development or a required stage for another skill."]}}},"ig28_neck_side_lift":{"id":"ig28_neck_side_lift","segment":"I","edits":{"ez":null,"exe":["Pomalu odlehči hlavu od ručníku a zvedni ji jen do prodloužení trupu. Obličej stále směřuje před tebe. Vrať hlavu na oporu; po sérii vyměň bok. Jeden zdvih a položení je jedno opakování na zvolený bok; druhý bok zapisuj zvlášť.","Slowly lift the head just clear of the towel toward trunk alignment. Keep facing forward. Lower onto the support; change sides after the set. One lift and lowering is one repetition on the selected side; record the other side separately."],"pro":["Stačí nepatrné odlehčení hlavy. Krátká pauza nebo pomalejší položení jsou volitelné, nikoli povinné. Nepřidávej závaží na hlavu. Ruční izometrie vsedě je jiný způsob zatížení, ne automatický mezistupeň.","Barely unweighting the head is enough. A brief pause or slower lowering is optional rather than required. Do not add a head weight. Seated manual isometrics are a different loading task, not an automatic intermediate step."]},"taxonomy":{"regions":["neck"],"secondaryRegions":[],"movements":["joint"],"focus":["strength"],"positions":["side_lying"],"supports":["head_support","hand_support"],"priority":2,"equipmentRequirements":[["towel"]],"aliases":[]},"policy":{"id":"ig28_neck_side_lift","measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"perSide","requirements":[["towel"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false,"blockedMotionSources":["/exercise-motion/ig28_neck_side_lift-64fbe2876f60fa6f.mp4"],"sideMeaning":["Směr úklonu hlavy (horní strana)","Head side-bending direction (upper side)"]},"art":{"appId":"ig28_neck_side_lift","atlasId":"ig28_neck_side_lift","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"bf3222319a750616a8343f23b20f5e565934db2171749de528d3c23a8968ce55","thumb":"/expansion-atlas/ig28_neck_side_lift-original-256.webp","detail":"/expansion-atlas/ig28_neck_side_lift-original-960.webp","inkThumb":"/expansion-atlas/ig28_neck_side_lift-ink-256.webp","inkDetail":"/expansion-atlas/ig28_neck_side_lift-ink-960.webp","fillThumb":"/expansion-atlas/ig28_neck_side_lift-fill-256.webp","fillDetail":"/expansion-atlas/ig28_neck_side_lift-fill-960.webp"},"sourceSha256":"bf3222319a750616a8343f23b20f5e565934db2171749de528d3c23a8968ce55","contourOnly":true,"darkOutline":true},"libraryOrder":10008,"deliveryProfiles":{"3523c7ea71aea05f":{"fields":{"id":"ig28_neck_side_lift","cz":"Zvedání hlavy vleže na boku","en":"Side-Lying Neck Lift","pat":"krk","eq":["telo"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":45,"unilateral":true,"sideMode":"perSide","focus":["Malý zdvih v jedné rovině, bez otáčení.","A small lift in one plane, without turning."],"startPosition":["Lehni si na bok, mírně pokrč kolena a srovnej ramena nad sebe. Hlavu opři o složený ručník, horní dlaň polož před hrudník.","Lie on your side with knees softly bent and shoulders stacked. Rest the head on a folded towel; place the upper palm in front of the chest."],"execution":["Pomalu odlehči hlavu od ručníku a zvedni ji jen do prodloužení trupu. Obličej stále směřuje před tebe. Vrať hlavu na oporu; po sérii vyměň bok. Jeden zdvih a položení je jedno opakování na zvolený bok; druhý bok zapisuj zvlášť.","Slowly lift the head just clear of the towel toward trunk alignment. Keep facing forward. Lower onto the support; change sides after the set. One lift and lowering is one repetition on the selected side; record the other side separately."],"watchFor":["Netahej ucho vysoko k rameni a neotáčej obličej. Trup zůstává na boku. Při závrati, brnění, vystřelující bolesti nebo nové bolesti hlavy přestaň.","Avoid a large ear-to-shoulder bend or turning the face. Keep the torso on its side. Stop for dizziness, tingling, radiating pain or a new headache."]},"progression":["Stačí nepatrné odlehčení hlavy. Krátká pauza nebo pomalejší položení jsou volitelné, nikoli povinné. Nepřidávej závaží na hlavu. Ruční izometrie vsedě je jiný způsob zatížení, ne automatický mezistupeň.","Barely unweighting the head is enough. A brief pause or slower lowering is optional rather than required. Do not add a head weight. Seated manual isometrics are a different loading task, not an automatic intermediate step."]}}},"ig28_neck_supine_lift":{"id":"ig28_neck_supine_lift","segment":"I","edits":{"exe":["Drobně přikývni a zachovej tuto polohu brady. Zvedni hlavu jen nepatrně od opory, krátce zastav a pomalu ji polož. Ramena se nezvedají. Jeden zdvih a položení je jedno opakování.","Make a small nod and retain the chin position. Lift the head just clear of its support, pause briefly and lower slowly. Keep the shoulders down. One lift and lowering is one repetition."],"pro":["Pokud je zdvih příliš náročný, ponech hlavu podepřenou a cvič jen drobné přikývnutí. Pauza nebo pomalejší položení jsou volitelné; nepřidávej závaží na hlavu.","If lifting is too demanding, keep the head supported and practise only a small nod. A pause or slower lowering is optional; do not add a head weight."],"equipmentDetail":["Pevná pohodlná plocha; cvičební podložka a tenký složený ručník pod hlavu jsou volitelné podle pohodlí.","A firm comfortable surface; an exercise mat and thin folded towel under the head are optional for comfort."]},"taxonomy":{"regions":["neck"],"secondaryRegions":[],"movements":["joint"],"focus":["strength"],"positions":["supine"],"supports":["head_support"],"priority":2,"equipmentRequirements":[["telo"]],"aliases":[]},"policy":{"id":"ig28_neck_supine_lift","measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"none","requirements":[["telo"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false,"blockedMotionSources":[]},"art":{"appId":"ig28_neck_supine_lift","atlasId":"ig28_neck_supine_lift","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"2a5bcb5b15478445a985216fd2103b952c1db690b989a872260bdd2dca1df0e3","thumb":"/expansion-atlas/ig28_neck_supine_lift-original-256.webp","detail":"/expansion-atlas/ig28_neck_supine_lift-original-960.webp","inkThumb":"/expansion-atlas/ig28_neck_supine_lift-ink-256.webp","inkDetail":"/expansion-atlas/ig28_neck_supine_lift-ink-960.webp","fillThumb":"/expansion-atlas/ig28_neck_supine_lift-fill-256.webp","fillDetail":"/expansion-atlas/ig28_neck_supine_lift-fill-960.webp"},"sourceSha256":"2a5bcb5b15478445a985216fd2103b952c1db690b989a872260bdd2dca1df0e3","contourOnly":true,"darkOutline":true},"libraryOrder":10007,"deliveryProfiles":{"9514bc288a200177":{"fields":{"id":"ig28_neck_supine_lift","cz":"Přikývnutí se zvednutím hlavy vleže","en":"Supine Chin Nod with Head Lift","pat":"krk","eq":["telo"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":45,"unilateral":false,"sideMode":"none","focus":["Nejdřív přikývnutí, potom malý zdvih.","Nod first, then make a small lift."],"startPosition":["Lehni si na záda, pokrč kolena a nech lopatky opřené. Čelist uvolni; podle potřeby podepři hlavu tenkým ručníkem.","Lie on your back with knees bent and shoulder blades supported. Relax the jaw; use a thin towel under the head if needed."],"execution":["Drobně přikývni a zachovej tuto polohu brady. Zvedni hlavu jen nepatrně od opory, krátce zastav a pomalu ji polož. Ramena se nezvedají. Jeden zdvih a položení je jedno opakování.","Make a small nod and retain the chin position. Lift the head just clear of its support, pause briefly and lower slowly. Keep the shoulders down. One lift and lowering is one repetition."],"watchFor":["Nevysunuj bradu, nezatínej zuby a nepřecházej do zkracovačky. Pokud přikývnutí neudržíš, hlavu polož. Při závrati, brnění, vystřelující bolesti nebo nové bolesti hlavy přestaň.","Do not jut the chin, clench the teeth or turn this into a crunch. Rest the head if the nod is lost. Stop for dizziness, tingling, radiating pain or a new headache."]},"progression":["Pokud je zdvih příliš náročný, ponech hlavu podepřenou a cvič jen drobné přikývnutí. Pauza nebo pomalejší položení jsou volitelné; nepřidávej závaží na hlavu.","If lifting is too demanding, keep the head supported and practise only a small nod. A pause or slower lowering is optional; do not add a head weight."]}}},"ig28_neck_prone_lift":{"id":"ig28_neck_prone_lift","segment":"I","edits":{"ez":null,"exe":["Z nepatrně sklopené polohy pomalu zvedni hlavu jen do linie zad, bradu drž lehce přikývnutou. Dívej se dolů. Vrať o malý kousek a po sérii hlavu znovu podepři. Jeden zdvih a řízený návrat je jedno opakování.","From slight head flexion, slowly lift only to the line of the back with a gentle chin nod. Look down. Lower a small distance and support the head again after the set. One lift and controlled return is one repetition."],"pro":["Zmenši pohyb nebo lehce podepři část váhy hlavy dlaní. Krátká pauza v ose je volitelná. Nepřidávej větší záklon ani závaží; ruční izometrie vsedě je jiný úkol.","Reduce the movement or lightly support some of the head weight with a palm. A brief pause in alignment is optional. Do not add extra extension or a weight; seated manual isometrics are a different task."]},"taxonomy":{"regions":["neck"],"secondaryRegions":[],"movements":["joint"],"focus":["strength"],"positions":["prone"],"supports":["chair_bench"],"priority":2,"equipmentRequirements":[["long_prone_bench"]],"aliases":[]},"policy":{"id":"ig28_neck_prone_lift","measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"none","requirements":[["long_prone_bench"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false,"blockedMotionSources":[]},"art":{"appId":"ig28_neck_prone_lift","atlasId":"ig28_neck_prone_lift","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"1148c6466467c937e574d53ee8dadfda73ede63cb6572002e88e02e721d32206","thumb":"/expansion-atlas/ig28_neck_prone_lift-original-256.webp","detail":"/expansion-atlas/ig28_neck_prone_lift-original-960.webp","inkThumb":"/expansion-atlas/ig28_neck_prone_lift-ink-256.webp","inkDetail":"/expansion-atlas/ig28_neck_prone_lift-ink-960.webp","fillThumb":"/expansion-atlas/ig28_neck_prone_lift-fill-256.webp","fillDetail":"/expansion-atlas/ig28_neck_prone_lift-fill-960.webp"},"sourceSha256":"1148c6466467c937e574d53ee8dadfda73ede63cb6572002e88e02e721d32206","contourOnly":true,"darkOutline":true},"libraryOrder":10009,"deliveryProfiles":{"036c5d2b0d08b102":{"fields":{"id":"ig28_neck_prone_lift","cz":"Zvedání hlavy do osy trupu vleže na břiše","en":"Supported Prone Neck Extension to Neutral","pat":"krk","eq":["telo","lavice"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":45,"unilateral":false,"sideMode":"none","focus":["Hlava se vrací do osy, nikoli do záklonu.","Bring the head back into line, without looking up."],"startPosition":["Lehni si na břicho na pevnou nízkou lavici. Hrudník, pánev i nohy nech opřené, hlavu za hranou. Při nastavení ji lehce podepři dlaní pod čelem.","Lie face down on a stable low bench with chest, pelvis and legs supported and head beyond the end. Lightly support the forehead with a palm while setting up."],"execution":["Z nepatrně sklopené polohy pomalu zvedni hlavu jen do linie zad, bradu drž lehce přikývnutou. Dívej se dolů. Vrať o malý kousek a po sérii hlavu znovu podepři. Jeden zdvih a řízený návrat je jedno opakování.","From slight head flexion, slowly lift only to the line of the back with a gentle chin nod. Look down. Lower a small distance and support the head again after the set. One lift and controlled return is one repetition."],"watchFor":["Nedívej se před sebe ani vzhůru a nenechávej hlavu volně padat. Hrudník zůstává na lavici. Při závrati, brnění, vystřelující bolesti nebo nové bolesti hlavy přestaň.","Do not look forward or upward, or let the head drop freely. Keep the chest on the bench. Stop for dizziness, tingling, radiating pain or a new headache."]},"progression":["Zmenši pohyb nebo lehce podepři část váhy hlavy dlaní. Krátká pauza v ose je volitelná. Nepřidávej větší záklon ani závaží; ruční izometrie vsedě je jiný úkol.","Reduce the movement or lightly support some of the head weight with a palm. A brief pause in alignment is optional. Do not add extra extension or a weight; seated manual isometrics are a different task."]}}},"openbook":{"id":"openbook","segment":"J","edits":{"source":{"author":"Movement Redefined","document":"Open Books with Over Hand (OH) Reach","url":"https://movementredefinedaz.com/exercises-library/open-books-with-over-hand-oh-reach-a-simple-move-to-improve-mobility/","scope":"Independent first-party exercise instructions support the existing overhead arm arc and controlled return from side lying. Comfortable neck position, reduced range and the new-record counting convention are editorial adaptations; no clinical outcome or universal dose is claimed."},"pos":["Lehni si na bok, kolena pohodlně pokrč a nech je nad sebou. Paže dej před tělo. Hlavu podlož, pokud by jinak visela do strany; opora nesmí bránit pohodlnému otočení.","Lie on your side with the knees comfortably bent and stacked. Place the arms in front of the body. Support the head if it would otherwise hang sideways, without restricting a comfortable turn."],"exe":["Horní paží veď pomalý oblouk kolem hlavy směrem dozadu a nech hrudník otevřít. Vrať paži stejnou cestou před tělo. Oblouk a návrat je jedno opakování na straně pohybující se paže; pak se přetoč na druhý bok. Dýchej volně, ruka nemusí dosáhnout podlahy.","Move the upper arm slowly in an arc past the head toward the back, allowing the chest to open. Return along the same path to the front. One arc and return is one repetition for the moving arm; then roll onto the other side. Breathe freely; the hand need not reach the floor."],"wat":["Kolena nech lehce u sebe a pánev co nejklidnější, bez silového přitlačování. Nezískávej dosah převalením celého těla nebo trhnutím. Hlava může pohyb pohodlně následovat, ale nemusíš za rukou otáčet krk do krajní polohy.","Keep the knees lightly together and the pelvis relatively still without pinning it down forcefully. Do not gain reach by rolling the whole body or jerking. The head may follow comfortably; do not force the neck to follow the hand into an end position."],"pro":["Lehčí: menší oblouk nebo mírně pokrčený loket. Dále můžeš zpomalit návrat či krátce zastavit v pohodlném otevření. Kontakt ruky se zemí, větší rozsah ani delší výdrž nejsou povinný cíl.","Easier: use a smaller arc or a softly bent elbow. You may then slow the return or pause briefly in a comfortable opening. Floor contact, more range and longer holds are not compulsory targets."],"foc":["Otevírej hrudník s pohodlným obloukem paže; pánev se nepřevalí za rukou.","Open the chest with a comfortable arm arc without rolling the pelvis after the hand."],"equipmentDetail":["Rovná neklouzavá plocha s místem pro oblouk paže; podložka a měkká opora hlavy jsou volitelné podle pohodlí. Žádná přídavná zátěž.","A level non-slip surface with room for the arm arc; a mat and soft head support are optional for comfort. No added weight."]},"taxonomy":{"movements":["trunk_movement","joint"],"focus":["mobility","coordination"],"positions":["side_lying"],"supports":[],"equipmentRequirements":[["telo"]],"priority":1},"policy":{"id":"openbook","measurementType":"REPS_ONLY","loadMode":"none","sideMode":"perSide","requirements":[["telo"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false,"sideMeaning":["Horní pohybující se paže","Moving upper arm"]},"art":{"appId":"openbook","atlasId":"openbook","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"19d1d5151fd1eb2a7a7620eb3d1f9a16ec37d9db87343d88a7b88faae847bf6c","thumb":"/unified-atlas/openbook-ebe40a54c04ec2d6-thumb.webp","detail":"/unified-atlas/openbook-c9ed7b55a5eadfba-detail.webp","inkThumb":"/unified-atlas/openbook-b258d5598a8500ac-inkThumb.webp","inkDetail":"/unified-atlas/openbook-e4f4e1abd798b915-inkDetail.webp","fillThumb":"/unified-atlas/openbook-1a36a83fc14562dc-fillThumb.webp","fillDetail":"/unified-atlas/openbook-28659c4e2fd7fa90-fillDetail.webp"},"sourceSha256":"19d1d5151fd1eb2a7a7620eb3d1f9a16ec37d9db87343d88a7b88faae847bf6c","contourOnly":true,"darkOutline":true},"libraryOrder":9000,"deliveryProfiles":{"527418b051e88a6e":{"fields":{"id":"openbook","cz":"Otevřená kniha","en":"Thoracic Open Book","pat":"mobilita","eq":["telo"],"measurementType":"REPS_ONLY","defaultRestSec":15,"unilateral":true,"sideMode":"perSide","focus":["Otevírej hrudník s pohodlným obloukem paže; pánev se nepřevalí za rukou.","Open the chest with a comfortable arm arc without rolling the pelvis after the hand."],"startPosition":["Lehni si na bok, kolena pohodlně pokrč a nech je nad sebou. Paže dej před tělo. Hlavu podlož, pokud by jinak visela do strany; opora nesmí bránit pohodlnému otočení.","Lie on your side with the knees comfortably bent and stacked. Place the arms in front of the body. Support the head if it would otherwise hang sideways, without restricting a comfortable turn."],"execution":["Horní paží veď pomalý oblouk kolem hlavy směrem dozadu a nech hrudník otevřít. Vrať paži stejnou cestou před tělo. Oblouk a návrat je jedno opakování na straně pohybující se paže; pak se přetoč na druhý bok. Dýchej volně, ruka nemusí dosáhnout podlahy.","Move the upper arm slowly in an arc past the head toward the back, allowing the chest to open. Return along the same path to the front. One arc and return is one repetition for the moving arm; then roll onto the other side. Breathe freely; the hand need not reach the floor."],"watchFor":["Kolena nech lehce u sebe a pánev co nejklidnější, bez silového přitlačování. Nezískávej dosah převalením celého těla nebo trhnutím. Hlava může pohyb pohodlně následovat, ale nemusíš za rukou otáčet krk do krajní polohy.","Keep the knees lightly together and the pelvis relatively still without pinning it down forcefully. Do not gain reach by rolling the whole body or jerking. The head may follow comfortably; do not force the neck to follow the hand into an end position."]},"progression":["Lehčí: menší oblouk nebo mírně pokrčený loket. Dále můžeš zpomalit návrat či krátce zastavit v pohodlném otevření. Kontakt ruky se zemí, větší rozsah ani delší výdrž nejsou povinný cíl.","Easier: use a smaller arc or a softly bent elbow. You may then slow the return or pause briefly in a comfortable opening. Floor contact, more range and longer holds are not compulsory targets."]}}},"thoracicext":{"id":"thoracicext","segment":"J","edits":{"eq":["flat_bench"],"source":{"author":"David Song / Rehab Hero","document":"Bench Thoracic Extension","url":"https://www.rehabhero.ca/exercise/bench-thoracic-extension","scope":"First-party instructions support upper-back contact at the free edge of a flat bench, feet grounded, hands supporting the head, controlled extension and return. The existing floor-seated setup and DURATION metric are retained; seconds of active movement are a forward recording convention, not a source dose or conversion of earlier holds. No clinical condition claim is adopted."},"pos":["Sedni si na zem před stabilní rovnou lavici, pokrč kolena a opři chodidla. Horní záda opři o její pohodlnou hranu přibližně u lopatek. Výšku zvol tak, abys na oporu dosáhl ze sedu. Ruce lehce podpírají hlavu, netahají za krk.","Sit on the floor in front of a stable flat bench with knees bent and feet grounded. Rest the upper back against a comfortable edge around shoulder-blade level. The support must be low enough to reach from sitting. Let the hands lightly support the head without pulling the neck."],"exe":["Pomalu otevři hrudník přes oporu jen o malý pohodlný rozsah a vrať se. Pánev zůstává na zemi, chodidla pomáhají držet polohu. Pro novou sérii zapisuj sekundy plynulého kontrolovaného pohybu, bez přípravy a odpočinku; krátká pauza v otevření je možná.","Slowly extend the upper back a small comfortable amount over the support, then return. Keep the pelvis on the floor and use the feet to steady the position. For a new set, record seconds of smooth controlled movement, excluding setup and rest; a brief pause in extension is optional."],"wat":["Nezatlačuj ostrou hranu do zad, neházej hlavou a nedoháněj rozsah výrazným prohnutím beder. Pokud lavice nedovolí pohodlný kontakt v sedu, tuto sestavu nepoužívej. Při bolesti nebo závrati pohyb ukonči.","Avoid pressing a sharp edge into the back, throwing the head back or gaining range through a large lower-back arch. Do not use this setup if the bench does not allow comfortable contact while seated. Stop for pain or dizziness."],"pro":["Lehčí: menší pohyb a kratší úsek. Dále můžeš pohyb zpomalit při stejné klidné poloze. Posun opory níž po zádech ani hlubší záklon nejsou automatický postup. Poznamenej výšku opory a zda série obsahovala pohyb nebo výdrž; staré časy nepřepočítávej.","Easier: use a smaller movement and a shorter interval. You may then move more slowly while maintaining the same steady position. Moving the support lower down the back or arching deeper is not an automatic progression. Note the support height and whether the set used movement or a hold; do not convert previous times."],"foc":["Malý pohodlný pohyb horních zad přes oporu, bez tahu za hlavu.","A small comfortable upper-back movement over the support without pulling the head."],"equipmentDetail":["Stabilní rovná lavice s přístupnou neostrou hranou a vhodnou výškou pro sed na zemi. Samotná dostupnost lavice nezaručuje vhodnou výšku. Případné tenké polstrování musí držet na místě. Židle, válec nebo klek s lokty na lavici nejsou automaticky stejná varianta.","A stable flat bench with an accessible, non-sharp edge at a suitable height for sitting on the floor. Having a bench does not guarantee a suitable height. Any thin padding must stay in place. A chair, roller or kneeling with elbows on a bench is not automatically the same variation."]},"taxonomy":{"movements":["trunk_movement"],"focus":["mobility","coordination"],"positions":["seated"],"supports":["chair_bench"],"equipmentRequirements":[["flat_bench"]],"priority":2},"policy":{"id":"thoracicext","measurementType":"DURATION","loadMode":"none","sideMode":"none","requirements":[["flat_bench"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"requiresEquipmentCheck":true,"allowEstimatedMax":false,"allowComparableRecords":false},"art":{"appId":"thoracicext","atlasId":"thoracicext","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"a0c019fbee3786b06f5ae74f9d15accb0ce9a5896f54bf1208e5f1bddaf16011","thumb":"/unified-atlas/thoracicext-c628f157aa5e9023-thumb.webp","detail":"/unified-atlas/thoracicext-6661aff80fc05374-detail.webp","inkThumb":"/unified-atlas/thoracicext-059d21e49893f9c4-inkThumb.webp","inkDetail":"/unified-atlas/thoracicext-3978f72a4cbba184-inkDetail.webp","fillThumb":"/unified-atlas/thoracicext-7fc7e142b971b7b1-fillThumb.webp","fillDetail":"/unified-atlas/thoracicext-45e18c49b1a04eaa-fillDetail.webp"},"sourceSha256":"a0c019fbee3786b06f5ae74f9d15accb0ce9a5896f54bf1208e5f1bddaf16011","contourOnly":true,"darkOutline":true},"libraryOrder":9001,"deliveryProfiles":{"1e7832334ebc2198":{"fields":{"id":"thoracicext","cz":"Hrudní extenze","en":"Thoracic Extension","pat":"mobilita","eq":["flat_bench"],"measurementType":"DURATION","defaultRestSec":15,"unilateral":false,"sideMode":"none","focus":["Malý pohodlný pohyb horních zad přes oporu, bez tahu za hlavu.","A small comfortable upper-back movement over the support without pulling the head."],"startPosition":["Sedni si na zem před stabilní rovnou lavici, pokrč kolena a opři chodidla. Horní záda opři o její pohodlnou hranu přibližně u lopatek. Výšku zvol tak, abys na oporu dosáhl ze sedu. Ruce lehce podpírají hlavu, netahají za krk.","Sit on the floor in front of a stable flat bench with knees bent and feet grounded. Rest the upper back against a comfortable edge around shoulder-blade level. The support must be low enough to reach from sitting. Let the hands lightly support the head without pulling the neck."],"execution":["Pomalu otevři hrudník přes oporu jen o malý pohodlný rozsah a vrať se. Pánev zůstává na zemi, chodidla pomáhají držet polohu. Pro novou sérii zapisuj sekundy plynulého kontrolovaného pohybu, bez přípravy a odpočinku; krátká pauza v otevření je možná.","Slowly extend the upper back a small comfortable amount over the support, then return. Keep the pelvis on the floor and use the feet to steady the position. For a new set, record seconds of smooth controlled movement, excluding setup and rest; a brief pause in extension is optional."],"watchFor":["Nezatlačuj ostrou hranu do zad, neházej hlavou a nedoháněj rozsah výrazným prohnutím beder. Pokud lavice nedovolí pohodlný kontakt v sedu, tuto sestavu nepoužívej. Při bolesti nebo závrati pohyb ukonči.","Avoid pressing a sharp edge into the back, throwing the head back or gaining range through a large lower-back arch. Do not use this setup if the bench does not allow comfortable contact while seated. Stop for pain or dizziness."]},"progression":["Lehčí: menší pohyb a kratší úsek. Dále můžeš pohyb zpomalit při stejné klidné poloze. Posun opory níž po zádech ani hlubší záklon nejsou automatický postup. Poznamenej výšku opory a zda série obsahovala pohyb nebo výdrž; staré časy nepřepočítávej.","Easier: use a smaller movement and a shorter interval. You may then move more slowly while maintaining the same steady position. Moving the support lower down the back or arching deeper is not an automatic progression. Note the support height and whether the set used movement or a hold; do not convert previous times."]}}},"threadneedle":{"id":"threadneedle","segment":"J","edits":{"source":{"author":"Wrightington, Wigan and Leigh Teaching Hospitals NHS Foundation Trust","document":"Neck and Upper Back Exercises — Level 2, exercise 7, page 5","url":"https://www.wwl.nhs.uk/media/.leaflets/6214d1fe0a5965.24837304.pdf","scope":"The first-party physiotherapy leaflet supports reaching one arm under the other and then upward from quadruped. Existing historical sideMode none is preserved. Comfortable contact and one full-cycle counting are editorial clarifications; no leaflet dose or treatment prescription is adopted."},"pos":["Klekni si na všechny čtyři, dlaně přibližně pod ramena a kolena pod kyčle. Jedna dlaň zůstane opřená, druhá paže se bude pohybovat.","Start on all fours with hands roughly under shoulders and knees under hips. Keep one palm supported while the other arm moves."],"exe":["Pohyblivou paži provlékni pod opěrnou do strany a nech hrudník pohodlně otočit. Vrať ji zpět, otevři ji vzhůru a potom polož dlaň do výchozí opory. Tento celý sled je jedno opakování pro novou sérii. Proveď také druhou paži; rozdělení počtu mezi strany napiš do poznámky.","Thread the moving arm sideways beneath the supporting arm, allowing a comfortable chest rotation. Bring it back, open it upward, then return the palm to the starting support. This complete sequence is one repetition for a new set. Work the other arm too; note how the count is split between sides."],"wat":["Pánev nech přibližně nad koleny a netoč se za rukou celým tělem. Rameno či bok hlavy mohou lehce dosednout, ale kontakt s podlahou není cíl. Netlač na krk ani se neodrážej hlavou. Zvol menší dráhu, pokud ztrácíš klidnou oporu.","Keep the pelvis roughly above the knees instead of turning the whole body after the hand. The shoulder or side of the head may rest lightly, but floor contact is not a target. Do not load the neck or push off through the head. Use a smaller path if the support becomes unsteady."],"pro":["Lehčí: kratší provlečení a nižší otevření, případně menší série. Dále můžeš zpomalit pohyb nebo krátce zastavit bez tlaku na krk. Tato karta neurčuje maximální hloubku ani délku výdrže.","Easier: thread a shorter distance and open less high, or use a shorter set. You may then slow the movement or pause briefly without neck pressure. This card prescribes no maximum depth or hold duration."],"foc":["Jedna dlaň drží oporu, druhá paže vede provlečení a otevření hrudníku.","One palm supports you while the other arm guides the thread and chest opening."],"equipmentDetail":["Pevná neklouzavá plocha pro kolena a opěrnou dlaň, prostor pro paži do strany. Podložení kolen je volitelné.","A firm non-slip surface for the knees and supporting palm, with room for the arm to reach sideways. Knee padding is optional."]},"taxonomy":{"movements":["trunk_movement","joint"],"focus":["mobility","coordination"],"positions":["quadruped"],"supports":["hand_support"],"equipmentRequirements":[["telo"]],"priority":1},"policy":{"id":"threadneedle","measurementType":"REPS_ONLY","loadMode":"none","sideMode":"none","requirements":[["telo"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false},"art":{"appId":"threadneedle","atlasId":"threadneedle","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"ff6fd9607c17092b13c014ff1334424d3b1f01810dca337f81abc516bd524bb9","thumb":"/unified-atlas/threadneedle-fc320ba112c11d8e-thumb.webp","detail":"/unified-atlas/threadneedle-ea4b4b9cef88676e-detail.webp","inkThumb":"/unified-atlas/threadneedle-2ca5e515b7ad9d84-inkThumb.webp","inkDetail":"/unified-atlas/threadneedle-1ad8503246e83903-inkDetail.webp","fillThumb":"/unified-atlas/threadneedle-25aec86ff21af016-fillThumb.webp","fillDetail":"/unified-atlas/threadneedle-e0ab5f5dc67e237f-fillDetail.webp"},"sourceSha256":"ff6fd9607c17092b13c014ff1334424d3b1f01810dca337f81abc516bd524bb9","contourOnly":true,"darkOutline":true},"libraryOrder":9002,"deliveryProfiles":{"02427790e992b42f":{"fields":{"id":"threadneedle","cz":"Provlečení","en":"Thread the Needle","pat":"mobilita","eq":["telo"],"measurementType":"REPS_ONLY","defaultRestSec":15,"unilateral":false,"sideMode":"none","focus":["Jedna dlaň drží oporu, druhá paže vede provlečení a otevření hrudníku.","One palm supports you while the other arm guides the thread and chest opening."],"startPosition":["Klekni si na všechny čtyři, dlaně přibližně pod ramena a kolena pod kyčle. Jedna dlaň zůstane opřená, druhá paže se bude pohybovat.","Start on all fours with hands roughly under shoulders and knees under hips. Keep one palm supported while the other arm moves."],"execution":["Pohyblivou paži provlékni pod opěrnou do strany a nech hrudník pohodlně otočit. Vrať ji zpět, otevři ji vzhůru a potom polož dlaň do výchozí opory. Tento celý sled je jedno opakování pro novou sérii. Proveď také druhou paži; rozdělení počtu mezi strany napiš do poznámky.","Thread the moving arm sideways beneath the supporting arm, allowing a comfortable chest rotation. Bring it back, open it upward, then return the palm to the starting support. This complete sequence is one repetition for a new set. Work the other arm too; note how the count is split between sides."],"watchFor":["Pánev nech přibližně nad koleny a netoč se za rukou celým tělem. Rameno či bok hlavy mohou lehce dosednout, ale kontakt s podlahou není cíl. Netlač na krk ani se neodrážej hlavou. Zvol menší dráhu, pokud ztrácíš klidnou oporu.","Keep the pelvis roughly above the knees instead of turning the whole body after the hand. The shoulder or side of the head may rest lightly, but floor contact is not a target. Do not load the neck or push off through the head. Use a smaller path if the support becomes unsteady."]},"progression":["Lehčí: kratší provlečení a nižší otevření, případně menší série. Dále můžeš zpomalit pohyb nebo krátce zastavit bez tlaku na krk. Tato karta neurčuje maximální hloubku ani délku výdrže.","Easier: thread a shorter distance and open less high, or use a shorter set. You may then slow the movement or pause briefly without neck pressure. This card prescribes no maximum depth or hold duration."]}}},"scorpion":{"id":"scorpion","segment":"J","edits":{"source":{"author":"Physitrack","document":"Scorpion stretch","url":"https://uk.physitrack.com/home-exercise-video/scorpion","scope":"First-party text supports a prone starting position, outstretched arms and moving one heel across toward the opposite side before switching. A controlled smaller range without required foot-to-hand/floor contact is an editorial adaptation. This is combined hip/pelvis/trunk motion, not isolated thoracic rotation. No therapeutic effect or universal dose is claimed."},"pos":["Lehni si na břicho, paže rozlož pohodlně do stran a opři je. Hlavu nech v pohodlné nízké poloze. Nech kolem sebe dost místa pro pohyb nohy.","Lie face down with the arms comfortably out to the sides and supported. Keep the head in a comfortable low position. Leave enough space around you for the moving leg."],"exe":["Pokrč jedno koleno a pomalu veď patu přes druhou nohu směrem na opačnou stranu těla. Pánev se přitom otáčí; nepokoušej se pohyb izolovat jen do hrudníku. Vrať nohu pod kontrolou a vystřídej ji. Jeden přenos a návrat jedné nohy je jedno opakování pro novou sérii.","Bend one knee and slowly take the heel across the other leg toward the opposite side of the body. The pelvis turns with the movement; do not try to isolate it to the upper back. Return the leg with control, then switch. One crossing and return of one leg is one repetition for a new set."],"wat":["Horní část hrudníku a paže nech pohodlně opřené. Nešvihej nohou ani ji netlač silou k protější ruce či k podlaze. Zmenši rozsah, pokud se horní tělo výrazně odvaluje, cítíš tlak v bedrech nebo musíš zadržet dech.","Keep the upper chest and arms comfortably supported. Do not swing the leg or force it toward the opposite hand or the floor. Reduce the range if the upper body rolls substantially, the lower back feels compressed or you have to hold your breath."],"pro":["Lehčí: menší přenos nohy a kratší série. Dále můžeš zpomalit návrat v témže pohodlném rozsahu. Větší rotace a dlouhá krajní výdrž nejsou povinné. Zapisovaný počet zahrnuje jednotlivé přenosy; rozdělení na levou a pravou nohu uveď v poznámce.","Easier: use a smaller leg crossing and a shorter set. You may then slow the return within the same comfortable range. More rotation and long end-range holds are not compulsory. The recorded count includes individual crossings; note the split between left and right legs."],"foc":["Pomalý přenos pokrčené nohy, bez švihu a bez nuceného dosahu.","Move the bent leg across slowly, without momentum or forced reach."],"equipmentDetail":["Rovná neklouzavá plocha a volný prostor pro paže i pohyb nohy na obě strany. Podložka je volitelná; žádná zátěž na kotníku.","A level non-slip surface with space for the arms and for leg movement to both sides. A mat is optional; no ankle weight."]},"taxonomy":{"movements":["trunk_movement","joint"],"focus":["mobility","coordination"],"positions":["prone"],"supports":[],"equipmentRequirements":[["telo"]],"priority":2},"policy":{"id":"scorpion","measurementType":"REPS_ONLY","loadMode":"none","sideMode":"none","requirements":[["telo"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false},"art":{"appId":"scorpion","atlasId":"scorpion","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"d97da2c3eccb85df50dcfc6c52f1718406e05731f1ad4ade7f87942cd41952e1","thumb":"/unified-atlas/scorpion-22a859abb3664e80-thumb.webp","detail":"/unified-atlas/scorpion-ad6ff8f2d0ec09b9-detail.webp","inkThumb":"/unified-atlas/scorpion-f7042a79bcf0e8c9-inkThumb.webp","inkDetail":"/unified-atlas/scorpion-8ccd72fb2faedc16-inkDetail.webp","fillThumb":"/unified-atlas/scorpion-27691ddf092e1e29-fillThumb.webp","fillDetail":"/unified-atlas/scorpion-9d0ea89d117b1269-fillDetail.webp"},"sourceSha256":"d97da2c3eccb85df50dcfc6c52f1718406e05731f1ad4ade7f87942cd41952e1","contourOnly":true,"darkOutline":true},"libraryOrder":9003,"deliveryProfiles":{"96c73f27b0993731":{"fields":{"id":"scorpion","cz":"Škorpion","en":"Scorpion","pat":"mobilita","eq":["telo"],"measurementType":"REPS_ONLY","defaultRestSec":15,"unilateral":false,"sideMode":"none","focus":["Pomalý přenos pokrčené nohy, bez švihu a bez nuceného dosahu.","Move the bent leg across slowly, without momentum or forced reach."],"startPosition":["Lehni si na břicho, paže rozlož pohodlně do stran a opři je. Hlavu nech v pohodlné nízké poloze. Nech kolem sebe dost místa pro pohyb nohy.","Lie face down with the arms comfortably out to the sides and supported. Keep the head in a comfortable low position. Leave enough space around you for the moving leg."],"execution":["Pokrč jedno koleno a pomalu veď patu přes druhou nohu směrem na opačnou stranu těla. Pánev se přitom otáčí; nepokoušej se pohyb izolovat jen do hrudníku. Vrať nohu pod kontrolou a vystřídej ji. Jeden přenos a návrat jedné nohy je jedno opakování pro novou sérii.","Bend one knee and slowly take the heel across the other leg toward the opposite side of the body. The pelvis turns with the movement; do not try to isolate it to the upper back. Return the leg with control, then switch. One crossing and return of one leg is one repetition for a new set."],"watchFor":["Horní část hrudníku a paže nech pohodlně opřené. Nešvihej nohou ani ji netlač silou k protější ruce či k podlaze. Zmenši rozsah, pokud se horní tělo výrazně odvaluje, cítíš tlak v bedrech nebo musíš zadržet dech.","Keep the upper chest and arms comfortably supported. Do not swing the leg or force it toward the opposite hand or the floor. Reduce the range if the upper body rolls substantially, the lower back feels compressed or you have to hold your breath."]},"progression":["Lehčí: menší přenos nohy a kratší série. Dále můžeš zpomalit návrat v témže pohodlném rozsahu. Větší rotace a dlouhá krajní výdrž nejsou povinné. Zapisovaný počet zahrnuje jednotlivé přenosy; rozdělení na levou a pravou nohu uveď v poznámce.","Easier: use a smaller leg crossing and a shorter set. You may then slow the return within the same comfortable range. More rotation and long end-range holds are not compulsory. The recorded count includes individual crossings; note the split between left and right legs."]}}},"ig28_crab_reach":{"id":"ig28_crab_reach","segment":"J","edits":{"exe":["Ponech obě chodidla a jednu dlaň na zemi. Zvedni pánev, otoč hrudník a volnou paží dosáhni pohodlně nad hlavu. Pomalu vrať pánev i ruku. Zvednutí, dosah a návrat je jedno opakování na straně volné paže; proveď také druhou stranu.","Keep both feet and one palm grounded. Lift the pelvis, turn the chest and reach the free arm comfortably overhead. Lower the hips and hand slowly. One lift, reach and return is one repetition for the free arm; work the other side too."],"equipmentDetail":["Pevná neklouzavá plocha pro obě celá chodidla a opěrnou dlaň; volný prostor pro dosah. Poloha dlaně musí být pohodlná pro zápěstí. Bez přídavné zátěže; nestabilní nebo klouzající oporu nepoužívej.","A firm non-slip surface for both whole feet and the supporting palm, with room to reach. Place the palm in a position comfortable for the wrist. No added weight; avoid unstable or slippery supports."]},"taxonomy":{"movements":["trunk_movement","hip_extension","joint"],"focus":["mobility","coordination"],"positions":["reverse_support"],"supports":["hand_support"],"equipmentRequirements":[["telo"]],"priority":1},"policy":{"id":"ig28_crab_reach","measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"perSide","requirements":[["telo"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false,"sideMeaning":["Volná dosahující paže","Free reaching arm"]},"art":{"appId":"ig28_crab_reach","atlasId":"ig28_crab_reach","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"c992c60bde71426e238ce78f96af4246ab688952974fcb5bee839bdc57801e27","thumb":"/expansion-atlas/ig28_crab_reach-original-256.webp","detail":"/expansion-atlas/ig28_crab_reach-original-960.webp","inkThumb":"/expansion-atlas/ig28_crab_reach-ink-256.webp","inkDetail":"/expansion-atlas/ig28_crab_reach-ink-960.webp","fillThumb":"/expansion-atlas/ig28_crab_reach-fill-256.webp","fillDetail":"/expansion-atlas/ig28_crab_reach-fill-960.webp"},"sourceSha256":"c992c60bde71426e238ce78f96af4246ab688952974fcb5bee839bdc57801e27","contourOnly":true,"darkOutline":true},"libraryOrder":9004,"deliveryProfiles":{"faa3f74c88f324bf":{"fields":{"id":"ig28_crab_reach","cz":"Krabí dosah nad hlavu","en":"Crab Reach","pat":"mobilita","eq":["telo"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":60,"unilateral":true,"sideMode":"perSide","focus":["Dvě chodidla a jedna dlaň nesou tělo.","Support the body on two feet and one palm."],"startPosition":["Sedni s pokrčenými koleny, chodidla opři celou plochou. Dlaně dej za tělo do pohodlné polohy a pánev nadlehči.","Sit with bent knees and feet flat. Place the palms comfortably behind you and lift the hips slightly."],"execution":["Ponech obě chodidla a jednu dlaň na zemi. Zvedni pánev, otoč hrudník a volnou paží dosáhni pohodlně nad hlavu. Pomalu vrať pánev i ruku. Zvednutí, dosah a návrat je jedno opakování na straně volné paže; proveď také druhou stranu.","Keep both feet and one palm grounded. Lift the pelvis, turn the chest and reach the free arm comfortably overhead. Lower the hips and hand slowly. One lift, reach and return is one repetition for the free arm; work the other side too."],"watchFor":["Rameno opěrné ruky nepropadá, chodidla se nezvedají. Nezakláněj prudce hlavu a nedoháněj dosah prohnutím beder.","Keep the supporting shoulder active and both feet down. Avoid throwing the head back or forcing the reach through the lower back."]},"progression":["Lehčí: nízký obrácený stůl na obou rukách. Těžší: větší pohodlný dosah a krátká pauza; obě chodidla zůstávají na zemi.","Easier: a low reverse table on both hands. Harder: a larger comfortable reach and brief pause, keeping both feet grounded."]}}},"ig26_wall_elbow_lat":{"id":"ig26_wall_elbow_lat","segment":"J","edits":{"exe":["Mírně ustup chodidly a posuň pánev dozadu. Hrudník nech klesnout mezi paže jen do mírného tahu. Klidně dýchej. Zapisuj sekundy této kontrolované výdrže obou paží současně, bez času přípravy a návratu; pak se pomalu narovnej.","Step slightly back and move the hips away. Lower the chest between the arms only to a mild stretch and breathe steadily. Record seconds of this controlled hold with both arms together, excluding setup and return; then slowly stand upright."],"equipmentDetail":["Pevná neklouzavá zeď pro oba lokty a podlaha, na které neujíždějí chodidla. Případné měkké podložení loktů musí držet na místě. Nejde o vis z hrazdy ani oporu rukou o vysokou lavici.","A firm non-slip wall for both elbows and a floor where the feet will not slide. Any soft elbow padding must stay in place. This is not a hanging stretch from a bar or a hands-on-high-bench version."]},"taxonomy":{"movements":["position","joint"],"focus":["mobility"],"positions":["standing"],"supports":["wall","forearm_support"],"equipmentRequirements":[["zed"]],"priority":1},"policy":{"id":"ig26_wall_elbow_lat","measurementType":"DURATION","loadMode":"none","sideMode":"none","requirements":[["zed"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false},"art":{"appId":"ig26_wall_elbow_lat","atlasId":"ig26_wall_elbow_lat","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"9e8f00acad3ed4c7a053406be8a8ee0c86dd3f9e6721e69cb4e64e5ddaa570ee","thumb":"/expansion-atlas/ig26_wall_elbow_lat-original-256.webp","detail":"/expansion-atlas/ig26_wall_elbow_lat-original-960.webp","inkThumb":"/expansion-atlas/ig26_wall_elbow_lat-ink-256.webp","inkDetail":"/expansion-atlas/ig26_wall_elbow_lat-ink-960.webp","fillThumb":"/expansion-atlas/ig26_wall_elbow_lat-fill-256.webp","fillDetail":"/expansion-atlas/ig26_wall_elbow_lat-fill-960.webp"},"sourceSha256":"9e8f00acad3ed4c7a053406be8a8ee0c86dd3f9e6721e69cb4e64e5ddaa570ee","contourOnly":true,"darkOutline":true},"libraryOrder":9005,"deliveryProfiles":{"ccbb43b6f800281f":{"fields":{"id":"ig26_wall_elbow_lat","cz":"Protažení ramen s lokty opřenými o zeď","en":"Wall Elbow-Supported Shoulder-Flexion Stretch","pat":"mobilita","eq":["zed"],"measurementType":"DURATION","defaultRestSec":60,"unilateral":false,"sideMode":"none","focus":["Prodluž prostor mezi lokty a pánví bez prohnutí beder.","Lengthen between elbows and pelvis without arching the back."],"startPosition":["Stůj čelem ke zdi a opři o ni oba lokty zhruba ve výši hlavy, na šířku ramen. Ohnuté paže nech směřovat rukama za temeno.","Face a wall with both elbows supported around head height, shoulder-width apart. Bend the arms so the hands rest behind the crown."],"execution":["Mírně ustup chodidly a posuň pánev dozadu. Hrudník nech klesnout mezi paže jen do mírného tahu. Klidně dýchej. Zapisuj sekundy této kontrolované výdrže obou paží současně, bez času přípravy a návratu; pak se pomalu narovnej.","Step slightly back and move the hips away. Lower the chest between the arms only to a mild stretch and breathe steadily. Record seconds of this controlled hold with both arms together, excluding setup and return; then slowly stand upright."],"watchFor":["Netlač rukama na hlavu a nezalamuj bedra. Lokty se nesmějí po zdi smýkat; při tlaku v rameni zmenši rozsah.","Do not pull on the head or arch the lower back. Prevent elbows from sliding; reduce the range if the shoulder feels pinched."]},"progression":["Lehčí: menší ústup a předklon. Těžší: o trochu větší rozsah při stejném postavení žeber a pánve. Hlubší záklon není pokračováním tohoto cviku.","Easier: less step-back and hinge. Harder: slightly more range with ribs and pelvis still controlled. A deeper backbend is not the progression."]}}},"scap":{"id":"scap","segment":"R","edits":{},"taxonomy":{},"policy":{"id":"scap","viewOnly":true,"measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"none","blockedMotionSources":[]},"art":{"appId":"scap","atlasId":"scap","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"f4840b4b0dee6e4652d954fc20f9fc02f18b457e324cca0e8dce92e8df5e473d","thumb":"/unified-atlas/scap-48bef3bfc11420cf-thumb.webp","detail":"/unified-atlas/scap-de45a6b5931c60f0-detail.webp","inkThumb":"/unified-atlas/scap-1e769058dd0d08fb-inkThumb.webp","inkDetail":"/unified-atlas/scap-f3a5e5e9b7f8a5f9-inkDetail.webp","fillThumb":"/unified-atlas/scap-bf0f964db87fb822-fillThumb.webp","fillDetail":"/unified-atlas/scap-948d9210a1f81b6a-fillDetail.webp"},"sourceSha256":"f4840b4b0dee6e4652d954fc20f9fc02f18b457e324cca0e8dce92e8df5e473d","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"7001485a53ad436b":{"fields":{"id":"scap","cz":"Lopatkové přítahy ve visu","en":"Scapular Pull-Up","pat":"tah","eq":["hrazda"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":20,"unilateral":false,"sideMode":"none","focus":["Pohyb ramen a lopatek ve visu s nataženými lokty.","A shoulder and shoulder-blade movement while hanging with straight elbows."],"startPosition":["Na pevné hrazdě zaujmi vis pohodlným nadhmatem s nataženými lokty a chodidly bez opory. Měj bezpečný způsob nástupu i ukončení visu.","Hang from a securely fixed bar with a comfortable overhand grip, straight elbows and feet unsupported. Use a safe way to enter and exit the hang."],"execution":["Bez ohýbání loktů jemně stáhni ramena od uší, takže se tělo mírně zvedne. Krátce zastav a kontrolovaně se vrať. Lopatky násilím nesvírej k sobě.","Without bending the elbows, gently draw the shoulders away from the ears so the body rises slightly. Pause briefly and return under control. Do not force the shoulder blades together."],"watchFor":["Pohyb je malý a kontrolovaný, bez švihu či předsunutí hlavy. Nevis přes bolest v rameni nebo slábnoucí úchop.","Keep the movement small and controlled, without swinging or jutting the head forward. Do not continue hanging through shoulder pain or a failing grip."]},"progression":["Nejprve zvládni pohodlný vis, malý pohyb a kontrolovaný návrat. Potom lze prodloužit krátkou pauzu či počet kvalitních opakování podle plánu; přechod na shyb není povinný.","First control a comfortable hang, a small movement and the return. Then increase the brief pause or the number of controlled repetitions as prescribed; progressing to a pull-up is optional."]}}},"scapush":{"id":"scapush","segment":"R","edits":{},"taxonomy":{},"policy":{"id":"scapush","viewOnly":true,"measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"none","blockedMotionSources":["/exercise-motion/scapush-db80d9ffd21fd081.mp4"]},"art":{"appId":"scapush","atlasId":"scapush","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"a72d6136405da6c09edfb88227f2f7fc0371ef749797066b2c0821cd74d628a8","thumb":"/unified-atlas/scapush-70bc599d4efef138-thumb.webp","detail":"/unified-atlas/scapush-8163a4ec893377d0-detail.webp","inkThumb":"/unified-atlas/scapush-b7b3735a4b2dad0b-inkThumb.webp","inkDetail":"/unified-atlas/scapush-69870c598d80a6dc-inkDetail.webp","fillThumb":"/unified-atlas/scapush-95e32316eea6d395-fillThumb.webp","fillDetail":"/unified-atlas/scapush-e206f6a47f516b18-fillDetail.webp"},"sourceSha256":"a72d6136405da6c09edfb88227f2f7fc0371ef749797066b2c0821cd74d628a8","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"eb63bfbe71464721":{"fields":{"id":"scapush","cz":"Lopatkový klik","en":"Scapula Push-Up","pat":"tlak","eq":["telo"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":60,"unilateral":false,"sideMode":"none","focus":["Paže nech pohodlně natažené. Malý pohyb vychází z lopatek po hrudníku.","Keep the arms comfortably straight. The small movement comes from the shoulder blades moving around the rib cage."],"startPosition":["Zaujmi pevný vzpor na dlaních a předních částech chodidel. Lokty nech pohodlně natažené a hlavu v prodloužení trupu.","Take a controlled high plank on palms and forefeet. Keep the elbows comfortably straight and the head aligned with the trunk."],"execution":["Hrudník klesá mezi lopatky, pak zatlač zem pryč a lopatky roztáhni. Malý, pomalý pohyb.","The chest sinks between the blades, then push the ground away and spread them. Small, slow movement."],"watchFor":["Lokty drž propnuté a boky nehybné. Pohyb je malý a kontrolovaný.","Keep the elbows straight and the hips still. Use a small, controlled movement."]},"progression":["Lehčí: opora kolen nebo dlaně na pevné zvýšené ploše. Uprav malý rozsah, tempo nebo pauzu při klidné poloze trupu.","Easier: support the knees or place the palms on a stable raised surface. Adjust the small range, tempo or pause while keeping the trunk controlled."]}}},"facepull":{"id":"facepull","segment":"R","edits":{},"taxonomy":{},"policy":{"id":"facepull","viewOnly":true,"measurementType":"WEIGHT_REPS","loadMode":"ext","sideMode":"none","blockedMotionSources":[]},"art":{"appId":"facepull","atlasId":"facepull","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"0d92b34a491504a0cf8e63868b661d5b7914e06e9f03e21c56cfea02917c1878","thumb":"/unified-atlas/facepull-f097c685da9d1462-thumb.webp","detail":"/unified-atlas/facepull-62685a4935e967d1-detail.webp","inkThumb":"/unified-atlas/facepull-ce1a8bc6b22a6a7a-inkThumb.webp","inkDetail":"/unified-atlas/facepull-034e69871f89cf80-inkDetail.webp","fillThumb":"/unified-atlas/facepull-13f734db40d357b8-fillThumb.webp","fillDetail":"/unified-atlas/facepull-d927a738e77c9be4-fillDetail.webp"},"sourceSha256":"0d92b34a491504a0cf8e63868b661d5b7914e06e9f03e21c56cfea02917c1878","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"23c60a5eb3f6743a":{"fields":{"id":"facepull","cz":"Přítah gumy k obličeji","en":"Band Face Pull","pat":"tah","eq":["guma","kladka"],"measurementType":"WEIGHT_REPS","defaultRestSec":90,"unilateral":false,"sideMode":"none","focus":["Plynulý tah gumy k obličeji při klidném trupu a pohodlném vedení loktů.","Pull the band smoothly toward the face with a steady trunk and comfortable elbow path."],"startPosition":["Gumu bezpečně upevni do vhodné kotvy přibližně ve výšce obličeje. Postav se čelem ke kotvě, uchop gumu oběma rukama a ustup do lehkého napětí.","Secure the band to a suitable anchor around face height. Face the anchor, hold the band with both hands and step back to create light tension."],"execution":["Přitahuj gumu k obličeji a lokty veď pohodlně do stran a dozadu. Kontrolovaně natáhni paže a vrať se bez zaklánění.","Pull the band toward the face, guiding the elbows comfortably outward and backward. Extend the arms under control and return without leaning back."],"watchFor":["Před sérií zkontroluj gumu i kotvu. Nevnucuj ramenům polohu loktů u uší; zvol odpor a rozsah, které udržíš pod kontrolou.","Check the band and anchor before the set. Do not force the elbows beside the ears; choose resistance and range you can control."]},"progression":["Odpor měň typem gumy nebo vzdáleností od kotvy. Nastavení si poznamenej, aby šly série porovnávat.","Adjust resistance through band choice or distance from the anchor. Note the setup so sets can be compared consistently."]}}},"ytw":{"id":"ytw","segment":"R","edits":{},"taxonomy":{},"policy":{"id":"ytw","viewOnly":true,"measurementType":"REPS_ONLY","loadMode":"none","sideMode":"none","blockedMotionSources":[]},"art":{"appId":"ytw","atlasId":"ytw","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"e45473543837d2b1398f9ca91e5aa9517bc2c0592bac7bff19e0d269799c083e","thumb":"/unified-atlas/ytw-5b4bf88c1c27c454-thumb.webp","detail":"/unified-atlas/ytw-b6d0b5bbdff82d84-detail.webp","inkThumb":"/unified-atlas/ytw-8c33626c33af0aad-inkThumb.webp","inkDetail":"/unified-atlas/ytw-96c5d8cbc8f4deac-inkDetail.webp","fillThumb":"/unified-atlas/ytw-953dbb42e0431914-fillThumb.webp","fillDetail":"/unified-atlas/ytw-49f1cc7878032510-fillDetail.webp"},"sourceSha256":"e45473543837d2b1398f9ca91e5aa9517bc2c0592bac7bff19e0d269799c083e","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"c2979dfe75a0b2b0":{"fields":{"id":"ytw","cz":"Y-T-W na břiše","en":"Prone Y-T-W","pat":"tah","eq":["telo"],"measurementType":"REPS_ONLY","defaultRestSec":60,"unilateral":false,"sideMode":"none","focus":["Kontroluj polohu ramen a lopatek při změně tvaru paží.","Control the shoulders and shoulder blades as the arm shape changes."],"startPosition":["Lehni si na břicho a čelo pohodlně opři o podložku; podle potřeby použij nízkou měkkou oporu. Krk nech v prodloužení trupu.","Lie prone with the forehead comfortably supported on the floor or a low soft support as needed. Keep the neck aligned with the trunk."],"execution":["Lehce zvedni paže šikmo nad hlavu do Y, potom do stran do T a nakonec s pokrčenými lokty do W. V každé poloze vydrž 2 sekundy a pohybuj se bez švihu.","Gently lift the arms diagonally overhead into a Y, then out to the sides into a T, and finally into a W with bent elbows. Hold each position for 2 seconds and move without swinging."],"watchFor":["Nezakláněj krk ani nezvedej hrudník, abys dostal paže výš. Rozsah přizpůsob ovládanému pohybu ramen a lopatek.","Do not extend the neck or lift the chest to raise the arms higher. Match the range to controlled shoulder and shoulder-blade movement."]},"progression":["Tato karta používá vlastní váhu paží. Nejprve ovládni jednotlivé polohy; potom lze podle zadání zpomalit přechody nebo upravit délku pauzy.","This card uses the weight of the arms. First control each position; then slow the transitions or adjust the pause length as prescribed."]}}},"tbridge":{"id":"tbridge","segment":"R","edits":{},"taxonomy":{},"policy":{"id":"tbridge","viewOnly":true,"measurementType":"REPS_ONLY","loadMode":"none","sideMode":"none","blockedMotionSources":[]},"art":{"appId":"tbridge","atlasId":"tbridge","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"04155718b3d1f99bd6afa65c71283cf1bd2671960646b9a9759bcb26ea3217e5","thumb":"/unified-atlas/tbridge-5c53ba87887fdf46-thumb.webp","detail":"/unified-atlas/tbridge-bb75f878892bc9dc-detail.webp","inkThumb":"/unified-atlas/tbridge-0fe1f9c5f1264f46-inkThumb.webp","inkDetail":"/unified-atlas/tbridge-d6fe6511dc434c12-inkDetail.webp","fillThumb":"/unified-atlas/tbridge-04929c7c9d2e513d-fillThumb.webp","fillDetail":"/unified-atlas/tbridge-5f64a12e7cb51b75-fillDetail.webp"},"sourceSha256":"04155718b3d1f99bd6afa65c71283cf1bd2671960646b9a9759bcb26ea3217e5","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"28c636ecb8e3c4be":{"fields":{"id":"tbridge","cz":"Hrudní rotace v tříbodovém mostu","en":"Three-Point Bridge Reach","pat":"mobilita","eq":["telo"],"measurementType":"REPS_ONLY","defaultRestSec":15,"unilateral":false,"sideMode":"none","focus":["Jedno zvednutí s dosahem a návratem počítej jako jedno opakování celkem. Střídej strany; pokud plán určuje počet na stranu, řiď se jeho zadáním.","Count one lift, reach and return as one total repetition. Alternate sides; if the plan specifies repetitions per side, follow that prescription."],"startPosition":["Sedni si s pokrčenými koleny a chodidly na zemi. Dlaně opři za tělem v poloze příjemné pro zápěstí. Nejdřív ověř, že se dokážeš opřít o ruce a zvednout pánev bez bolesti.","Sit with bent knees and feet on the floor. Plant the palms behind you in a comfortable wrist position. First check that you can support yourself on the hands and lift the pelvis without pain."],"execution":["Zatlač jednou dlaní a oběma chodidly do země, zvedni pánev a druhou paží dosáhni přes tělo nad hlavu. Hrudník se řízeně otáčí. Vrať ruku, polož pánev a potom vystřídej strany.","Press through one palm and both feet, lift the pelvis and reach the other arm across the body and overhead. Rotate the chest under control. Return the hand, lower the pelvis and then switch sides."],"watchFor":["Nepřetáčej se přes rameno ani neodvaluj hlavu na zem. Rozsah zkrať při ztrátě opory; při bolesti ramene, zápěstí nebo zad pokus kontrolovaně ukonči.","Do not roll over the shoulder or place the head on the floor. Reduce range if support is lost; stop the attempt under control if the shoulder, wrist or back hurts."]},"progression":["Lehčí: zvednutí pánve s oběma dlaněmi na zemi a bez dosahu paže. Dosah rozšiřuj jen při jisté opoře a pohodlném pohybu.","Easier: lift the pelvis with both palms grounded and without the arm reach. Extend the reach only with secure support and comfortable movement."]}}},"scapdip":{"id":"scapdip","segment":"R","edits":{},"taxonomy":{},"policy":{"id":"scapdip","viewOnly":true,"measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"none","blockedMotionSources":[]},"art":{"appId":"scapdip","atlasId":"scapdip","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"b09ee947b4950e4c15de6d0d0630570d3c0caa06719c9c79d177f1d645597e17","thumb":"/unified-atlas/scapdip-573b10702bdf54c3-thumb.webp","detail":"/unified-atlas/scapdip-b833669b8ebfe691-detail.webp","inkThumb":"/unified-atlas/scapdip-722ea464ab9ac261-inkThumb.webp","inkDetail":"/unified-atlas/scapdip-3e9661f8fb22419e-inkDetail.webp","fillThumb":"/unified-atlas/scapdip-31f93aae042b1687-fillThumb.webp","fillDetail":"/unified-atlas/scapdip-786fda3546d76af3-fillDetail.webp"},"sourceSha256":"b09ee947b4950e4c15de6d0d0630570d3c0caa06719c9c79d177f1d645597e17","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"76531bc20b122407":{"fields":{"id":"scapdip","cz":"Lopatkové zdvihy ve vzporu na bradlech","en":"Parallel-Bar Scapular Shrugs","pat":"tlak","eq":["bradla","kruhy"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":60,"unilateral":false,"sideMode":"none","focus":["Pohyb lopatek ve vzporu při rovné paži; nejde o plný dip s ohýbáním loktů.","Move the shoulder blades in support with straight arms; this is not a full dip with elbow bending."],"startPosition":["Na stabilních bradlech zaujmi klidný vzpor s rovnými pažemi a chodidly mimo podlahu. Drž pevný úchop a připrav si kontrolovaný sestup z bradel.","Enter steady straight-arm support on stable parallel bars with the feet clear of the floor. Maintain a firm grip and prepare a controlled exit."],"execution":["S rovnými lokty nech tělo mírně klesnout a ramena přiblížit k uším. Potom tlakem do bradel tělo opět nadzvedni a ramena od uší oddal. Pohyb zůstává malý a plynulý.","With the elbows straight, let the body lower slightly as the shoulders move toward the ears. Then press into the bars to lift the body and move the shoulders away from the ears. Keep the movement small and smooth."],"watchFor":["Nepropadej pasivně mezi ramena a nevynucuj krajní polohu loktů. Při bolesti nebo ztrátě opory sérii ukonči.","Do not collapse passively between the shoulders or force the elbows into an end position. End the set if pain or loss of support occurs."]},"progression":["Měň počet plynulých opakování v malém rozsahu. Přechod na kruhy ani plný dip není povinný; výdrž ve vzporu je odlišný úkol.","Adjust the number of smooth repetitions within a small range. Rings or a full dip are not compulsory progressions; a static support hold is a different task."]}}},"vi_scap":{"id":"vi_scap","segment":"R","edits":{},"taxonomy":{},"policy":{"id":"vi_scap","viewOnly":true,"measurementType":"WEIGHT_REPS","loadMode":"ext","sideMode":"none","blockedMotionSources":[]},"art":{"appId":"vi_scap","atlasId":"vi_scap","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"d81a552b7bf5672d0b4c275ffa0b43ced7f08d0906344086266a6480af666143","thumb":"/unified-atlas/vi_scap-137f02f99b8982a9-thumb.webp","detail":"/unified-atlas/vi_scap-25cc4dd3f087e070-detail.webp","inkThumb":"/unified-atlas/vi_scap-627622ffe8f67110-inkThumb.webp","inkDetail":"/unified-atlas/vi_scap-104f0b04cc5231c7-inkDetail.webp","fillThumb":"/unified-atlas/vi_scap-18d45d2e0a4aa4ae-fillThumb.webp","fillDetail":"/unified-atlas/vi_scap-09fde161e56550ad-fillDetail.webp"},"sourceSha256":"d81a552b7bf5672d0b4c275ffa0b43ced7f08d0906344086266a6480af666143","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"44057ff6f9cef26b":{"fields":{"id":"vi_scap","cz":"Stabilizátory lopatky","en":"Scapular stabilizers","pat":"tah","eq":["guma","kladka"],"measurementType":"WEIGHT_REPS","defaultRestSec":60,"unilateral":false,"sideMode":"none","focus":["Vyber konkrétní cvik pro práci lopatek a řiď se jeho popisem i způsobem záznamu.","Select a specific scapular-control exercise and follow its instructions and recording method."],"startPosition":["Poloha a opora závisejí na zvoleném cviku; tato programová položka zahrnuje varianty vleže na břiše i vsedě.","Position and support depend on the chosen exercise; this programme entry includes prone and seated variations."],"execution":["Proveď konkrétní variantu uvedenou v plánu. Pohyb lopatek sladíš s pohybem paží podle jejího návodu; bezodporová simulace a stahování s odporem nejsou stejný úkol.","Perform the specific variation named in the plan. Coordinate the shoulder blades with the arms as instructed for that variation; an unloaded simulation and a resisted pulldown are different tasks."],"watchFor":["Jde o programovou šablonu, ne o jedno přesné provedení. Potřebné pomůcky a rozsah určuje vybraný cvik; ramena nemusíš po celou dobu držet násilně dole a vzadu.","This is a programme template, not one fixed execution. The chosen exercise determines equipment and range; the shoulders need not be forced down and back throughout."]},"progression":["Obtížnost upravuj podle konkrétní varianty a zadání plánu. Druh odporu a nastavení zapisuj konzistentně; údaje různých variant nepovažuj automaticky za srovnatelné.","Adjust difficulty for the specific variation and plan. Record resistance type and setup consistently; do not automatically compare results from different variations."]}}},"ex26_cable_facepull":{"id":"ex26_cable_facepull","segment":"R","edits":{},"taxonomy":{},"policy":{"id":"ex26_cable_facepull","viewOnly":true,"measurementType":"WEIGHT_REPS","loadMode":"ext","sideMode":"none","blockedMotionSources":[]},"art":{"appId":"ex26_cable_facepull","atlasId":"ex26_cable_facepull","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"19663ebe167484031428de05e50125447ea02bc36ba6f34a475020f94ebfb39b","thumb":"/expansion-atlas/ex26_cable_facepull-original-256.webp","detail":"/expansion-atlas/ex26_cable_facepull-original-960.webp","inkThumb":"/expansion-atlas/ex26_cable_facepull-ink-256.webp","inkDetail":"/expansion-atlas/ex26_cable_facepull-ink-960.webp","fillThumb":"/expansion-atlas/ex26_cable_facepull-fill-256.webp","fillDetail":"/expansion-atlas/ex26_cable_facepull-fill-960.webp"},"sourceSha256":"19663ebe167484031428de05e50125447ea02bc36ba6f34a475020f94ebfb39b","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"2784d71e433f2e86":{"fields":{"id":"ex26_cable_facepull","cz":"Přítah lana na kladce k obličeji","en":"Cable Rope Face Pull","pat":"tah","eq":["kladka"],"measurementType":"WEIGHT_REPS","defaultRestSec":120,"unilateral":false,"sideMode":"none","focus":["Přitahuj lano k čelu a jeho konce od sebe.","Pull the rope toward the forehead while separating its ends."],"startPosition":["Lano nastav zhruba do výšky obličeje. Postav se stabilně, paže směřují ke kladce a žebra jsou nad pánví.","Set the rope around face height. Stand securely with arms reaching toward the pulley and ribs over the pelvis."],"execution":["Přitahuj lano k čelu a jeho konce od sebe. Lokty veď pohodlně do stran. Vracej pomalu bez pohybu trupu.","Pull the rope toward the forehead while separating its ends. Let the elbows travel comfortably outward. Return slowly without moving the torso."],"watchFor":["Nekrč ramena k uším a nelámej zápěstí. Rozsah zevní rotace přizpůsob rameni, ne představě o správném úhlu.","Do not shrug or bend the wrists sharply. Match external-rotation range to the shoulder rather than forcing a prescribed angle."]},"progression":["Odpor, počet opakování nebo délku krátké pauzy měň podle kontroly pohybu bez zaklánění. Guma je jiná varianta vybavení, nikoli automaticky lehčí odpor.","Adjust resistance, repetition count or a brief pause according to movement control without leaning back. A band is a different equipment option, not automatically lighter resistance."]}}},"ex26_kneel_reversefly":{"id":"ex26_kneel_reversefly","segment":"R","edits":{},"taxonomy":{},"policy":{"id":"ex26_kneel_reversefly","viewOnly":true,"measurementType":"WEIGHT_REPS","loadMode":"ext","sideMode":"none","familyOverride":"kneeling_cable_reverse_fly","blockedMotionSources":[]},"art":{"appId":"ex26_kneel_reversefly","atlasId":"ex26_kneel_reversefly","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"553daf72860b7f0eca8b5560d166f1458eb0edcc3dd963d0ef32f59d32599895","thumb":"/expansion-atlas/ex26_kneel_reversefly-audit20261013-original-256.webp","detail":"/expansion-atlas/ex26_kneel_reversefly-audit20261013-original-960.webp","inkThumb":"/expansion-atlas/ex26_kneel_reversefly-audit20261013-ink-256.webp","inkDetail":"/expansion-atlas/ex26_kneel_reversefly-audit20261013-ink-960.webp","fillThumb":"/expansion-atlas/ex26_kneel_reversefly-audit20261013-fill-256.webp","fillDetail":"/expansion-atlas/ex26_kneel_reversefly-audit20261013-fill-960.webp"},"sourceSha256":"553daf72860b7f0eca8b5560d166f1458eb0edcc3dd963d0ef32f59d32599895","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"4c4390629fca4526":{"fields":{"id":"ex26_kneel_reversefly","cz":"Rozpažování šikmo dolů v kleku na kladce","en":"Kneeling Cable Reverse Fly","pat":"tah","eq":["kladka"],"measurementType":"WEIGHT_REPS","defaultRestSec":120,"unilateral":false,"sideMode":"none","focus":["Veď paže širokým obloukem dozadu a dolů k bokům, potom se pomalu vrať.","Sweep arms in a wide arc backward and downward toward the hips, then return slowly."],"startPosition":["Klekni čelem ke dvěma výškově nastavitelným kladkám, každé s jednoručním madlem přibližně ve výšce ramen. Uchop obě madla před tělem a lokty nech mírně povolené; zvol lehký odpor a stabilní klek.","Kneel facing two height-adjustable pulleys, each with a single handle set around shoulder height. Hold both handles in front with softly extended elbows; use light resistance and a stable kneeling position."],"execution":["Veď paže širokým obloukem dozadu a dolů k bokům. Pomalu vrať rukojeti před sebe.","Sweep arms in a wide arc backward and downward toward the hips, then return slowly."],"watchFor":["Nepřecházej do záklonu a nepřitahuj rukojeti ohýbáním loktů.","Do not lean backward or turn the motion into an elbow-driven row."]},"progression":["Lehčí: menší odpor a kratší oblouk. Těžší: krátká pauza u boků nebo mírně vyšší odpor.","Easier: reduce resistance and arc length. Harder: pause beside the hips or slightly increase resistance."]}}},"ig27_pushup_plus":{"id":"ig27_pushup_plus","segment":"R","edits":{},"taxonomy":{},"policy":{"id":"ig27_pushup_plus","viewOnly":true,"measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"none","blockedMotionSources":[]},"art":{"appId":"ig27_pushup_plus","atlasId":"ig27_pushup_plus","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"9e319d8ddd041c26e56ff529c92a74654af9202414e39b8cbdbe5a8a6128a9b0","thumb":"/expansion-atlas/ig27_pushup_plus-original-256.webp","detail":"/expansion-atlas/ig27_pushup_plus-original-960.webp","inkThumb":"/expansion-atlas/ig27_pushup_plus-ink-256.webp","inkDetail":"/expansion-atlas/ig27_pushup_plus-ink-960.webp","fillThumb":"/expansion-atlas/ig27_pushup_plus-fill-256.webp","fillDetail":"/expansion-atlas/ig27_pushup_plus-fill-960.webp"},"sourceSha256":"9e319d8ddd041c26e56ff529c92a74654af9202414e39b8cbdbe5a8a6128a9b0","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"84ee291751b3cec5":{"fields":{"id":"ig27_pushup_plus","cz":"Klik s dotažením lopatek do protrakce","en":"Push-Up Plus","pat":"tlak","eq":["telo"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":60,"unilateral":false,"sideMode":"none","focus":["Jeden celý klik a následné krátké odtlačení přes lopatky tvoří jedno opakování.","One full push-up followed by the short scapular reach counts as one repetition."],"startPosition":["Začni ve vysokém vzporu s dlaněmi přibližně pod rameny. Opři se o přední části chodidel, zpevni trup a nech hlavu v jeho prodloužení.","Begin in a high plank with palms roughly below the shoulders. Support yourself on the forefeet, brace the trunk and keep the head aligned with it."],"execution":["Pokrč lokty a spusť hrudník mezi ruce. Vytlač se zpět do natažených paží. Potom ještě odtlač podlahu, aby se lopatky rozešly po hrudníku; teprve poté začni další klik.","Bend the elbows and lower the chest between the hands. Press back to straight arms. Then push the floor away a little farther so the shoulder blades spread around the rib cage; only then begin the next push-up."],"watchFor":["Lokty veď šikmo vzad, ne přímo do stran. Závěrečný pohyb vychází z lopatek: nezvedej pánev do střechy, nepropadej v bedrech a nezalamuj krk.","Angle the elbows backward rather than directly sideways. The final movement comes from the shoulder blades: do not pike the hips, sag through the lower back or bend the neck sharply."]},"progression":["Lehčí: stejný klik s dlaněmi na pevné vyšší opoře; pro nácvik závěru dělej jen lopatkové kliky. Těžší: zpomal spouštění a krátce vydrž v horním dotažení při stejné poloze trupu.","Easier: perform the same movement with hands on a stable raised support; practice just scapular push-ups to learn the finish. Harder: lower more slowly and pause briefly in the final reach with the trunk unchanged."]}}},"ig27_prone_pulldown":{"id":"ig27_prone_pulldown","segment":"R","edits":{},"taxonomy":{},"policy":{"id":"ig27_prone_pulldown","viewOnly":true,"measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"none","blockedMotionSources":["/exercise-motion/ig27_prone_pulldown-1d47d4e97ce40c4e.mp4"]},"art":{"appId":"ig27_prone_pulldown","atlasId":"ig27_prone_pulldown","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"08886878335f8f1cc111f5a455fea234c4624eaa144e2e1f0f89cc227c70e081","thumb":"/expansion-atlas/ig27_prone_pulldown-original-256.webp","detail":"/expansion-atlas/ig27_prone_pulldown-original-960.webp","inkThumb":"/expansion-atlas/ig27_prone_pulldown-ink-256.webp","inkDetail":"/expansion-atlas/ig27_prone_pulldown-ink-960.webp","fillThumb":"/expansion-atlas/ig27_prone_pulldown-fill-256.webp","fillDetail":"/expansion-atlas/ig27_prone_pulldown-fill-960.webp"},"sourceSha256":"08886878335f8f1cc111f5a455fea234c4624eaa144e2e1f0f89cc227c70e081","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"bf10ac419cee91ef":{"fields":{"id":"ig27_prone_pulldown","cz":"Přitahování loktů v lehu na břiše bez zátěže","en":"Prone Bodyweight Pull-Down","pat":"tah","eq":["telo"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":60,"unilateral":false,"sideMode":"none","focus":["Pohybuj pažemi, nohy a pánev nech opřené.","Move the arms while keeping the legs and pelvis grounded."],"startPosition":["Lehni si na břicho a natáhni paže před hlavu. Nohy i pánev nech na zemi, čelo těsně nad podložkou a pohled dolů.","Lie face down and reach the arms forward beyond the head. Keep the legs and pelvis grounded, with the forehead just above the surface and gaze downward."],"execution":["Paže lehce odlehči od země. Pokrč lokty a veď je šikmo k bokům do tvaru W. Pomalu znovu natáhni paže před sebe, aniž bys zvedal nohy nebo výrazně zakláněl trup.","Lift the arms slightly from the floor. Bend the elbows and draw them diagonally toward the sides into a W shape. Slowly reach forward again without lifting the legs or markedly extending the trunk."],"watchFor":["Nezvedej bradu a netlač ramena násilně dolů. Paže se pohybují jen v rozsahu, který zvládneš bez prohnutí v bedrech. Jde o řízení pohybu, ne o silové přitahování velké zátěže.","Do not lift the chin or force the shoulders downward. Move only through the range you can control without arching the lower back. This is movement-control practice, not a heavy pulling exercise."]},"progression":["Lehčí: kratší dosah a položení paží mezi opakováními; čelo může spočívat na tenkém ručníku. Těžší: pomalejší návrat a krátká pauza v natažení. Gumu přidávej až jako samostatnou odporovou variantu.","Easier: a shorter reach and resting the arms between repetitions; the forehead may rest on a thin towel. Harder: a slower return and a brief pause in the overhead reach. Add a band only as a separate resisted variation."]}}},"latiso":{"id":"latiso","segment":"R","edits":{},"taxonomy":{},"policy":{"id":"latiso","viewOnly":true,"measurementType":"WEIGHT_DURATION","loadMode":"ext","sideMode":"none","blockedMotionSources":[]},"art":{"appId":"latiso","atlasId":"latiso","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"ee41c700d6bb095fadc48333ae374fa5452008ca627268305544abf9ba228942","thumb":"/unified-atlas/latiso-b8e7676763b6c3e7-thumb.webp","detail":"/unified-atlas/latiso-c7ff6226da43ae49-detail.webp","inkThumb":"/unified-atlas/latiso-4ddf5d8a211a0877-inkThumb.webp","inkDetail":"/unified-atlas/latiso-fab40a38674d536b-inkDetail.webp","fillThumb":"/unified-atlas/latiso-45a08bf4b1922b8d-fillThumb.webp","fillDetail":"/unified-atlas/latiso-3d1af3d00b9030ac-fillDetail.webp"},"sourceSha256":"ee41c700d6bb095fadc48333ae374fa5452008ca627268305544abf9ba228942","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"c8dc5e7584a62959":{"fields":{"id":"latiso","cz":"Izometrický tah širokým zádovým","en":"Lat Iso Pull","pat":"tah","eq":["hrazda","zavazi"],"measurementType":"WEIGHT_DURATION","defaultRestSec":90,"unilateral":false,"sideMode":"none","focus":["Zatlač nataženou paží dolů a ucítíš záda. Aktivace.","Press down with a straight arm and feel the back. Activation."],"startPosition":["Ruce na tyči nebo stole, paže natažené, tělo zpevněné.","Hands on a bar or table, arms straight, body tight."],"execution":["Tlač dolů, jako bys chtěl tyč porazit k zemi. Drž 10 s před sériemi.","Press down as if driving the bar to the ground. Hold 10 s before your sets."],"watchFor":["Před zařazením upřesni konkrétní oporu, odpor a způsob zápisu. Popis neuvádí, co zde představuje hmotnost v kilogramech; neodhaduj ji ze síly tlaku do opory.","Before programming this entry, specify the support, resistance and recording convention. The description does not establish what the kilogram value represents; do not estimate it from how hard you press into the support."]},"progression":["Bez vyjasněného provedení neporovnávej zatížení s jinými cviky. Lopatkový shyb ani front lever nejsou povinným pokračováním této položky.","Until the setup is clarified, do not compare its load with other exercises. A scapular pull-up or front lever is not a required progression from this entry."]}}}};
